INSERT INTO `songs` (`id`, `title`, `author`, `music_sheet`, `verses`, `created_at`, `updated_at`, `category`) VALUES
	(93, 'ANDINO UWEM', 'pending', NULL, '<p><strong>1.</strong><br>Oboñ enyoñ y\'inyan y\'soñ, O! bo itoro Ye Uboñ</p>\n<p>Nam nnyin ima kpafi ikpoñ,</p>\n<p>O! Andino, O! Andino</p>\n<p><strong>Chorus:</strong></p>\n<p>O! Andino, (uwen ke mfon)</p>\n<p>O! Andino, (nson idem)</p>\n<p>O! Andino, (uwen ke mfon)</p>\n<p>O! Andino, (nfon idem)</p>\n<p>nam nyim ima kpa fi ikpon</p>\n<p>O! Andino, O! Andino</p>\n<p><strong>2.</strong><br>Afo Oboñ One uwem, Udia ñko yinsoñ idem</p>\n<p>Okoro ye kpukpru mm\'eno</p>\n<p>O! Andino, O! Andino</p>\n<p><strong>3.</strong><br>Afo one ikpom Eyen Eno okpon akan Efen</p>\n<p>man edifak nnyin mi k\'isan</p>\n<p>O! Andino, O! Andino</p>\n<p><strong>4.</strong><br>Se nnyin inode fi k\'ison, ikemkekem y\'ata uboñ</p>\n<p>edinode nnyin ke enyoñ</p>\n<p>O! Andino, O! Andino</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'praise'),
	(94, 'OJIMA CHEYI OJO', 'Jude Nnam', NULL, '<p><strong>Gloria:</strong></p>\n<p><strong>Ch.:</strong><br>Ojima Cheyi Ojo,  k’ida ta te</p>\n<p>Ojima Cheyi ojo k’ida ta te</p>\n<p>Ojima Cheyi Ojo,  k’ida ta te</p>\n<p>Ojima Cheyi ojo k’ida ta a te.</p>\n<p><strong>1.</strong><br>Kpai edebo k’iche we,</p>\n<p>Amen okpo kpa efile</p>\n<p>Awa k’ele we,</p>\n<p>Awa d’uguwe adojima uwe, Achugbe dewe</p>\n<p><strong>2.</strong><br>Todu Ojima lile ewe,</p>\n<p>Ada nyekwugwo we ondu</p>\n<p>k’ichojo Onuaye ojale</p>\n<p>ojo ata odobogagwu,</p>\n<p>kpai jesu Kristi ondu wa o makate eyi ata.</p>\n<p><strong>3.</strong><br>Ondu k’iche ojo,</p>\n<p>Omale eyi ojo,</p>\n<p>wekia k’ebiene</p>\n<p>Ile rinyo,</p>\n<p>gbaduwa ewa onduwa</p>\n<p><strong>4.</strong><br>Uwe k’egwugwuawato e ojo, cheju mo miwa ondu wa,</p>\n<p>Todu k’uwe kate ch’ina</p>\n<p>uwe, kate che ondu,</p>\n<p>uwe kate o, Jesu Kristi</p>\n<p><strong>5.</strong><br>Uwe kpai, Af’ina dama</p>\n<p>Ef’ojima Eyi ojo ata,</p>\n<p>Amen, Amen, Amen.</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'gloria'),
	(95, 'I BELIEVE IN ONE GOD, THE FATHER', 'pending', NULL, '<p><strong>Refrain:</strong></p>\n<p>I believe in one GOD the father</p>\n<p>Maker of heaven and earth</p>\n<p>Yes I believe in one Lord JESUS</p>\n<p>the only son of GOD</p>\n<p><strong>1.</strong><br>I believe in one God the almighty father creator of heaven and earth</p>\n<p>And in JESUS His only son our Lord who was conceived by the holy Spirit</p>\n<p><strong>2.</strong><br>Born of the virgin Mary suffered under pontius Pilate was crucified dead was buried</p>\n<p>He descended into hell on the third day He rose again from the dead.</p>\n<p><strong>3.</strong><br>He ascended into heaven sweated at the right hand of GOD the father almighty.</p>\n<p>From thence he shall come to judge the living and the dead I believe in the holy spirit.</p>\n<p><strong>4.</strong><br>The holy Catholic Church the communion of saints the forgiveness of sin.</p>\n<p>The resurrection of the body and life everlasting amen.</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'creed'),
	(96, 'BABA GBOPE WA.', 'pending', NULL, '<p>Chorus</p>\n<p>Gbore wa o, gbore wa o ele du ma re a wa so pe funore ofe re ni nu aiye wa baba adupe o gbore tia muwa  e ledumare..</p>\n<p>Verse 1</p>\n<p>Ope iyin ogo lamuwa siwaju re baba</p>\n<p>I jo ilu a torin lamuwa siwaju re..</p>\n<p>Baba lo ke.. baba lo ke</p>\n<p>Te wo gbope wa, te wo gbope wa</p>\n<p>Baba lo ke... baba lo ke gbore tiamuwa  e- leduma  re</p>\n<p>Chorus</p>\n<p>Gbore wa o, gbore wa o ele du ma re a wa so pe funore ofe re ni nu aiye wa baba adupe o gbore tia muwa  e ledumare..</p>\n<p>Verse 2.</p>\n<p>Oso funwa wi pe ninu ohun ko hun kia ma dupe</p>\n<p>O hun ti ba sele o si se po fun rere fun wa</p>\n<p>Adupe adupe  baba adupe o gbore tia muwa e_eledumare</p>\n<p>Verse 3</p>\n<p>Mo mo ri ri ore baba o iwo  ore mi ye  o sunmo  biwa gbo o jare</p>\n<p>Sunmo biwa gbo baba sere re funwa</p>\n<p>Sunmo biwa gbo baba sere re funwa</p>\n<p>Sunmo biwa gbo baba sere re funwa</p>\n<p>Ba ba wa gbo pe.</p>\n<p>Ya Ubangiji</p>\n<p>Ya Ubangiji kai mana jinkai</p>\n<p>(Ya Ubangiji) x2</p>\n<p>Kristo Kristo kai mana jinkai</p>\n<p>Ya Kristo, Ya Kristo</p>\n<p>Ya Ubangiji</p>\n<p>kai mana jinkai</p>\n<p>Kai mana jinkai</p>\n<p>Kai mana jinkai</p>\n<p>Awa L\'ulẹ Alo T\'unyi At\'atẹ</p>\n<p><strong>1.</strong><br>Awa l\'ulẹ a lo t\'unyi at\'atẹ</p>\n<p>unyi ọjamalia</p>\n<p>Awa jeju ọmọ ẹgba t\'ẹgba fai</p>\n<p>unyi ọjamalia</p>\n<p><strong>Ch:</strong><br>o: Unyi ọjamalia, unyi ọjamalia</p>\n<p>akanya takpa awa jeju ọmọ</p>\n<p>unyi ọjamalia</p>\n<p><strong>2.</strong><br>Awa dẹ kpai abo ufẹdọ w\'ọmọ</p>\n<p>unyi ọjamalia</p>\n<p>Af\'uja ilẹi du k\'ogwu lẹ takpa</p>\n<p><strong>3.</strong><br>Ondu Jisọs d\'uloko iñmi nwuwa</p>\n<p>unyi ọjamalia</p>\n<p>ẹgba k\'ọbata kpai akanya takpa</p>\n<p>unyi ọjamalia</p>\n<p><strong>4.</strong><br>Awa a k\'eli abo Kuma k\'ẹdọno</p>\n<p>unyi ọjamalia</p>\n<p>Eli lẹ a kọ ẹgba t\'ẹgba fai</p>\n<p>unyi ọjamalia</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'praise'),
	(97, 'OBI EZE CHUKWU', 'pending', NULL, '<p>Ebea bu ebe di egwu nkea b"ulo nso Chukwu onu Uzo nke eligwe aga akpo ya obi eze Chukwu di nso</p>\n<p><strong>1.</strong><br>O Nna ji Ike Nile anyi abiago ikpo isi ala Nye<br>Gi, meere anyi Ebere anyi biara nobi gi Chukwu<br>2<br>Anyi biara nihu gi Chineke inye gi ekele kwesiri gi , Gee nti Nuru ekpere anyi, anyi biara nobi gi Chukwu<br>3<br>Gee nti Nuru olu anyi gee nti Nuru aririo anyi,  denye aha anyi n"akwukwo ndu  anyi biara nobi gi Chukwu<br>4<br>Anyi ga efe gi uwatuwa Biko, Chukwu Mee ka anyi binyere gi<br>Ka Ngozi rukwasi anyi Chineke anyi biara nobi gi Chukwu<br>IHO IHO IHO - Sanctus(Idoma)<br>Iho Iho Iho Ondu owoicho<br>Ondu owoicho omancha la (X2)<br>Owofuku wo lemu lokpowoi cho<br>Olemu lo kp\'owoi cho mu le che<br>Osana osana osana<br>Owoicho ne hi<br>Ugwu ko yo la che noi wa<br>Ache no wa nmiye kondu<br>Osana osana osana<br>Owoicho ne hi</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'sanctus'),
	(98, 'O JISOS DEJU MI', 'pending', NULL, '<p>O Jisos deju mio</p>\n<p>Deju mi deju mi agba</p>\n<p>O Jisos deju mi</p>\n<p>Ka kpere alo</p>\n<p><strong>1.</strong><br>Ama tawa fola mu Iko Ile wa me (2 times)</p>\n<p><strong>2.</strong><br>Ami yewa fola mu Iko Ile wa me (2 times)</p>\n<p><strong>3.</strong><br>Ami fada fola mu Iko Ile wa me (2 times)</p>\n<p><strong>4.</strong><br>Amo maye fola mu Iko Ile wa me (2 times)</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'general'),
	(99, 'OTITO DIRI Chineke', 'Fr. Barth Ezeokafor', NULL, '<p>Otito diri n\'elu kach\'elu</p>\n<p>N"uwa udo udo diri</p>\n<p>Ndi mmadu ndi nwere obioma</p>\n<p>Ndi mmadu ndi nwere obioma</p>\n<p>Otito diri Chukwu</p>\n<p><strong>Verse 1</strong></p>\n<p>Anyi a jaa gi mma eh</p>\n<p>Anyi a gozie gi eh</p>\n<p>Anyi ese kpuoro gi, anyi e too gi</p>\n<p>Anyi ekele gi nihi nnukwu ebube gi</p>\n<p>Oseburuwa Chukwu, Eze nke eluigwe</p>\n<p><strong>Ch:</strong><br>ukwu Nna ji Ike Nile</p>\n<p>Otito diri gi n\'elu kasi elu</p>\n<p><strong>Verse 2</strong></p>\n<p>Dinwenu Jesus Kristi so otu nwa</p>\n<p><strong>Ch:</strong><br>ineke muru, dinwenu Chukwu</p>\n<p>Nwaturu nke Chineke, Nwa nke Nna</p>\n<p>Gi onye na ekpo chapu njo nk\'uwa ner\'anyi Ebere</p>\n<p>Gi onye na ekpo chapu njo nk\'uwa nur\'aririo anyi</p>\n<p>Gi onye no n\'aka nri Nna mere\'anyi Ebere</p>\n<p>Otito diri gi n\'elu kasi elu</p>\n<p><strong>Verse 3</strong></p>\n<p>N\'ihi na so gi di nso,</p>\n<p>so gi bu dinwenu</p>\n<p>So gi Jesu Kristi</p>\n<p>Kacha si di elu</p>\n<p>Gina Muo Nso</p>\n<p>N\'ebube Chukwu Nna</p>\n<p>Amen, Amen</p>\n<p>Otito diri gi n\'elu kasi elu</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'gloria'),
	(100, 'K\'ANYI JEE N\'OBI EZE', 'pending', NULL, '<p>Obi na aso muo aiyeiye obi na aso muo o</p>\n<p>Mgbe m nuru ka ha na asi eh</p>\n<p>Ka anyi jeenu n\'ulo nso,</p>\n<p>Ka anyi jeenu n\'obi Eze eh</p>\n<p>Onye ihe nile di n\'aka ya</p>\n<p>Onye ji aka ya diri n\'onwe ya</p>\n<p>Onye n\'enwero mbido</p>\n<p>Nke oji enwe njedebe oh</p>\n<p><strong>Ch:</strong><br>ineke Eze ukwu</p>\n<p>Nwanne m were anuri bata</p>\n<p>K\'anyi kelee chineke Onyeoma.</p>\n<p><strong>VERSE 1</strong></p>\n<p>Osebuluwa Nara ekele</p>\n<p>Onye nwe mmadu abiara m be gi</p>\n<p>Anyi si ka anyi bia kpooro gi isi ala n\'ihi na emere anyi ebuka</p>\n<p>Ogologo ndu I na enye anyi</p>\n<p>Aru Ike anyi di gi n\'aka</p>\n<p>Ji na ede anyi na ako bu oru aka gi</p>\n<p>Umu na uba anyi bu oru aka gi</p>\n<p>Ya ka anyi ji bia n\'iru gi</p>\n<p>Ikporo gi isiala aiyeye</p>\n<p><strong>VERSE 2</strong></p>\n<p>Lee iheoma nile di n\'uwa ebube ebube ebube</p>\n<p>ugwu na ndida n\'ile hancha bu oruaka ya</p>\n<p>Onwa na Kpakpando nwannem okwa chukwu Kere ha</p>\n<p>anu elu na anu mmiri na anuala tobe Chukwu</p>\n<p>Uwa na iheoma nile di n\'ime ya bu nke gi</p>\n<p>ezi chukwu gi n\'elekota ha</p>\n<p>ony\'eze chineke abiaram be gi omalicha</p>\n<p>IN THE FATHER I BELIEVE</p>\n<p>Chorus</p>\n<p>In the Father, I believe  Yes, I believe</p>\n<p>In the Spirit I believe three in one , I believe ( 2 times)</p>\n<p><strong>1.</strong><br>I believe in one God, the Father Almighty</p>\n<p>And in Jesus the son of God, maker of heaven and earth</p>\n<p><strong>2.</strong><br>He was conceived by the spirit, born of the Virgin Mary</p>\n<p>Suffered death and was crucified, under Pontius Pilate</p>\n<p><strong>3.</strong><br>He descended into hell, He rose on the third day.</p>\n<p>He ascended into heaven seated at the right hand of God.</p>\n<p><strong>4.</strong><br>He will come again in glory, to judge the living and dead.</p>\n<p>And His kingdom will have no end, and His kingdom will have no end.</p>\n<p><strong>5.</strong><br>I believe in the Spirit, the Catholic and Apostolic church,</p>\n<p>The communion of saints, the forgiveness of sins</p>\n<p><strong>6.</strong><br>I look forward, to the resurrection of the dead.</p>\n<p>And the life of the world to come, in the glory of the Lord.</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'communion'),
	(101, 'HANMA SHIIE', 'pending', NULL, '<p><strong>1.</strong><br>Zenden shin tar ne Ambatio mov nav hanma shie hanma jiir (2×)</p>\n<p><strong>Chorus:</strong></p>\n<p>Hanma shie haan, han-ma shie haan, han-ma shie han-ma shie hanma jiir (2×)</p>\n<p><strong>2.</strong><br>Tesen se kwaghfan wou sha u dondon gbenda wou... hanma</p>\n<p><strong>3.</strong><br>Eren se baptisima sha u nyorun Ken ya wou hanma...</p>\n<p><strong>Chorus:</strong></p>\n<p><strong>4.</strong><br>Yes se mba yilan we va kohol se shintarne hanma...</p>\n<p><strong>5.</strong><br>Shin tar ne se gba kwagh ga kpa u van hen vese abem hanma...</p>\n<p>A-mbatio mov nav Ken Jerusalem hanma</p>\n<p>A mbatiomov nav Ken Jadia</p>\n<p>A mbatiomov nav Ken Kafanahum</p>\n<p>A mbatiomov nav ken  Galalia</p>\n<p>A mbatiomov nav Ken Sidon</p>\n<p>hanma shie hanma shie hanma jiir</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'general'),
	(102, 'I GO ENTER HIS COURT', 'pending', NULL, '<p><strong>VERSE 1</strong></p>\n<p>I go enter his court with praise,</p>\n<p>I go shout Alleluia,</p>\n<p>Me I go enter his court with praise</p>\n<p>Me I go shout Alleluia.</p>\n<p><strong>Chorus:</strong></p>\n<p>O yeah my savior, o yeah my good Lord. X2</p>\n<p><strong>VERSE 2</strong></p>\n<p>I go enter his court with song,</p>\n<p>I go shout Alleluia,</p>\n<p>Me I go enter his court with song,</p>\n<p>Me I go shout Alleluia</p>\n<p><strong>VERSE 3</strong></p>\n<p>I go enter his court with dance,</p>\n<p>I go shout Alleluia,</p>\n<p>Me I go enter his court with dance</p>\n<p>Me I go shout Alleluia</p>\n<p><strong>VERSE 4</strong></p>\n<p>I go enter his court with thanks</p>\n<p>I go shout Alleluia,</p>\n<p>Me I go enter his court with thanks</p>\n<p>Me I go shout Alleluia</p>\n<p>Papa You Do Well</p>\n<p><strong>VERSE 1</strong></p>\n<p>Since the time of Adam</p>\n<p>Come reach today soh</p>\n<p>I never see anybody wey dey like my papa God</p>\n<p>(Because) I don go many places see many things hear many tori,</p>\n<p>The main topic na the good good things wey God dey do</p>\n<p>(Because) I don go many places see many things hear many tori,</p>\n<p>The main topic na the good good things wey God dey do</p>\n<p>Mighty father we dey hail you,</p>\n<p>We dey praise you,</p>\n<p>You be baba Ewoo, you do well (2x)</p>\n<p>You dey make me wonder</p>\n<p>Make me happy,</p>\n<p>You dey give me joy</p>\n<p>You dey make me jolly</p>\n<p>Sotey I dey denge pose</p>\n<p>I dey make Iyanga</p>\n<p>For all the blessings wey you give me dey boku-boku</p>\n<p>Na im make I come</p>\n<p>To come hail you Lord</p>\n<p>Na im make I come to say thank you.</p>\n<p>Baba you do well)</p>\n<p>Mungode, Ese oh, Daalu oh, Uwese</p>\n<p>Anya oh, Agba oh</p>\n<p>Magode papa you do well</p>\n<p>Anya anya!!!</p>\n<p>Obulu, Doo Jesu, Masu yebo, Se-ba-su we</p>\n<p>Imokon- fi, Tinji-gwe-je</p>\n<p>We thank you papa you do</p>\n<p>Mighty father we dey hail you,</p>\n<p>We dey praise you,You be baba Ewoo, you do well</p>\n<p><strong>VERSE 2</strong></p>\n<p>Anytime I ask you dey give me</p>\n<p>Anytime I seek I dey find</p>\n<p>Anytime I knock you dey open your door</p>\n<p>Anytime I call you dey answer</p>\n<p>You dey make me wonder, Make me happy,</p>\n<p>You dey give me joy, You dey make me jolly</p>\n<p>Sotey I dey denge pose, I dey make Iyanga</p>\n<p>For all the blessings wey you give me dey boku-boku</p>\n<p>Na im make I come,  To come hail you Lord</p>\n<p>Na im make I come to say thank you.</p>\n<p>(Baba you do well)</p>\n<p>Mungode, Ese oh, Daalu oh, Uwese</p>\n<p>Anya oh, Agba oh</p>\n<p>Magode papa you do well</p>\n<p>Anya anya!!!</p>\n<p>Obulu, Doo Jesu, Masu yebo, Se-ba-su we</p>\n<p>Imokon- fi, Tinji-gwe-je</p>\n<p>We thank you papa you do</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'communion'),
	(103, 'OBONG AMANAM', 'pending', NULL, '<p><strong>Chorus:</strong></p>\n<p>Amanam Obong amanam O sosongo Manam manam manam manam yenyi O sosongo (2ce)</p>\n<p><strong>Verse 1</strong></p>\n<p>Abasi mbok O bong amanam O kedi nonnyin U sen mfin emi sosongo bong ye ima fo</p>\n<p><strong>Verse 2</strong></p>\n<p>Baba owo nte kiet I biet ke Obong kem fon ido yeki ma fo O bong Yak ekom ye ukpo no yenefi</p>\n<p><strong>Verse 3</strong></p>\n<p>Ete mfon nyin I mo kom fi O kedi no Jesus man edi kpa oro anam nnyin I di kom fi O</p>\n<p><strong>Verse 4</strong></p>\n<p>Yak itoro enye ne te ye yen yedi sam spirit ke U bong tie ken yon yun doing ndi to fo emi</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'praise'),
	(104, 'HUEAN JESU', 'Atalakpa Henry', NULL, '<p><strong>Verse 1</strong></p>\n<p>O Jesu, ze’ hi bu mhenre ne gbe bia’ hu</p>\n<p>mhe kha gbon gbon</p>\n<p>Huean re gbe bia’ran non se mne</p>\n<p>khe ji mhan de o</p>\n<p>bhe don......Chorus</p>\n<p><strong>Verse 2</strong></p>\n<p>Ebealen, Huean gbee’ lo</p>\n<p>ghe Ibho khanlen se le re bhe.</p>\n<p>Rofure mhan, rhi’ iyen len ni mhan,</p>\n<p>Osenob’lua mhan bhie.... chorus</p>\n<p><strong>Chorus:</strong></p>\n<p>Huean Jesu 3x</p>\n<p>khe ji mhan de</p>\n<p>O bhe’ don mhen</p>\n<p>ona mhan bhi Ebealen</p>\n<p>Ise!!!</p>\n<p>Chi Obioma</p>\n<p><strong>1.</strong><br>Chim merem obioma mgbem n’enweghi Olol’anya chim merem obi oma eh 2X.</p>\n<p><strong>Ch:</strong><br>ukwu bu so mma</p>\n<p><strong>Ch:</strong><br>im merem obioma eh chim merem obi oma eh chim merem obi oma eh</p>\n<p>Agada gbachiri uzo Dike</p>\n<p><strong>Ch:</strong><br>im merme obi oma eh chim merem obi oma eh chim merem Obi oma eh</p>\n<p>Okike kere uwa Eze chim merem obi oma eh chim merem Obi oma eh chim merem obi oma eh Omerem ihe oma eh</p>\n<p><strong>Ch:</strong><br>im merem Obi oma eh Chim merem Obi oma eh chim merem Obi oma eh.</p>\n<p><strong>2.</strong><br>Ekele dikwara dikwara gi n’ibu odogwu chim merem obi oma eh 2X.</p>\n<p><strong>3.</strong><br>Otito dikwara dikwara gi n’ibu chukwu chim merem obi oma eh! 2X</p>\n<p><strong>4.</strong><br>Chukwu idi ugwu olil’anya umu-uwa no Mgbere de Chim merem obioma Eh! 2X.</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'agnus_dei'),
	(105, 'EYEN ERONG ABASI', 'pending', NULL, '<p>Eyen erong</p>\n<p>Abasi emi...emende</p>\n<p>M\'i diok\'m kpo</p>\n<p>Ererim bot efep</p>\n<p>tua tua yi mbom</p>\n<p>Tua yin bom tua yin bom</p>\n<p>Eyen erong</p>\n<p>Abasi emi...emende</p>\n<p>M\'i diok\'m kpo</p>\n<p>Ererim bot efep</p>\n<p>tua tua yi mbom</p>\n<p>Tua yin bom tua yin bom</p>\n<p>Eyen erong</p>\n<p>Abasi emi...emende</p>\n<p>M\'i diok\'m kpo</p>\n<p>Erim bot efep</p>\n<p>Noyin noyin emem</p>\n<p>Noyin emem noyin emem</p>\n<p>Oluwa saanu fun wa - by Sam Ezugwu</p>\n<p>Oluwa saanu fun wa</p>\n<p>saanu fun wa</p>\n<p>oluwa, oluwa saanu fun wa x2</p>\n<p>Kristi saanu fun wa, Kristi saanu fun wa</p>\n<p>Kristi saanu fun wa (Kristi)</p>\n<p>Kristi saanu fun wa</p>\n<p>Oluwa saanu fun wa</p>\n<p>saanu fun wa</p>\n<p>oluwa, oluwa saanu fun wa x2</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'general'),
	(106, 'GLORIA TO GOD', 'Gabriel Momah', NULL, '<p>Glory to God, glory to God, glory to God to God to God</p>\n<p>Glory to God, glory to God, glory to God I\'m the highest</p>\n<p><strong>1.</strong><br>And on earth peace to men, peace to men of goodwill</p>\n<p>We praise you, we bless you</p>\n<p>we bless and worship you, we glorify your great name, we give you thanks O lord</p>\n<p><strong>2.</strong><br>Lord God heavenly king, lord God almighty father</p>\n<p>we praise you, we bless you</p>\n<p>Jesus Christ son of God, only son of the father</p>\n<p>Lord God lamb of God</p>\n<p><strong>3.</strong><br>Have mercy in us Lord</p>\n<p>You who takes away sins</p>\n<p>the sins of all mankind</p>\n<p>Have mercy on us Lord</p>\n<p>You who takes away sins</p>\n<p>receive our prayers O lord</p>\n<p><strong>4.</strong><br>Have mercy on us Lord</p>\n<p>You who sits at the right hand</p>\n<p>Of the father in heaven</p>\n<p>You alone lord Jesus</p>\n<p>You alone are holy</p>\n<p>You alone are the most high</p>\n<p><strong>5.</strong><br>You alone lord Jesus</p>\n<p>with the holy spirit</p>\n<p>in the father\'s glory</p>\n<p>Amen, amen amen, amen</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'gloria'),
	(107, 'O Mai tsarki', 'Jude Nnam', NULL, '<p><strong>1.</strong><br>O Mai Tsarki O</p>\n<p>O Mai tsarki</p>\n<p>Ubangiji Ubangiji</p>\n<p>Allah Mai rudunan o</p>\n<p>O Mai Tsarki (Allah),</p>\n<p>(Allah mai tsarki)</p>\n<p>Sama da Kasa a cike suke darajarka.</p>\n<p><strong>Chorus:</strong></p>\n<p>Hossanna, a cikin samaniya</p>\n<p>Hossanna, a cikin samaniya o 2x</p>\n<p><strong>2.</strong><br>O Mai Tsarki<br>O Mai Tsarki<br>Mai albarkane ya Mai tsarki o<br>Wande yake zuwa<br>Wande yake zuwa<br>A cikin sunan Ubangiji - chorus</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'sanctus'),
	(108, 'HOLY GOD WE PRAISE THY NAME', 'pending', NULL, '<p><strong>1.</strong><br>Holy God, we praise Your name;</p>\n<p>Lord of all, we bow before You.</p>\n<p>Saints on earth Your scepter claim;</p>\n<p>all in heav\'n above adore You.</p>\n<p>Infinite, Your vast domain;</p>\n<p>everlasting is Your reign.</p>\n<p><strong>2.</strong><br>Hark, the glad celestial hymn</p>\n<p>angel choirs above are raising;</p>\n<p><strong>Ch:</strong><br>erubim and seraphim,</p>\n<p>in unceasing chorus praising,</p>\n<p>fill the heav\'ns with sweet accord:</p>\n<p>“Holy, holy, holy Lord!”</p>\n<p><strong>3.</strong><br>Lo, the apostolic train</p>\n<p>joins Your sacred name to hallow;</p>\n<p>prophets swell the glad refrain,</p>\n<p>and the white-robed martyrs follow;</p>\n<p>and from morn to set of sun,</p>\n<p>through the church the song goes on.</p>\n<p><strong>4.</strong><br>Holy Father, Holy Son,</p>\n<p>Holy Spirit, three we name You,</p>\n<p>though in essence only one;</p>\n<p>undivided God, we claim You,</p>\n<p>and, adoring, bend the knee</p>\n<p>while we own the mystery.</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'sanctus'),
	(109, 'JUST AS I AM WITHOUT ONE PLEA', 'pending', NULL, '<p><strong>1.</strong><br>Just as I am, without one plea,</p>\n<p>But that Thy blood was shed for me,</p>\n<p>And that Thou bid’st me come to Thee,</p>\n<p>O Lamb of God, I come! I come</p>\n<p>Ref: Just as I am, just as I am, just as I am I come</p>\n<p>And that thou bidst me come to thee, O lamb of God I come I come</p>\n<p><strong>2.</strong><br>Just as I am, and waiting not</p>\n<p>To rid my soul of one dark blot;</p>\n<p>To Thee whose blood can cleanse each spot,</p>\n<p>O Lamb of God, I come, I come!</p>\n<p><strong>3.</strong><br>Just as I am, though tossed about</p>\n<p>With many a conflict, many a doubt;</p>\n<p>Fightings within, and fears without,</p>\n<p>O Lamb of God, I come, I come!</p>\n<p><strong>4.</strong><br>Just as I am, poor, wretched, blind;</p>\n<p>Sight, riches, healing of the mind;</p>\n<p>Yes, all I need, in Thee to find,</p>\n<p>O Lamb of God, I come, I come!</p>\n<p><strong>5.</strong><br>Just as I am, Thou wilt receive,</p>\n<p>Wilt welcome, pardon, cleanse, relieve;</p>\n<p>Because Thy promise I believe,</p>\n<p>O Lamb of God, I come, I come!</p>\n<p><strong>6.</strong><br>Just as I am, Thy love unknown</p>\n<p>Has broken every barrier down;</p>\n<p>Now, to be Thine, yea, Thine alone,</p>\n<p>O Lamb of God, I come, I come!</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'communion'),
	(110, 'COME CHRISTIANS JOIN TO SING', 'pending', NULL, '<p><strong>1.</strong><br>Come, Christians, join to sing</p>\n<p>Alleluia, Amen!</p>\n<p>Loud praise to Christ our King,</p>\n<p>Alleluia, Amen!</p>\n<p>Let all, with heart and voice,</p>\n<p>before His throne rejoice;</p>\n<p>praise is His gracious choice,</p>\n<p>Alleluia, Amen!</p>\n<p><strong>2.</strong><br>Come, lift your hearts on high,</p>\n<p>Alleluia, Amen!</p>\n<p>Let praises fill the sky,</p>\n<p>Alleluia, Amen!</p>\n<p>He is our Guide and Friend,</p>\n<p>to us He\'ll condescend;</p>\n<p>His love shall never end,</p>\n<p>Alleluia, Amen!</p>\n<p><strong>3.</strong><br>Praise yet our Christ again,</p>\n<p>Alleluia, Amen!</p>\n<p>Life shall not end the strain,</p>\n<p>Alleluia, Amen!</p>\n<p>On heaven\'s blissful shore</p>\n<p>His goodness we\'ll adore,</p>\n<p>singing forevermore,</p>\n<p>"Alleluia, Amen!"</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'praise'),
	(111, 'AGNUS DEI (LATIN)', 'pending', NULL, '<p>Agnus Dei, qui tollis peccata mundi:</p>\n<p>Lamb of God,</p>\n<p>you take away the sins of the world,</p>\n<p>have mercy on us. X2</p>\n<p>Agnus Dei, qui tollis peccata mundi:</p>\n<p>Lamb of God,</p>\n<p>you take away the sins of the world,</p>\n<p>grant us peace.</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'agnus_dei'),
	(112, 'THE LORD BLESS AND KEEP YOU', 'pending', NULL, '<p>The Lord bless you and keep you;</p>\n<p>the Lord lift his countenance upon you,</p>\n<p>and give you peace;</p>\n<p>the Lord make his face to shine upon you,</p>\n<p>and be gracious unto you.</p>\n<p>Amen, amen.......</p>\n<p>SANCTUS LIBERA</p>\n<p>Sanctus Sanctus Sanctus</p>\n<p>Sanctus dominus deus sabbaoth</p>\n<p>pleni sunt caeli te Terra gloria x2</p>\n<p>Hossana Hossana in excelsis</p>\n<p>Benedictus Benedictus qui Venite in nomine benedictus in nomine et domine</p>\n<p>Benedictus Benedictus qui venit in nomine Benedictus in nomine et domine</p>\n<p>Hossana Hossana in excess</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'sanctus'),
	(113, 'EAT THIS BREAD', 'pending', NULL, '<p><strong>Refrain:</strong></p>\n<p>Eat this bread drink this cup come to me and never be hungry</p>\n<p>Eat this bread drink this cup trust in me and you will have rest</p>\n<p><strong>Verse 1</strong></p>\n<p>I am the bread of life a true bread sent from the Father</p>\n<p><strong>Verse 2</strong></p>\n<p>Your ancestors ate manner in the desert it is the bread that came down from heaven</p>\n<p><strong>Verse 3</strong></p>\n<p>Eat my flesh and drink my blood and I will raise you up on the last day</p>\n<p><strong>Verse 4</strong></p>\n<p>Anyone who eat this bread will live forever</p>\n<p><strong>Verse 5</strong></p>\n<p>If you believe and eat this bread you will have eternal life</p>\n<p>BRING THEM TO THE LORD</p>\n<p>Chorus</p>\n<p>Bring them to the Lord</p>\n<p>Bring them to the Lord,</p>\n<p>I will bring my gift to the Lord</p>\n<p>I will offer unto God, the gift from my heart,</p>\n<p>I will bring them and bring them to the lord.</p>\n<p><strong>1.</strong><br>I lost my way, and went astray,Jesus came to me,</p>\n<p>He touched my heart, He touched my soul and then He made me whole.</p>\n<p><strong>2.</strong><br>I lost my sight I cannot see, a shadow fell on me.</p>\n<p>He spoke to me, it was Jesus and I can see again.</p>\n<p><strong>3.</strong><br>I was afloat the troubled sea, Jesus came to me,</p>\n<p>He held me close and calmed my fears And then He led me home…</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'communion'),
	(114, 'HOW CAN I REPAY YOUR LOVE', 'pending', NULL, '<p><strong>Ch:</strong><br>ORU:</p>\n<p>Jesus, you have been so good to me</p>\n<p>How can I repay your love?</p>\n<p>Take and sanctify sanctify the gift I offer to you</p>\n<p>Take this thanksgiving sacrifice I make to you</p>\n<p>Take and sanctify this gift I offer to you</p>\n<p>Accept my humble thankful heart</p>\n<p><strong>1.</strong><br>what can I offer to him who has died for me</p>\n<p>The one who still loves me inspite of all my offences</p>\n<p>Please take this thanksgiving sacrifice I make to you</p>\n<p>How can I repay your love?</p>\n<p><strong>2.</strong><br>In trails and temptation, you have stood by me</p>\n<p>When I feel hopeless and I\'m helpless You still care for me</p>\n<p>There\'s no one in the world who can compare to you</p>\n<p>How can I repay your love?</p>\n<p><strong>3.</strong><br>I sin against you constantly, betray your love</p>\n<p>Yet you assure me that you died to save me from my sin</p>\n<p>If only I will love you like you love my soul</p>\n<p>How can I repay your love?</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'praise'),
	(115, 'MY STORY', 'Jude Nnam', NULL, '<p><strong>Verse 1</strong></p>\n<p>When I remember what you\'ve done for me,</p>\n<p>My heart leaps for joy for there\'s none like you,</p>\n<p>When I remember that you died for me,</p>\n<p>My heart leaps for joy for there\'s none like you</p>\n<p>And so.</p>\n<p><strong>Chorus:</strong></p>\n<p>I will give you all I have,</p>\n<p>Receive God my offering to you,</p>\n<p>Which I offer with my friends today...</p>\n<p>Transform them and transform us</p>\n<p>Purify them and purify us,</p>\n<p>In this sacrifice divine</p>\n<p>Always Lord, you know that</p>\n<p>I have given all I have.</p>\n<p><strong>Verse 2</strong></p>\n<p>There was a time in life when I thought all was</p>\n<p>Lost, Lord I am a living testimony of your love</p>\n<p>You changed my story of woes to joy,</p>\n<p>Lord I am a living testimony of your Love</p>\n<p>And so</p>\n<p><strong>Verse 3</strong></p>\n<p>Many cannot see, many cannot hear,</p>\n<p>I am blessed with these glory be to God,</p>\n<p>Many have no food many have no home I</p>\n<p>Am blessed with these glory be to God</p>\n<p>And so...</p>\n<p><strong>Verse 4</strong></p>\n<p>I will tell this story to my neighbors,</p>\n<p>I will tell this story to all my friends,</p>\n<p>I will sing for you, I will praise your name,</p>\n<p>I will dance for you for there\'s none like you</p>\n<p>And so.</p>\n<p>Abu\'m nke gi Jesu</p>\n<p>werem o Jesu ahurum gi n\'anya</p>\n<p>werem me ihe di gi mma</p>\n<p>abu\'m nke gi</p>\n<p>bia biri n\'ime\'m, i bu enyim oma</p>\n<p>sacha\'m Jesu, abu\'m nke gi</p>\n<p>Achicha di ndu achicha si n\'igwe bia</p>\n<p>bia biri n\'ime\'m abu\'m nke gi x2</p>\n<p>Nri ndi mmuo ozi,</p>\n<p>Nri ndi di aso,</p>\n<p>bia biri n\'ime\'m,</p>\n<p>Abum nke gi.</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'offertory'),
	(116, 'ALL GLORY BELONGS TO YOU', 'pending', NULL, '<p>All glory belongs to you,</p>\n<p>It belongs to you Holy trinity (x2)</p>\n<p>O yes, o yes God is three.</p>\n<p>O yes, o yes God is one.</p>\n<p>There is one God in three persons,</p>\n<p>It belongs to you holy trinity.</p>\n<p><strong>1.</strong><br>To you be all praise, all thanksgiving.</p>\n<p>Forever, o blessed trinity.</p>\n<p><strong>2.</strong><br>In you there is hope and salvation,</p>\n<p>And glory, o blessed trinity.</p>\n<p><strong>3.</strong><br>Hear us when we pray, God the father.</p>\n<p>Son and Spirit, o blessed trinity.</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'gloria'),
	(117, 'OTITO NA NSOPURU', 'pending', NULL, '<p>Otito otito otito na nsopuru kanyi na ebunye Gi Chukwu Nna na Nwa na Muo  nso. Ato, ato n\'otu di ngozi</p>\n<p>Uwa Nile donu aha Chineke ebube, werenu ukwe onu bulie aha ya elu, werenu ukwe onu bulie aha ya elu, bulie aha ya bulie aha ya bulie aha ya elu, sekpuere nu ya, sekpuere nu ya</p>\n<p>N\'ezie Person ato n\'otu Chineke do omimi, Kasia kachasi Kasia kachasi uche madu (odikwazi aso kwesi nsopuru) odikwazi aso odikwazi aso kwesi nsopuru na otito nebe ihe Nile okere eke di</p>\n<p>Kanyi kelenu</p>\n<p>Kanyi kelenu Onye okike</p>\n<p>Kanyi kelenu</p>\n<p>Kanyi kelenu Onye nzoputa</p>\n<p>Kanyi kele ya</p>\n<p>Bianu kanyi kelenu Onye ndokwa kele Onye ndokwa nke ihe Nile di nokpuru anyanwu Chukwu ee Chukwu na enye ndu Chukwu na enye ndu Chukwu na enye ndu odogwu</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'general'),
	(118, 'COME DOWN HOLY SPIRIT', 'pending', NULL, '<p><strong>Refrain:</strong></p>\n<p>Halleluia Halleluia Halleluia Amen Halleluia (2ce)</p>\n<p><strong>Verse 1</strong></p>\n<p>This is the day the Lord has made let us be glad and rejoice in it let us thank the Lord for this wonderful day when we gather to share His blessings</p>\n<p>So come down come down come down Holy Spirit come down (2ce)</p>\n<p><strong>Verse 2</strong></p>\n<p>Come down Holy Spirit and fill our hearts come and fill the hearts of all Your faithful people Kindle in our hearts the fire of Your love Descend on us Creator Spirit So come down come down come down Holy Spirit come down (2ce)</p>\n<p><strong>Verse 3</strong></p>\n<p>Send forth Your Spirit to us O Lord let it renew the face of the earth the love of God has been poured in our hearts by His Spirit living in His people</p>\n<p>So come down come down come down Holy Spirit come down (2ce)</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'sanctus'),
	(119, 'THE COMFORTER HAS COME', 'pending', NULL, '<p><strong>1.</strong><br>Oh, spread the tidings ’round, wherever man is found,<br>Wherever human hearts and human woes abound;<br>Let every Christian tongue proclaim the joyful sound:</p>\n<p><strong>Chorus:</strong></p>\n<p>The Comforter has come!</p>\n<p>The Comforter has come,</p>\n<p>The Comforter has come!</p>\n<p>The Holy Ghost from heav’n,</p>\n<p>The Lord’s dear promise giv’n;</p>\n<p>Oh, spread the tidings ’round,</p>\n<p>Wherever man is found—</p>\n<p>The Comforter has come!</p>\n<p><strong>2.</strong><br>The long, long night is past, the morning breaks at last;<br>And hushed the dreadful wail and fury of the blast,<br>As o’er the golden hills the day advances fast!<br>    The Comforter has come!<br>3<br>Lo, the great King of kings, with healing in His wings,<br>To every captive soul a full deliv’rance brings;<br>And through the vacant cells the song of triumph rings:<br>    The Comforter has come!<br>4<br>O boundless love divine! how shall this tongue of mine<br>To wond’ring mortals tell the matchless grace divine<br>That I, a child of hell, should in His image shine!<br>    The Comforter has come!</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'sanctus'),
	(120, '_*MUO NSO GBADATA*_', 'pending', NULL, '<p>Chorus</p>\n<p>Muo nso gba _ da- ta</p>\n<p>Muo nso gba _ da- ta</p>\n<p>eligwe me ghee me ghee</p>\n<p>o meghee wo.(twice)</p>\n<p><strong>Verse1</strong></p>\n<p>Muo nso, m</p>\n<p>Muo nso Nuo nso bata ni m\'obi  mo,...biko doh.. Gbadata n\'ime ulo a, gbadata n\'ime anyi o biko</p>\n<p><strong>Verse2</strong></p>\n<p>Obibia muo nso nke kristi kwel\'an yi nkwa a bia wo, a bia wo</p>\n<p>O bibia muo nso nke kristi kwe lanyi nkwa a bia wo ni me ndu mo</p>\n<p><strong>Verse3</strong></p>\n<p>Gbabalu ya egwu, egwu ekene, egwu otito, egwu ojija mma eh ewo ewo</p>\n<p>Gbabalu ya egwu egwu ekene, egwu otito, egwu ojija mma eh ewo ewo</p>\n<p><strong>Verse4</strong></p>\n<p>Otito dili Chukwu nna</p>\n<p>Otito dili kri_sti</p>\n<p>Otito dili muo nso</p>\n<p>Ise..  Ise</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'praise'),
	(121, 'IFE CHUKWU', 'pending', NULL, '<p><strong>Refrain:</strong></p>\n<p>O nwube nwube Ife Chukwu nwuru gabazia nu Ife Chineke mo</p>\n<p><strong>Ch:</strong><br>usasia Ochichiri nime nduma buru ngozi nkemo ife Chukwu Chahwa sima Ife Chineke Nna mo</p>\n<p><strong>Verse 1</strong></p>\n<p><strong>Ch:</strong><br>ukwu bu ike mo O ne nyere maka Chukwu bu ndu mo O na zoputa mo</p>\n<p><strong>Ch:</strong><br>ukwu buife mo O nedu meje edu mala Ife mo mara nma nwube nwube</p>\n<p><strong>Verse 2</strong></p>\n<p><strong>Ch:</strong><br>ineke elekwasago many’ebere ya Ez’ebube elekwasa go manya mara ya</p>\n<p>Oji ngozi ya gbaa m Okirikiri wer’ife ya chagide mo si m nwube</p>\n<p><strong>Verse 3</strong></p>\n<p>Oge nwugide Oge nwugide</p>\n<p><strong>Ch:</strong><br>ukwu nyere mo ge nwugide N’ebe nilem neje Oge nwugide Nihe nilem ne me Ife Chukwu n’ilulo Okwu n’o mume nile Ife Chukwu Ife Chineke ge nwugide</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'general'),
	(122, 'OMOGODE', 'HPC Anyanwu', NULL, '<p>Omogode Omogode r\'Ọghẹnẹ(r\'Ọghẹnẹ)x2</p>\n<p>rọ si imuemu rẹ akpọ na no</p>\n<p>naruẹdọn rẹ avwanre</p>\n<p>(Repeat twice)</p>\n<p>Omogode Omogode r\'Ọghẹnẹ(r\'Ọghẹnẹ)</p>\n<p>ró si imuemu rẹ akpọ na no</p>\n<p><strong>v</strong></p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'gloria'),
	(123, 'SANCTUS (EFIK)', 'Sam Ezugwu', NULL, '<p>Edisana</p>\n<p>Edisana Edisana.</p>\n<p>Edisana Edisana</p>\n<p>Edisana,</p>\n<p>Obong Abasi u-dim Ekong</p>\n<p>Enyong ye isong eyohoye itoro\'fo</p>\n<p>Edisana (2x)</p>\n<p>(Hosanna) Hosanna Hosanna Hosanna-a, Hosanna Hosa-nna</p>\n<p>Ke ata ikpa enyong.</p>\n<p>Edisana Edisana..a-</p>\n<p>Edisana Edisana..a</p>\n<p>Edisana,</p>\n<p>E-mediong enye emi</p>\n<p>E-di-de K\'enyin Obong (2x)</p>\n<p>(Hosanna) Hosanna Hosanna Hosanna-a, Hosanna Hosa-nna</p>\n<p>Ke ata ikpa enyong.</p>\n<p>Dada Kabati</p>\n<p>Dada kabati bin ka ti goro</p>\n<p>Kaba tibinka ti goro</p>\n<p>Dada kabati bin ka ti goro</p>\n<p>Dada kabati bin ka tu ji ra</p>\n<p>bin ka tu ji ra a sap ta goro</p>\n<p>VERSE 1</p>\n<p>Kabi ita mi kabi ita mi</p>\n<p>Kaba en mi ji ra I sap ta goro</p>\n<p>Tiyi tiu en na gun ghu tsai su go ro</p>\n<p>Tsai su go ro na fa rin ci ki ki ni ti go diya</p>\n<p>VERSE 2</p>\n<p>Kaba mini kaba mini</p>\n<p>Kaba enmi ji ra I sap tagoro</p>\n<p>Tsaisu go ro na farin ci ki</p>\n<p>Kini ti go diya</p>\n<p>Kini ti go diya</p>\n<p>VERSE 3</p>\n<p>Timagi di nu ida tha namatha ra mo-wa sap ta goro</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'sanctus'),
	(124, 'DAUKAKA GA ALLAH (HAUSA)', 'pending', NULL, '<p><strong>Bass:</strong><br>Daukaka ga Allah cikin sama niya</p>\n<p><strong>Chorus:</strong></p>\n<p>Daukaka ga Allah,</p>\n<p>Daukaka ga Allah</p>\n<p>Daukaka ga Allah</p>\n<p>Cikin sama niya</p>\n<p><strong>VERSE 1</strong></p>\n<p>Aduniya Kuma salama</p>\n<p>Ga mutane na nufi mai kyau</p>\n<p>Muna Muna yabonka, Muna albarka ceka</p>\n<p><strong>VERSE 2</strong></p>\n<p>Muna yi maka sujada</p>\n<p>Muna muna daukaka ka</p>\n<p>Munayi maka godiya,</p>\n<p>Saboda dara jarka mai girma</p>\n<p><strong>VERSE 3</strong></p>\n<p>Ya ubangiji Allah</p>\n<p>Sarkin Sarkin Sama</p>\n<p>Allah Uba Mai iko duka</p>\n<p>Allah Uba Mai iko duka</p>\n<p><strong>VERSE 4</strong></p>\n<p>Ya Ubangiji Yesu almasihu</p>\n<p>Da maka da ici</p>\n<p>Ya Ubangiji Allah</p>\n<p>Dan tunkiya na Allah Dan Uba.</p>\n<p><strong>VERSE 5</strong></p>\n<p>Kai da ke ka-war da zunu-banduniya</p>\n<p>kayi mana jinkai</p>\n<p>kaida kekawa da zunuban duniya</p>\n<p>ka ji addu \'awar-mu</p>\n<p><strong>VERSE 6</strong></p>\n<p>Kai da ka ke zaune</p>\n<p>A hannun-dama na Uba,</p>\n<p>Ka yi mana jinkai</p>\n<p>kayi Mana jinkai</p>\n<p><strong>VERSE 7</strong></p>\n<p>Domin kai ka-dai Mai Tsarki ne,</p>\n<p>Kai ka dai Ubangiji ne</p>\n<p>kai ka dai madaukaki ne</p>\n<p>Kai ka dai madaukaki ne</p>\n<p><strong>VERSE 8</strong></p>\n<p>Ya Yesu almasihu</p>\n<p>tare da ruhu mai Tsarki,</p>\n<p>Cikin dara ja Allah Uba</p>\n<p>Amin Amin Amin</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'sanctus'),
	(125, 'SPIRIT OF GOD', 'pending', NULL, '<p><strong>VERSE 1</strong></p>\n<p>Spirit of God in the clear running water,</p>\n<p>Blowing to greatness the trees on the hill,</p>\n<p>Spirit of God in the finger of morning.</p>\n<p><strong>Chorus:</strong></p>\n<p>Fill the earth, bring it to birth and blow</p>\n<p>where you will,</p>\n<p>Blow, blow, blow, till I be but the breath</p>\n<p>of the Spirit blowing in me.</p>\n<p><strong>VERSE 2</strong></p>\n<p>I saw the scar of a year that lay dying,</p>\n<p>Hear the lament of a lone whip-poor-will,</p>\n<p>Spirit of God, see that cloud crying,</p>\n<p>Fill the earth, bring it to birth and blow</p>\n<p>where you will,</p>\n<p>Blow, blow, blow, till I be but the breath</p>\n<p>of the Spirit blowing in me.</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'holy_spirit'),
	(126, 'BOLINGO BWA NZAMBE', 'pending', NULL, '<p>(The Love of God)</p>\n<p>Bolingo bwa Nzambe boleki bonene</p>\n<p>(The Love of God surpasses all understanding)</p>\n<p>Wanatindeli biso Yes mobikisi</p>\n<p>(He sent the Sávior Jesus to us) (Repeat)</p>\n<p><strong>Refrain:</strong></p>\n<p>Salelaka Mokonzi, okoyoka esengo</p>\n<p>(Keep working for God, He will add to Your Joy) Salelaka Mokonzi, okoyoka esengo</p>\n<p>(Keep working for God,</p>\n<p>He will add to Your Joy) (Repeat)</p>\n<p>Lolaka la ngelu loye Marie</p>\n<p>(The voice of the Angel came to Mary)</p>\n<p>Ndiabuti Emmanueli Kristu mosikoli</p>\n<p>("For You will birth Emanuel, Christ the Redeemer) (Repeat)</p>\n<p>(Refrain)</p>\n<p>Maseli wa zambe nandi meli yo</p>\n<p>(God\'s worker, I believe You)</p>\n<p>Impo manso malobi yond eyel ngai</p>\n<p>(For the Word says that!</p>\n<p>You have come for me) (Repeat)</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'creed'),
	(127, 'ONDU CH\'EJUMO MI WA', 'pending', NULL, '<p>Ondu Ch’jumomi wa</p>\n<p>Ondu ch’ejumomi wa</p>\n<p>Kristi ch’ejumomi wa, Kristi ch’ejumomi wa x2</p>\n<p>Ondu ch’ejumomi wa</p>\n<p>Ondu ch’ejumomi wa</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'general'),
	(128, 'A JOYFUL DAY', 'pending', NULL, '<p><strong>Chorus:</strong></p>\n<p>What a joyful day, the day of the Lord</p>\n<p>What a joyful day, we are happy and glad.</p>\n<p><strong>Refrain:</strong></p>\n<p>A joyful day, we are happy and glad</p>\n<p><strong>1.</strong><br>Rejoice in the Lord, yeah children of the Lord. Ref</p>\n<p><strong>2.</strong><br>Arise and praise Him, who made earth and heaven Ref/Chorus</p>\n<p><strong>3.</strong><br>Enter His temple, and sing Him your praises. Ref/Chorus</p>\n<p><strong>4.</strong><br>The Lord is so good, He\'s good to His people. Ref/Chorus</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'praise'),
	(129, 'REJOICE FOR THE HOLY MAN OF GOD IS GIVEN', 'pending', NULL, '<p>Rejoice, O rejoice</p>\n<p>Rejoice for the holy man of God rejoice</p>\n<p>Rejoice, rejoice</p>\n<p>Behold the priest of God is given</p>\n<p>Rejoice, rejoice, rejoice, rejoice</p>\n<p>Rejoice, rejoice, rejoice</p>\n<p>For the priest of God is given</p>\n<p>(For the priest of God is given</p>\n<p>For the priest of God is given</p>\n<p>O rejoice for He is among the people) 2x</p>\n<p>Among the people</p>\n<p>He shall cast away demons</p>\n<p>In the house of our Lord Jesus</p>\n<p>And He shall heal the sick</p>\n<p>And make the weak to be strong</p>\n<p>Blessed is the holy man of God</p>\n<p>Blessed is the holy man of God, blessed</p>\n<p>Blessed is the holy man of God</p>\n<p>Blessed is the holy man of God, Holy one</p>\n<p>Blessed is the holy man of God, Holy one</p>\n<p>Blessed One</p>\n<p>The holy one</p>\n<p>Sacrament of love</p>\n<p><strong>Chorus:</strong></p>\n<p>Come to my Jesus, Come in and stay.</p>\n<p>May this sacrament be my life.</p>\n<p><strong>verse 1</strong></p>\n<p>Give my life to Jesus, in you I trust.</p>\n<p>Rule in my heart, and make it thy throne.</p>\n<p>oh my gentle Jesus in this Eucharist,</p>\n<p>Reign in me and make me thy own.</p>\n<p><strong>verse 2</strong></p>\n<p>Come to me Jesus, thy kingdom bring.</p>\n<p>rule in my world, my thoughts and my words</p>\n<p>oh my saving Jesus lover of the poor,</p>\n<p>come to me and give thy rest.</p>\n<p><strong>verse 3</strong></p>\n<p>Oh loving Jesus, dear son of Mary.</p>\n<p>Life is no gain, except in your name.</p>\n<p>Oh my caring Jesus, my only Jesus.</p>\n<p>bid me come to share in thy name.</p>\n<p><strong>verse 4</strong></p>\n<p>Hail! Hail! my Jesus, hope of the lost.</p>\n<p>teach me thy pain, thy gain and thy name.</p>\n<p>Oh redeemer Jesus, I trust you alone.</p>\n<p>Now and in all ages to come.</p>\n<p>ITORO</p>\n<p><strong>Chorus:</strong></p>\n<p>Itoro Itoro, enyene Abasi</p>\n<p>Abasi K\'enyong Itoro K\'enyong</p>\n<p><strong>1.</strong><br>Emem onyung odu k\'isong</p>\n<p>Yeme nye ne nti esit</p>\n<p>Nnyin imotoro fi imobuk mfonfo</p>\n<p>Imatuak ibuot nofi - chorus</p>\n<p><strong>2.</strong><br>Imatana asefo Imokomfi</p>\n<p>Ke ntak akwa\'bong fo</p>\n<p>Obong Abasi ediden heaven</p>\n<p>Abasi ete andi keme ndinam kpukpru mkpo - chorus</p>\n<p><strong>3.</strong><br>Obong Jesus Christ nku kure</p>\n<p>Eyen Abasi O Obong Abasi</p>\n<p>Eyen erong Abasi eyen Abasi ete -Chorus</p>\n<p><strong>4.</strong><br>Emi emende mi diok nkpo</p>\n<p>Ererim bot efep tua nnyin mbom</p>\n<p>Afo emi emende mi\'diok mkpo</p>\n<p>Ererim bot efep kop akam nnyin</p>\n<p><strong>5.</strong><br>Afo emi etie de k\'ubok na sia</p>\n<p>Abasi ete tua nnyin mbom</p>\n<p>Koro\'fo ikpong edi edisana</p>\n<p>Afo ikpong edi Obong</p>\n<p><strong>6.</strong><br>Afo ikpong okong akan</p>\n<p>O Jesus Christ ye edisana spirit</p>\n<p>Ke ubong Abasi ete. Amen</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'communion'),
	(130, 'THE STONE THAT THE BUILDERS REJECTED', 'pending', NULL, '<p><strong>Chorus:</strong></p>\n<p>The stone which the builders rejected</p>\n<p>Has become cornerstone</p>\n<p>Alleluia! Alleluia!</p>\n<p>Has become the CORNERSTONE x2</p>\n<p><strong>1.</strong><br>Let the family of Israel sing</p>\n<p>"God\'s love has no end! God\'s love has no end!"</p>\n<p>Let the family of Aaron say</p>\n<p>"God\'s love has no end! God\'s love has no end!"</p>\n<p>And let all who fear God, and let all who fear God</p>\n<p>Say "His love is without end!"</p>\n<p>Alleluia! Alleluia!</p>\n<p>Say "His love is without end!"</p>\n<p><strong>2.</strong><br>I call to the Lord in my distress</p>\n<p>He answered me and set me free</p>\n<p>God is at my side, God is at my side</p>\n<p>God is here to help me now</p>\n<p>Alleluia! Alleluia!</p>\n<p>God is here to help me now</p>\n<p><strong>3.</strong><br>Open to me the gates of holiness</p>\n<p>I will enter and give thanks</p>\n<p>This is the Lord\'s own gate</p>\n<p>The gate where the just may enter in</p>\n<p>I will thank you Lord, I will thank you Lord</p>\n<p>For you hear and answer me</p>\n<p>Alleluia! Alleluia!</p>\n<p>For you hear and answer me</p>\n<p><strong>4.</strong><br>Go forward with branches</p>\n<p>Go forward processing</p>\n<p>Go to the altar of the Lord</p>\n<p>And give thanks to God</p>\n<p>And give thanks go God</p>\n<p>For His love is without end</p>\n<p>Alleluia! Alleluia!</p>\n<p>For His love is without end</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'communion'),
	(131, 'AMI NYEKOM OBONG ABASI MI', 'pending', NULL, '<p><strong>1.</strong><br>Ami nyekom Obong Abasi mi</p>\n<p>Obong Kima emi enyen enye ne de ono nyi</p>\n<p>O edi Kom Abasi mi sia om’odot itoro</p>\n<p><strong>Chorus:</strong><br>Sio mkpo alleluia, Jesus, edi akwa ima,</p>\n<p>Mee anie okpo fon te Jesus, Jesus odot itoro</p>\n<p><strong>2.</strong><br>Mee anie okpo font’Abasi mi</p>\n<p>Obong Kima emi enyen enye ne de ono nyi</p>\n<p>O edi Kom Abasi mi sia om’odot itoro</p>\n<p>OBILIWO</p>\n<p>Alleluia Obiliwo,  Obiliwo Jesu akpogburu nelu obe onye mmeri</p>\n<p>Alleluia Obiliwo nezie Obiligo Jesu akpogburu nelu</p>\n<p>Nuzu ututu ka umu nwanyi jere nili ite ude nahu Jesu Muoma si nigwe gbadata nili wee si ha na Obiliwo</p>\n<p>Mary nebe akwa na acho ahu Jesu Mary neti nkpu nili Jesu Mary n\'akwughali ebe eliri Jesu mgbe ozutere Dinwenu</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'praise'),
	(132, 'WE HAVE COME, O LORD.', 'pending', NULL, '<p><strong>Chorus:</strong></p>\n<p>We have come oh Lord to worship you,</p>\n<p>we have come oh Lord to praise your holy name</p>\n<p>We have come to give you thanks</p>\n<p>We have come to honour you</p>\n<p>Come and dwell with us (x2)</p>\n<p><strong>Verse 1</strong></p>\n<p>This is the day the Lord has made,</p>\n<p>Let us rejoice and be glad in it.</p>\n<p>This is the time to commune with the Lord,</p>\n<p>Ah! Let us make the best of it</p>\n<p><strong>Verse 2</strong></p>\n<p>The Lord is kind and full of compassion,</p>\n<p>He knows how very weak we are.</p>\n<p>He is ready to forgive all our sins,</p>\n<p>Ah let us make the best of it.</p>\n<p><strong>Verse 3</strong></p>\n<p>The Lord knows our hearts, he knows our needs,</p>\n<p>He hears each time we call upon him</p>\n<p>He is ready to answer our plea</p>\n<p>ah let us make the best of it.</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'sanctus'),
	(133, 'VENI SANCTE SPIRITUS', 'traditional', NULL, '<p><strong>V</strong></p>\n<p><strong>V</strong></p>\n<p><strong>V</strong></p>\n<p><strong>V</strong></p>\n<p><strong>1.</strong><br>Come holy spirit from heaven shine forth with your glorious light veni sancte spiritus.</p>\n<p><strong>2.</strong><br>Come father of the poor come, generous spirit come light of our hearts veni sancte spiritus.</p>\n<p><strong>3.</strong><br>Come from the four winds o spirit come breath of God disperse the shadows over us renew and strengthen your people veni sancte spiritus</p>\n<p><strong>4.</strong><br>Most kindly warming light enter the in most depths of our hearts for we are faithful to you without your presence, we have nothing worthy, nothing pure. Veni sancte spiritus</p>\n<p><strong>5.</strong><br>You are our only comforter peace of the soul in the heart you shade us in our labor you refresh us and in trouble you are our strength. Veni sancte spiritus.</p>\n<p><strong>6.</strong><br>On all who put their trust in you and receive you in faith shower all your gifts. Grant that they may grow in you and preserve to the end give them lasting joy. Veni sancte spiritus.</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'holy_spirit'),
	(134, 'A GIFT FROM MY HEART', 'pending', NULL, '<p><strong>Refrain:</strong></p>\n<p>What shall I offer to the Lord to make Him happy</p>\n<p>What shall I offer to the Lord to please Him (2ce)</p>\n<p><strong>Verse 1</strong></p>\n<p>I may give Him the best of my clothes, He may not take it</p>\n<p>I may give Him the best of my shoes, He may not take it (2ce)</p>\n<p>A loving heart, a patient heart a humble heart a caring heart He will love</p>\n<p><strong>Verse 2</strong></p>\n<p>I may give Him the gift of a ram He may not take it</p>\n<p>I may give Him the gift of a cow He may not take it (2ce)</p>\n<p>A loving heart, a patient heart a humble heart a caring heart He will love</p>\n<p><strong>Verse 3</strong></p>\n<p>I may give Him the gift of a car He may not take it</p>\n<p>I may give Him the gift of a house He may not take it (2ce)</p>\n<p>A loving heart, a patient heart a humble heart a caring heart He will love</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'offertory'),
	(135, 'BECAUSE HE LOVES US', 'pending', NULL, '<p>Verse 1</p>\n<p>Because He loves us sinful though we are, With a crescendo, we shall praise His name</p>\n<p>Chorus</p>\n<p>O join us our brithers and sisters</p>\n<p>In praising God for His love and mercy</p>\n<p>Join us all Ye works of the Lord</p>\n<p>In adoration in His Holy place</p>\n<p>Verse 2</p>\n<p>He is a Father who is always near</p>\n<p>O what a Father with a gracious heart</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'sanctus'),
	(136, 'SURRENDER YOUR HEART TO JESUS', 'pending', NULL, '<p><strong>Chorus:</strong></p>\n<p>Surrender your heart to Jesus; give him your love O</p>\n<p>Surrender your heart to Jesus today,</p>\n<p>Love of my soul, he will bless you and take care of your soul</p>\n<p>In everything that you do, surrender your heart to Jesus.</p>\n<p><strong>Verse 1</strong></p>\n<p>Wherever I go, he has been like a shadow on me,</p>\n<p>Wherever I go, I find Jesus ever near me,</p>\n<p>Love of my soul, love of my life, I’ll always be your love. - Chorus</p>\n<p><strong>Verse 2</strong></p>\n<p>Whatever I do, O the everlasting love,</p>\n<p>Whatever I do, has been through his wonderful love,</p>\n<p>Love of my soul, love of my life, I’ll always be your love. - Chorus</p>\n<p><strong>Verse 3</strong></p>\n<p>Whoever I am, Jesus has made me in his love,</p>\n<p>Whoever I am, Jesus has brought me this far,</p>\n<p>Love of my soul, love of my life, I’ll always be your love. - Chorus</p>\n<p>Hanma Shie</p>\n<p><strong>1.</strong><br>Zenden shin tar ne Ambatio mov nav hanma shie hanma jiir (2×)</p>\n<p><strong>Chorus:</strong></p>\n<p>Hanma shie haan, han-ma shie haan, han-ma shie han-ma shie hanma jiir (2×) *A-mbatio mov nav Ken Jerusalem hanma shie hanma shie hanma jiir</p>\n<p><strong>2.</strong><br>Tesen se kwaghfan wou sha u dondon gbenda wou... hanma</p>\n<p><strong>Chorus:</strong><br>*A mbatiomov nav Ken Jadia*</p>\n<p><strong>3.</strong><br>Eren se baptisima sha u nyorun Ken ya wou hanma...</p>\n<p><strong>Chorus:</strong><br>*A mbatiomov nav Ken Kafanahum*</p>\n<p><strong>4.</strong><br>Yes se mba yilan we va kohol se shintarne hanma...</p>\n<p><strong>Chorus:</strong><br>*A mbatiomov nav ken  Galalia*</p>\n<p><strong>5.</strong><br>Shin tar ne se gba kwagh ga kpa u van hen vese abem hanma...</p>\n<p><strong>Chorus:</strong><br>*A mbatiomov nav Ken Sidon*</p>\n<p><strong>Responsorial psalm:</strong></p>\n<p><strong>Chorus:</strong></p>\n<p>Poor man call, papa God hear\'am</p>\n<p><strong>Verse 1</strong></p>\n<p>I go Bless papa God all the times</p>\n<p>Im praise go de dey for my mouth dey go</p>\n<p>Inside God, my soul go dey do shakara</p>\n<p>Pesin wen humble go happy wen e hear\'am</p>\n<p><strong>Verse 2</strong></p>\n<p>Papa God go bone all the bad and wicked people</p>\n<p>Make dia generations for kpafuka for this world</p>\n<p>When pesin wen pure(pio) hala God</p>\n<p>God go hear\'am come save am from all im worry worry.</p>\n<p><strong>Verse 3</strong></p>\n<p>Papa God nia people wey dia mind don spoil, Him go save person wey im spirit don kpeme.</p>\n<p>God go pay for the souls of im servants, people wey trust am no go suffer</p>\n<p>JESUS AHA NA ATO MUTO</p>\n<p>Jesus aha na tomuto Jesus aha na to muto Jesus aha kachasie bube site nu gwu rue na ndi da Jesus aha gi diu to...</p>\n<p>Jesus Jesus Jesus aha kachasie bube nenye ndu</p>\n<p><strong>1.</strong><br>Ihu nanya nke Jesus  2x</p>\n<p>Ihu nanya nke Jesus enwe ghi mgbanwo bula</p>\n<p>Ihu nanya 3x</p>\n<p>Ihu nanya ihu nanya nke Jesus nadi gi de o</p>\n<p><strong>2.</strong><br>Nime mkpagbum nile nime ahuhu nile nime nsogbum nile Jesus  nazo puta</p>\n<p>Obu Jesus 2x</p>\n<p>Obu Jesus nazoputa mo</p>\n<p>Nzo puta nke Jesus nadigide o</p>\n<p><strong>3.</strong><br>Jesus nwuru ni him 3x</p>\n<p>Ne lu o be onyenwem Jesus wee nwun ni him ne lu o be ko nwuru na calvary</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'repentance'),
	(137, 'GLORY TO GOD', 'Gabriel Momoh', NULL, '<p>Glory to God, glory to God, glory to God to God to God</p>\n<p>Glory to God, glory to God, glory to God in the highest</p>\n<p><strong>1.</strong><br>And on earth peace to men, peace to men of goodwill</p>\n<p>We praise you, we bless you</p>\n<p>we bless and worship you, we glorify your great name, we give you thanks O lord</p>\n<p><strong>2.</strong><br>Lord God heavenly king, lord God almighty father</p>\n<p>we praise you, we bless you</p>\n<p>Jesus Christ son of God, only son of the father</p>\n<p>Lord God lamb of God</p>\n<p><strong>3.</strong><br>Have mercy in us Lord</p>\n<p>You who takes away sins</p>\n<p>the sins of all mankind</p>\n<p>Have mercy on us Lord</p>\n<p>You who takes away sins</p>\n<p>receive our prayers O lord</p>\n<p><strong>4.</strong><br>Have mercy on us Lord</p>\n<p>You who sits at the right hand</p>\n<p>Of the father in heaven</p>\n<p>You alone lord Jesus</p>\n<p>You alone are holy</p>\n<p>You alone are the most high</p>\n<p><strong>5.</strong><br>You alone lord Jesus</p>\n<p>with the holy spirit</p>\n<p>in the father\'s glory</p>\n<p>Amen, amen amen, amen</p>\n<p><strong>Ch:</strong><br>IDIMMA</p>\n<p><strong>Refrain:</strong></p>\n<p><strong>Ch:</strong><br>idimma, I di mma Chi n’eme mma. Onyen’enye onyinye, Chineke, Onye mma. Onyinye mara mma ka m jiri bia n’iru Gi. I diiri mu mma, Chidimma Onyemma.</p>\n<p><strong>Verse 1</strong></p>\n<p>Dika onye nche si atu anya chi obubo, ka mkpul’obi m si eche Dinwenu: Ih’Inemere m, Chineke, o juru m’anya. I diiri mu mma Chidimma, Onye mma. REF</p>\n<p><strong>Verse 2</strong></p>\n<p>Ka onye nche chekwube chi obubo, ma mu n’ezin’ulo mu, chekwube Dinwenu: Ih’Inemere m, Chineke, o juru m’anya. I diiri mu mma Chidimma, Onye mma. REF</p>\n<p><strong>Verse 3</strong></p>\n<p>I nyere m amamihe, aga m ekele Gi. I nyere m ogugo isi, aga m ekele Gi. Ih’Inemere m, Chineke, o juru m’anya. I diiri mu mma Chidimma, Onye mma. REF</p>\n<p><strong>Verse  4</strong></p>\n<p>O bu aku n’uba? O bu ihe onwunwe? Obu ego? Obu akwa? O bu nwa? Ih’Inemere m, Chineke, o juru m’anya. I diiri mu mma Chidimma, Onye mma. REF</p>\n<p>U-yio ghosa vbéhe no yo see</p>\n<p><strong>Verse 1</strong></p>\n<p>O-fun mwegbe vbéno ne mwan</p>\n<p>(Gi ma)r\'uyi n\'osa</p>\n<p>No ne mwan ren vb\'oto agbon</p>\n<p>Uyi n\'osa mwan</p>\n<p>Osa no yae mwan</p>\n<p>r\'uyi n\'osa</p>\n<p>Oba erhin mwin</p>\n<p>r\'uyi n\'osa</p>\n<p>Osa n\'erha no mwen tin hia</p>\n<p>uyi no n\'osa mwan</p>\n<p><strong>Verse 2</strong></p>\n<p>Magoon ruen ma rhie\'kpon mwen nuen</p>\n<p>(Gi ma) r\'uyi n\'osa</p>\n<p>Marhuo we y\'uyi we no khua</p>\n<p>Uyi n\'osa mwan</p>\n<p>Jesu Kristi</p>\n<p>r\'uyi n\'osa</p>\n<p>Noyae mwan</p>\n<p>r\'uyi n\'osa</p>\n<p>Ukp\'o mokpa oghe n\'e rha</p>\n<p>Uyi no n\'osa mwan</p>\n<p><strong>Chorus:</strong></p>\n<p>Uyi no n\'osa, r\'uyi n\'osa</p>\n<p>Uyi no n\'osa, r\'uyi n\'osa</p>\n<p>U-yio ghosa vbe no yo see</p>\n<p>U-yio ghosa no yo se-se</p>\n<p>Uyi no n\'osa r\'uyi n\'osa</p>\n<p>Uyi no n\'osa r\'uyi n\'osa</p>\n<p>Na do r\'uyi n\'osa mwan o</p>\n<p><strong>Verse 3</strong></p>\n<p>Osa no yae mwan ovbio haun osa</p>\n<p>(Gi ma)r\'uyi n\'osa</p>\n<p>Uwe no vbi\'o rukho agbon kua</p>\n<p>Uyi n\'osa mwan</p>\n<p>To han mwan</p>\n<p>r\'uyi n\'osa</p>\n<p>Osa to han mwan</p>\n<p>r\'uyi n\'osa</p>\n<p>We no to-ta y\'ob\'osa n\'e-rha</p>\n<p>Uyi no n\'osa mwan</p>\n<p><strong>Verse 4</strong></p>\n<p>We no to-ta y\'ob\'osa n\'erha</p>\n<p>(Gi ma)r\'uyi n\'osa</p>\n<p>Mi\'e rhunwun mwan mata tie we</p>\n<p>Uyi n\'osa mwan</p>\n<p>Rhun-wun-da we o-kpa</p>\n<p>r\'uyi n\'osa</p>\n<p>Ore no huan ren</p>\n<p>r\'uyi n\'osa</p>\n<p>U w\'o kpa o no yae mwan</p>\n<p>Uyi no n\'osa mwan</p>\n<p><strong>Chorus:</strong></p>\n<p>Uyi no n\'osa, r\'uyi n\'osa</p>\n<p>Uyi no n\'osa, r\'uyi n\'osa</p>\n<p>U-yio ghosa vbe no yo see</p>\n<p>U-yio ghosa no yo se-se</p>\n<p>Uyi no n\'osa r\'uyi n\'osa</p>\n<p>Uyi no n\'osa r\'uyi n\'osa</p>\n<p>Na do r\'uyi n\'osa mwan o</p>\n<p><strong>Verse 5</strong></p>\n<p>Uw\'okpa o re no yo se-e</p>\n<p>(Gi ma) r\'uyi n\'osa</p>\n<p>Jesu Kristi deba ehrin mwin</p>\n<p>Uyi n\'osa mwan</p>\n<p>Erhin mwin no huan ren</p>\n<p>r\'uyi n\'osa</p>\n<p>Erhin mwin no huan ren</p>\n<p>r\'uyi n\'osa</p>\n<p><strong>V</strong></p>\n<p>Uyi no n\'osa mwan</p>\n<p><strong>Chorus:</strong></p>\n<p>Uyi no n\'osa, r\'uyi n\'osa</p>\n<p>Uyi no n\'osa, r\'uyi n\'osa</p>\n<p>U-yio ghosa vbe no yo see</p>\n<p>U-yio ghosa no yo se-se</p>\n<p>Uyi no n\'osa r\'uyi n\'osa</p>\n<p>Uyi no n\'osa r\'uyi n\'osa</p>\n<p>Na do r\'uyi n\'osa mwan o</p>\n<p>(I se o) I se o.</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'gloria'),
	(138, 'THE LORD IS WONDERFUL', 'pending', NULL, '<p><strong>1.</strong><br>I daily pass along</p>\n<p>So happy with my savior</p>\n<p>He’s keeping me within the path of right</p>\n<p>He’s living in my heart, from him I will not waver</p>\n<p>He’s leading me by heaven’s holy light.</p>\n<p><strong>Chorus:</strong></p>\n<p>The Lord is wonderful,</p>\n<p>Yes He’s so wonderful</p>\n<p>He filled my soul with joy I never knew</p>\n<p>The Lord is wonderful,</p>\n<p>Yes He’s so wonderful</p>\n<p>He blesses me in everything I do</p>\n<p><strong>2.</strong><br>There’s joy within my soul</p>\n<p>I just can’t keep from telling</p>\n<p>It’s bubbling bubbling bubbling night and day</p>\n<p>It can’t be very long, ‘till with him I’ll be dwelling</p>\n<p>And trusting him to lead me all the way</p>\n<p><strong>3.</strong><br>Great peace I have today</p>\n<p>To him all glory belong</p>\n<p>All glory glory unto him</p>\n<p>And his sufficient grace</p>\n<p>is enough to see me through</p>\n<p>And make me dwell with him eternally.</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'sanctus'),
	(139, 'BECAUSE HE LIVES', 'pending', NULL, '<p><strong>1.</strong><br>God sent His son</p>\n<p>They called Him Jesus</p>\n<p>He came to love</p>\n<p>Heal and forgive</p>\n<p>He bled and died</p>\n<p>To buy my pardon</p>\n<p>An empty grave</p>\n<p>Is there to prove</p>\n<p>My savior lives</p>\n<p><strong>Chorus:</strong></p>\n<p>Because He lives</p>\n<p>I can face tomorrow</p>\n<p>Because He lives</p>\n<p>All fear is gone</p>\n<p>Because I know</p>\n<p>He holds the future</p>\n<p>And life is worth the living</p>\n<p>Just because He lives</p>\n<p><strong>2.</strong><br>And then one day</p>\n<p>I\'ll cross the river</p>\n<p>And I\'ll fight life\'s final war with pain</p>\n<p>And then</p>\n<p>As death gives way to victory</p>\n<p>I\'ll see the lights of glory</p>\n<p>And I\'ll know He reigns</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'general'),
	(140, 'SING PRAISE TO THE LIVING GOD', 'pending', NULL, '<p><strong>VERSE 1</strong></p>\n<p>Sing praise to the living God, Glory Halleluia.</p>\n<p>Come adore the living God, Glory Halleluia,</p>\n<p>Though sun and moon may pass away,</p>\n<p>His word will ever stay</p>\n<p>His power is forevermore, Glory Halleluia.</p>\n<p><strong>Chorus:</strong></p>\n<p>Glory to the Trinity, the undivided unity.</p>\n<p>The Father; Son and Spirit One,</p>\n<p>From whom all life and goodness come.</p>\n<p><strong>VERSE 2</strong></p>\n<p>To the living God we sing, Glory, Halleluia,</p>\n<p>Let our love and praises ring, Glory, Halleluia.</p>\n<p>To His sons, He always</p>\n<p>gives His mercy and His love.</p>\n<p>Praise Him now forevermore, Glory, Halleluia.</p>\n<p><strong>VERSE 3</strong></p>\n<p>To the God who cannot die, Glory, Halleluia</p>\n<p>To the living God we cry, Glory, Halleluia</p>\n<p>He promised to be with us</p>\n<p>and He lives in everyone</p>\n<p>Love Him now forevermore, Glory, Halleluia.</p>\n<p>BE WITH US LORD</p>\n<p><strong>Chorus:</strong></p>\n<p>Be with us Father we need your blessings,</p>\n<p>Be with us son, we need your presence,</p>\n<p>Be with us spirit we need your power,</p>\n<p>As we come to worship you Lord.</p>\n<p><strong>Verse 1</strong></p>\n<p>Standing in your presence Father,</p>\n<p>We\'re declaring our love for you.</p>\n<p>Watching and waiting with face lifted high up,</p>\n<p>As we long for your power from high,</p>\n<p>We raise our voice in praise, in worship to you our God.</p>\n<p><strong>Chorus:</strong></p>\n<p><strong>Verse 2</strong></p>\n<p>King of kings, Lord of lords, mighty redeemer,</p>\n<p>The creator of heaven and earth,</p>\n<p>Lord we bring ourselves before you,</p>\n<p>Take our hearts so filled with love,</p>\n<p>We raise our voice in praise, in worship to you our God.</p>\n<p><strong>Chorus:</strong></p>\n<p><strong>Verse 3</strong></p>\n<p>Lord we raise our voice to you, with praises on our lips,</p>\n<p>All creation bow before you.</p>\n<p>Everyone shall call you Lord, you are the maker of all things living,</p>\n<p>Come and rule over all our hearts.</p>\n<p><strong>Chorus:</strong></p>\n<p>I am the living bread</p>\n<p><strong>Verse 1</strong></p>\n<p>I am the living bread which has come down from heaven</p>\n<p>Anyone who eats this bread will live forever and ever</p>\n<p><strong>Chorus:</strong></p>\n<p>Come and eat my body</p>\n<p>And drink my blood</p>\n<p>I will give you peace and eternal life.</p>\n<p><strong>Verse 2</strong></p>\n<p>I tell you solemnly:</p>\n<p>If you do not eat my flesh</p>\n<p>If you do not drink my blood</p>\n<p>If you do not eat the flesh of the Son of man</p>\n<p>You will have no life in you. Chorus</p>\n<p><strong>Verse 3</strong></p>\n<p>Anyone who eats my body and drinks my blood shall live</p>\n<p>For ever and ever</p>\n<p>I shall raise him up</p>\n<p>I shall raise him up</p>\n<p>I shall raise him up</p>\n<p>On the last day. Chorus</p>\n<p><strong>Verse 4</strong></p>\n<p>Whosoever eats my flesh</p>\n<p>Whosoever drinks my blood</p>\n<p>Whosoever eats my flesh and drinks of my blood</p>\n<p>Shall live in me and I in him. Chorus</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'communion'),
	(141, 'OGO F\'OLORUN LOKE ORUN', 'pending', NULL, '<p><strong>Chorus:</strong></p>\n<p>Ogo  f’olorun loke orun x2</p>\n<p>Ala afia si ni laye fawon eniyan to ni ife inu rere</p>\n<p><strong>Verse 1</strong></p>\n<p>Inyin ni fuo o,</p>\n<p>I bukun ni fuo,</p>\n<p>A fo ri bale fun o,</p>\n<p>Ope ni fun o,</p>\n<p>Nitori ola,</p>\n<p>ati\'ogo, ati\'ogo, nla Re.</p>\n<p><strong>Refrain:</strong><br>.</p>\n<p>Ogo  f’olorun loke orun</p>\n<p><strong>Verse 2</strong></p>\n<p>Baba Olodumare,</p>\n<p>Oluwa olorun Oba orun,</p>\n<p>Jesu Kristi, Omo bibi Re,</p>\n<p>Nikan soso o,</p>\n<p>Odo\'aguntan Olorun,</p>\n<p>Omo ti baba.</p>\n<p><strong>Refrain:</strong><br>.</p>\n<p>Ogo  f’olorun loke orun</p>\n<p><strong>Chorus:</strong></p>\n<p>Ogo  f’olorun loke orun x2</p>\n<p>Ala afia si ni laye fawon eniyan to ni ife inu rere</p>\n<p><strong>Verse 3</strong></p>\n<p>Oun lo k\'ese aye lo,</p>\n<p>Saa nu fun wa,</p>\n<p>Oun lo k\'ese aye lo,</p>\n<p>Gbadurawa,</p>\n<p>Ojoko lo wo,</p>\n<p>Otun baba,</p>\n<p>Saa nu fun wa,</p>\n<p><strong>Refrain:</strong><br>.</p>\n<p>Ogo  f’olorun loke orun</p>\n<p>Oun nikan ni mimo,</p>\n<p>At\'Oluwa,</p>\n<p>Jesu Kristi, nikan lo ga ju lo.</p>\n<p><strong>Refrain:</strong><br>.</p>\n<p>Ogo  f’olorun loke orun</p>\n<p><strong>Chorus:</strong></p>\n<p>Ogo  f’olorun loke orun x2</p>\n<p>Ala afia si ni laye fawon eniyan to ni ife inu rere</p>\n<p>CODA:</p>\n<p>Pelu emi mimo,</p>\n<p>Ati ogo Olorun baba,</p>\n<p>Amin.</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'gloria'),
	(142, 'SECOND CHANCE', 'pending', NULL, '<p>Lord I need your presence that I may be free from sins guide o Lord through thy ways save me Lord or I die please pardon me of my guilt wash away my sins save me Lord give me second chance that I may l live, save me Lord or I die</p>\n<p><strong>1.</strong><br>I am old in sin I was born I have lived in sin all my life I have come to you o Jesus save me Lord or I die give Lord a second chance<br>2<br>I have lived a life of deceit and I cheated I scorned I dishonoured I surrender to you Jesus save me Lord or I die give Lord a second chance<br>3<br>Christ the rock on you I depend comfort me take me as I am o Lord give me your grace to live save me Lord or I die give Lord a second chance</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'repentance'),
	(143, 'LORD, I\'M COMING HOME', 'pending', NULL, '<p><strong>1.</strong><br>I\'ve wandered far away from God,</p>\n<p>Now I\'m coming home;</p>\n<p>The paths of sin too long I\'ve trod,</p>\n<p>Lord, I\'m coming home.</p>\n<p><strong>Refrain:</strong></p>\n<p>Coming home, coming home,</p>\n<p>Nevermore to roam,</p>\n<p>Open wide Thine arms of love,</p>\n<p>Lord, I\'m coming home.</p>\n<p><strong>2.</strong><br>I\'ve wasted many precious years,</p>\n<p>Now I\'m coming home;</p>\n<p>I now repent with bitter tears,</p>\n<p>Lord, I\'m coming home. [Refrain]</p>\n<p><strong>3.</strong><br>I\'ve tired of sin and straying, Lord,</p>\n<p>Now I\'m coming home;</p>\n<p>I\'ll trust Thy love, believe Thy word,</p>\n<p>Lord, I\'m coming home. [Refrain]</p>\n<p><strong>4.</strong><br>My soul is sick, my heart is sore,</p>\n<p>Now I\'m coming home;</p>\n<p>My strength renew, my hope restore,</p>\n<p>Lord, I\'m coming home. [Refrain]</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'creed'),
	(144, 'AS I LOOK UNTO THE CROSS', 'pending', NULL, '<p><strong>Chorus:</strong></p>\n<p>I know , I know Christ is my Lord</p>\n<p>I’ve come to know He died for me</p>\n<p>i say goodbye to the evil world</p>\n<p>I know my Lord will care for me</p>\n<p>eeeh eeh…</p>\n<p>As I look up to the cross on which he died</p>\n<p>I can hear him say it is ended</p>\n<p><strong>Ch:</strong><br>rist is calling all sinners to come to Him now,</p>\n<p>If you dont listen to Him, surely you will die</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'general'),
	(145, 'By the blood of Jesus Christ I know I’m saved,', 'pending', NULL, '<p>I know He loves me, He always says</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'communion'),
	(146, 'I WILL FOLLOW JESUS', 'pending', NULL, '<p><strong>1.</strong><br>Down in the valley with my Savior I would go,<br>Where the flowers are blooming and the sweet waters flow;<br>Everywhere He leads me I would follow, follow on,<br>Walking in His footsteps till the crown be won.</p>\n<p><strong>Chorus:</strong></p>\n<p>Follow! follow! I would follow Jesus!</p>\n<p>Anywhere, everywhere, I would follow on!</p>\n<p>Follow! follow! I would follow Jesus!</p>\n<p>Everywhere He leads me I would follow on!</p>\n<p><strong>2.</strong><br>Down in the valley with my Savior I would go,<br>Where the storms are sweeping and the dark waters flow;<br>With His hand to lead me I will never, never fear,<br>Dangers cannot fright me if my Lord is near.<br>3<br>Down in the valley, or upon the mountain steep,<br>Close beside my Savior would my heart ever keep;<br>He will lead me safely in the path that He has trod,<br>Up to where they gather in the rest of God.</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'general'),
	(147, 'MY SUFFERING JESUS', 'pending', NULL, '<p><strong>Chorus:</strong></p>\n<p>Jesus Christ you suffered,</p>\n<p>On the cross you suffered,</p>\n<p>Crucified to save a sinner me,</p>\n<p>See Him bleeding dying for me...Oh I love you dear Jesus mine.</p>\n<p><strong>Verse 1</strong></p>\n<p>Oh see the soldiers mocking Lord Jesus x2</p>\n<p>Pontius Pilate condemned Jesus to die,</p>\n<p>To die a shameful death on the cross</p>\n<p><strong>Chorus:</strong></p>\n<p><strong>Verse 2</strong></p>\n<p>Pls don\'t tell me how you felt mother Mary,</p>\n<p>Your dearest son Jesus to behold.</p>\n<p>What bruises and pains he endureth,</p>\n<p>O Mother you were so heartbroken</p>\n<p><strong>Verse 3</strong></p>\n<p>See how ruthlessly they nailed Him hands and feet,</p>\n<p>See how wickedly they left Jesus to die,</p>\n<p>See Him calling, weeping, sighing and dying,</p>\n<p>On the cross of Calvary.</p>\n<p><strong>Verse 4</strong></p>\n<p>See how he was given vinegar to drink,</p>\n<p>He how they cast lot for His beautiful garment,</p>\n<p>See how quietly our dear Lord Jesus died,</p>\n<p>Declaring that it is finished.</p>\n<p>KU TASHI SAI KUZO</p>\n<p>Ku tashi sai kuzo, Jesu ya na kira.</p>\n<p>Karbi shi, ci jikin shi.</p>\n<p>Abinchi ne me kyau</p>\n<p>Mai salama, mai iko, mai kauna ya na kiran mu.</p>\n<p>Mu karbi shi, mu zabe shi.</p>\n<p>Mai rayuwa, mai ceto.</p>\n<p>Ya Kristo, ya Kristo,</p>\n<p>Gamu munyi lefi,</p>\n<p>Ka wanke mu, da jinin sa,</p>\n<p>Mu samu lafiya har abada</p>\n<p>Godiya ni na ke, godiya ni na ke,</p>\n<p>Ga godiya abaki na, don Yesu na ya bani rai.</p>\n<p>Ku tashi sai kuzo, Jesu ya na kira.</p>\n<p>Karbi shi, ci jikin shi.</p>\n<p>Abinchi ne me kyau</p>\n<p>Glory in the cross</p>\n<p><strong>1.</strong><br>Let us ever glory in the cross of Christ,</p>\n<p>our salvation and our hope.</p>\n<p>Let us bow in homage to the Lord of Life,</p>\n<p>who was broken to make us whole.</p>\n<p>There is no greater love, as blessed as this:</p>\n<p>to lay down one’s life for a friend.</p>\n<p>Let us ever glory in the cross of Christ</p>\n<p>and the triumph of God’s great love.</p>\n<p><strong>2.</strong><br>Let us make our journey to the cross of Christ,</p>\n<p>who surrendered glory and grace</p>\n<p>to become a servant of the great and small,</p>\n<p>that all people may know God’s face.</p>\n<p>Though his birth was divine, he knelt as a slave,</p>\n<p>to wash common dust from our feet.</p>\n<p>Let us ever glory in the cross of Christ</p>\n<p>and the triumph of God’s great love.</p>\n<p><strong>3.</strong><br>Let us tell the story of the cross of Christ</p>\n<p>as we share this heavenly feast.</p>\n<p>We become one body in the blood of Christ,</p>\n<p>from the great to the very least.</p>\n<p>When we eat of this bread, and drink of this cup,</p>\n<p>we honor the death of the Lord.</p>\n<p>Let us ever glory in the cross of Christ</p>\n<p>and the triumph of God’s great love.</p>\n<p><strong>4.</strong><br>Let us stand together at the cross of Christ</p>\n<p>where we see God’s boundless love.</p>\n<p>We are saints and sinners who are joined</p>\n<p>by faith here on earth and heav’n above.</p>\n<p>Neither woman nor man, not servant or free,</p>\n<p>but one in the eyes of the Lord.</p>\n<p>Let us ever glory in the cross of Christ</p>\n<p>and the triumph of God’s great love.</p>\n<p>Amazing Grace* By Sam Ezugwu</p>\n<p>Amazing grace, how sweet the sound</p>\n<p>That saved a wretch like me</p>\n<p>I once was lost, but now I\'m found</p>\n<p>Was blind, but now I see</p>\n<p>Amazing Grace that I live, amazing grace of God</p>\n<p>\'Twas grace that taught my heart to fear</p>\n<p>And grace, my fears relieved</p>\n<p>How precious did that grace appear</p>\n<p>The hour I first believed</p>\n<p>Amazing Grace that I live, amazing grace of God</p>\n<p>Through many dangers, toils and snares</p>\n<p>We have already come</p>\n<p>\'Twas grace that brought us safe thus far</p>\n<p>And grace will lead us home</p>\n<p>Amazing Grace that I live, amazing grace of God</p>\n<p>When we\'ve been there ten thousand years</p>\n<p>Bright shining as the sun</p>\n<p>We\'ve no less days to sing God\'s praise</p>\n<p>Than when we first begun</p>\n<p>Than when we first begun</p>\n<p>Amazing Grace that I live, amazing grace of God</p>\n<p>Sanctus</p>\n<p>Holy holy holy, holy holy holy</p>\n<p>Lord God of power and might</p>\n<p>Heaven and earth are full of your glory, Lord God of power and might x2</p>\n<p>Hosanna ho-</p>\n<p>Hosanna in the highestx2</p>\n<p>Blessed is he who comes in the name of the Lord, Lord God of power and might x2</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'communion'),
	(148, 'AVO INDA', 'pending', NULL, '<p>Avo o Avo o Avo o Inda Avo avo avo..</p>\n<p>oricha avooo</p>\n<p>Avo</p>\n<p>Oricha avooo</p>\n<p>Avooo</p>\n<p>Oricha avo oo oo</p>\n<p>Avo oo Inda mmh</p>\n<p>Oza name yi za ono nya voni o I Jesu akoro</p>\n<p>O mei zoba nyi adaye ba Avo Inda (2x)</p>\n<p>Eme ro re Yani poro,</p>\n<p>Ohio zirenu, eme yaku Nye nwuje adaye ba Avo Inda lnda.</p>\n<p>Inda (adaye ba) lnda(adaye ba) Inda (adaye ba)</p>\n<p>(2x)</p>\n<p>Oza name yiza ono da ve ri</p>\n<p>(Oza name yi za ono davo voni o)x2</p>\n<p>Evoro kaye hiayi x3</p>\n<p>Avoro kaye hiayi da, eiye eiye eiye x2</p>\n<p>Inda avo oo, avoro kaye hiayi da, eiye eiye eiye x3</p>\n<p>Kozana me yizo nya vo ni,</p>\n<p>avoro kaye hiayi da, eiye eiye eiye ooooooo</p>\n<p>eiye eiye eiye ooooo</p>\n<p>Òzò zo ve yana kyada yeba,</p>\n<p>Avo inda, avo inda.</p>\n<p>Ozo zo ve yana ku Jesu,</p>\n<p>Avo inda, avo inda</p>\n<p>Òzò zo ve yana kyada yeba,</p>\n<p>Avo inda, avo inda.</p>\n<p>Inda- - - - avo yan gada x3</p>\n<p>Òzò zo ve yana kyada yeba,</p>\n<p>Ave ye husa, idi yan yeze</p>\n<p>Ave ye husa diyaje x3</p>\n<p>Nyeze Nyeze Nyeze Nyeze Nyeze Nyeze Nyeze Nyeze</p>\n<p>Nyeze Nyeze Nyeze</p>\n<p><strong>V</strong></p>\n<p><strong>V</strong></p>\n<p><strong>V</strong></p>\n<p><strong>V</strong></p>\n<p><strong>V</strong></p>\n<p><strong>V</strong></p>\n<p><strong>V</strong></p>\n<p><strong>V</strong></p>\n<p>(Repeat as much as possible)</p>\n<p>Ave ye husa diya je!!!!!!!!</p>\n<p>Eee!!!!!!!</p>\n<p>Avo inda!!!!!!!!!!</p>\n<p>SOM NYAME</p>\n<p>Som nyame nyame som nyame nyame som nyame nyame som nyame</p>\n<p><strong>1.</strong><br>Ad ze bia ra ebee ye I be o bu ho a kunta</p>\n<p><strong>2.</strong><br>(Alto) Ad ze bia ra ebee ye I be o bu ho a kunta</p>\n<p><strong>3.</strong><br>Se papa a se bone a i be o bu ho a kunta</p>\n<p><strong>4.</strong><br>(Bass) Se papa a se bone a i be o bu ho a kunta</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'general'),
	(149, 'NA ORIRI DI ASO', 'pending', NULL, '<p>Chorus</p><p>Na oriri di aso ,</p><p>eluigwe n’uwa na emekorita, chukwu na mmadu aburu otu, ndi no n’eluigwe na ndi no n’uwa emekoria bie oma, buru otu n’ime muo (oru ebube),</p><p>oru itunanya yana ihe omimi, chineke bu amamihe n’onwe ya,</p><p>ihunanya ya ebukakwa,</p><p>umu mmadu kelenu chukwu, doo nna ekele diri gi chukwu.</p><p>Verse 1</p><p>Bia naranum rie bia naranum nuo,</p><p>Jesu gwara anyi niile,</p><p>onye riri ahum nuo obaram, ga ebi n’imem munwa ebiri n’ime ya…</p><p>Verse 2</p><p>Abum uzo buru ndu na eziokwu,</p><p>jesu gwara anyi niile,</p><p>onye sobe mu ga enwe ndu okpu,</p><p>ngwanu k’anyi sobe ya.</p><p><br></p>', '2026-04-08 19:19:26', '2026-05-12 13:08:46', 'Communion'),
	(150, 'UKOCHUKWU EBEBE', 'pending', NULL, '<p>Kristi Dinwenu UkoChukwu ebebe na ehunye achicha na mmanya dika Melkisedek</p>\n<p><strong>1.</strong><br>Dinwenu gwara Nna m ukwu nodu ala n\'aka nri m, aga m edote ndi iro gi n\'okpuru ukwu gi</p>\n<p><strong>2.</strong><br>Onyenweanyi ga-esi na Zion zite nkpo eze nke Ike gi chiwa ochichi n\'etiti ndi iro gi</p>\n<p><strong>3.</strong><br>Eze site n\'ubochi amuru gi n\'elu ugwu di nso tupu chi efoo esiri n\'afom muta gi</p>\n<p><strong>Bofi:</strong></p>\n<p><strong>Verse 1</strong></p>\n<p>Kimesese bofi bofi da Fagha akpor yerin</p>\n<p>Fagha akpor yerin o</p>\n<p>Kimesese bofi Tamara\'ngo da fagha fagha akpo yerin mou.</p>\n<p><strong>Chorus:</strong><br>Tamara\'ngo fio Tamarasin bouo  o</p>\n<p>Bouo 3x fi o bouo o da Fagha fagha Fagha akpor yerin mou.</p>\n<p><strong>2.</strong><br>Kimesese bou o bou o da fagha akpor yerin, fagha akpor yerin o<br>Kimesese bouo tamarasin bou o da fagha fagha akpor yerin o</p>\n<p><strong>Chorus:</strong></p>\n<p><strong>3.</strong><br>Zesu Kristi buru buru da fagha akpor yerin, fagha akpor yerin o</p>\n<p>Zesu Kristi buru Tamara\'ngo fio da fagha fagha akpor yerin o.</p>\n<p><strong>Chorus:</strong></p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'communion'),
	(151, 'ARA OLUWA', 'pending', NULL, '<p><strong>VERSE 1</strong></p>\n<p>Jesu mi wa fun mi l\'ara re</p>\n<p>Je ko si se l\'okan mi fa\'ara mi mo re bo mi o</p>\n<p>K\'esu ko ma r\'aye l\'okan mi o</p>\n<p>Wa Oluwa</p>\n<p>Wa, wa o, wa o</p>\n<p><strong>Chorus:</strong></p>\n<p>Baba oli nu re, Olu so re re</p>\n<p>Ore oloti to, Jesu Oba t\'o to</p>\n<p>Fa\'ara mi mo re bo mi o</p>\n<p>K\'esu ko ma raye l\'okan  mi o</p>\n<p>Wa Oluwa,</p>\n<p>Wa, wa o, wa o</p>\n<p><strong>VERSE 2</strong></p>\n<p>Jesu mi</p>\n<p>Wa fun mi l\'eje re, so mi d\'aja gun re</p>\n<p>Ki om\'okan mi le</p>\n<p>K\'esu ko ma raye l\'okan  mi o</p>\n<p>Wa Oluwa,</p>\n<p>Wa, wa o, wa o</p>\n<p><strong>VERSE 3</strong></p>\n<p>Jesu mi</p>\n<p>Wa s\'inu okan mi, wa s\'inu okan mi</p>\n<p>Fa\'ara mi mo re bo mi o</p>\n<p>K\'esu ko ma raye l\'okan  mi o</p>\n<p>Wa Oluwa,</p>\n<p>Wa, wa o, wa o</p>\n<p>COMMUNION</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'communion'),
	(152, 'LORD I SEEK TO DO YOUR WILL', 'pending', NULL, '<p>Lord I seek to do your will</p>\n<p>Lord I seek to do your will</p>\n<p>Lord give me the grace to do your will.</p>\n<p>Lord I want  to do your will</p>\n<p>O blessed are those</p>\n<p>who hunger and thirst.</p>\n<p>Those who hunger and thirst</p>\n<p>for righteousness</p>\n<p>For they shall be filled</p>\n<p>Lord I want to do your will</p>\n<p>Proclaiming the good news,</p>\n<p>is doing your will;</p>\n<p>and singing your praises,</p>\n<p>is doing your will;</p>\n<p>also loving your neighbors,</p>\n<p>as you live yourself;</p>\n<p>Lord I want to do your will</p>\n<p>There is joy in the hearts of men;</p>\n<p>there is happiness in the life of those who believe,</p>\n<p>in abundance there are blessings;</p>\n<p>for those who trust in the Lord and  do his will.</p>', '2026-04-08 19:19:26', '2026-04-08 19:19:26', 'praise'),
	(159, 'TAKE AND SANCTIFY', 'Jude Nnam', NULL, '<p><strong>Chorus:</strong></p>\n<p>Take and sanctify, for Your honour Lord</p>\n<p>And sanctify these gifts</p>\n<p>Take and sanctify these gifts</p>\n<p>For Your honour, Lord</p>\n<p><strong>1.</strong><br>All that I am, all that I do</p>\n<p>Everything I will ever make</p>\n<p>Take my life and take my all</p>\n<p>Everything I will ever make</p>\n<p><strong>2.</strong><br>All our bread, all our wine</p>\n<p>Everything we will ever bring</p>\n<p>Take our gifts and sanctify</p>\n<p>Everything we will ever bring</p>\n<p><strong>3.</strong><br>All our pain, all our joy</p>\n<p>Everything we will ever feel</p>\n<p>Take our hearts and sanctify</p>\n<p>Everything we will ever feel</p>', '2026-04-08 19:32:21', '2026-04-08 19:32:21', 'offertory'),
	(160, 'O YES IN THE PRESENCE OF THE LORD', 'Jude Nnam', NULL, '<p><strong>Chorus:</strong></p>\n<p>O yes, in the presence of the Lord</p>\n<p>I will bring my gifts</p>\n<p>In thanksgiving and love</p>\n<p>There is joy in my heart</p>\n<p>It is flowing like a river</p>\n<p>I will praise the Lord</p>\n<p>In thanksgiving and love</p>\n<p><strong>1.</strong><br>God our Father, everlasting King</p>\n<p>Please accept this gift we offer</p>\n<p>Take our bread upon Your altar</p>\n<p>And our wine in the chalice</p>\n<p><strong>2.</strong><br>With thankful hearts and joyful songs</p>\n<p>We approach Your holy altar</p>\n<p>Bearing gifts of Your creation</p>\n<p>We return what You have given</p>\n<p><strong>3.</strong><br>To You Father, now we offer</p>\n<p>With the host and with the chalice</p>\n<p>All we have and all our being</p>\n<p>In this sacrifice most holy</p>', '2026-04-08 19:32:21', '2026-04-08 19:32:21', 'offertory'),
	(161, 'INTO YOUR SANCTUARY', 'Ifeanyichukwu Eze', NULL, '<p><strong>Chorus:</strong></p>\n<p>Into Your Sanctuary</p>\n<p>We\'ve come to adore You Lord</p>\n<p>Into Your Sanctuary</p>\n<p>We\'ve come to worship You</p>\n<p><strong>1.</strong><br>We thank the Lord for the gift of life</p>\n<p>And reverence His holy name</p>\n<p>As our God</p>\n<p><strong>2.</strong><br>With sweet melody of joy</p>\n<p>Our mouth is full of praise</p>\n<p>For one day in Your House</p>\n<p>Is better than a thousand elsewhere</p>\n<p><strong>3.</strong><br>Hide us under the shadow</p>\n<p>Of Your wings oh Lord</p>\n<p>Fill us with Your Holy Spirit</p>\n<p>For ever more</p>', '2026-04-08 19:32:21', '2026-04-08 19:32:21', 'processional'),
	(162, 'A PRIEST FOREVER', 'Jude Nnam', NULL, '<p><strong>Chorus:</strong></p>\n<p>You are a priest forever and ever</p>\n<p>A priest like Melchizedek of old</p>\n<p>You are a priest forever and ever</p>\n<p>A priest like Melchizedek of old</p>\n<p><strong>1.</strong><br>The Lord\'s revelation to my master</p>\n<p>"Sit on my right hand on high</p>\n<p>Until I make your enemies</p>\n<p>Your footstool"</p>\n<p><strong>2.</strong><br>The Lord will send from Zion</p>\n<p>Your sceptre of power</p>\n<p>Rule in the midst of all your foes</p>\n<p>Your people will offer themselves</p>\n<p><strong>3.</strong><br>On the day You lead Your forces</p>\n<p>To the holy mountains</p>\n<p>From the womb before the dawn</p>\n<p>I begot You</p>', '2026-04-08 19:32:21', '2026-04-08 19:32:21', 'general'),
	(163, 'DO YOU BELIEVE', 'Jude Nnam', NULL, '<p><strong>Chorus:</strong></p>\n<p>Do you believe in God the Father</p>\n<p>Do you believe in Christ the Son</p>\n<p>Do you believe in the Holy Spirit</p>\n<p>Do you believe in the Three in One</p>\n<p><strong>1.</strong><br>I believe in God the Father</p>\n<p>Maker of heaven and earth</p>\n<p>And in Jesus Christ His only Son</p>\n<p>Our Lord and Savior</p>\n<p><strong>2.</strong><br>Conceived by the Holy Spirit</p>\n<p>Born of the Virgin Mary</p>\n<p>Suffered under Pontius Pilate</p>\n<p>Crucified died and was buried</p>\n<p><strong>3.</strong><br>On the third day He rose again</p>\n<p>He ascended into heaven</p>\n<p>He will come again to judge</p>\n<p>The living and the dead</p>', '2026-04-08 19:32:21', '2026-04-08 19:32:21', 'creed'),
	(164, 'UBI CARITAS', 'traditional', NULL, '<p><strong>Latin:</strong></p>\n<p>Ubi caritas et amor, Deus ibi est</p>\n<p>Congregavit nos in unum Christi amor</p>\n<p>Exsultemus, et in ipso jucundemur</p>\n<p>Timeamus, et amemus Deum vivum</p>\n<p>Et ex corde diligamus nos sincero</p>\n<p><strong>English:</strong></p>\n<p>Where charity and love are, God is there</p>\n<p>Love of Christ has gathered us into one</p>\n<p>Let us rejoice in Him and be glad</p>\n<p>Let us fear, and let us love the living God</p>\n<p>And from a sincere heart let us love one</p>\n<p>Ubi caritas et amor, Deus ibi est</p>\n<p>Simul ergo cum in unum congregamur</p>\n<p>Ne nos mente dividamur, caveamus</p>\n<p>Cessent iurgia maligna, cessent lites</p>\n<p>Et in medio nostri sit Christus Deus</p>\n<p>Ubi caritas et amor, Deus ibi est</p>', '2026-04-08 19:32:21', '2026-04-08 19:32:21', 'communion'),
	(165, 'PANGE LINGUA GLORIOSI', 'St. Thomas Aquinas', NULL, '<p><strong>1.</strong><br>Pange lingua gloriosi</p>\n<p>Corporis mysterium</p>\n<p>Sanguinisque pretiosi</p>\n<p>Quem in mundi pretium</p>\n<p>Fructus ventris generosi</p>\n<p>Rex effudit gentium</p>\n<p><strong>2.</strong><br>Nobis datus, nobis natus</p>\n<p>Ex intacta Virgine</p>\n<p>Et in mundo conversatus</p>\n<p>Sparso verbi semine</p>\n<p>Sui moras incolatus</p>\n<p>Miro clausit ordine</p>\n<p><strong>3.</strong><br>In supremae nocte cenae</p>\n<p>Recumbens cum fratribus</p>\n<p>Observata lege plene</p>\n<p>Cibis in legalibus</p>\n<p>Cibum turbae duodenae</p>\n<p>Se dat suis manibus</p>\n<p><strong>4.</strong><br>Verbum caro, panem verum</p>\n<p>Verbo carnem efficit</p>\n<p>Fitque sanguis Christi merum</p>\n<p>Et si sensus deficit</p>\n<p>Ad firmandum cor sincerum</p>\n<p>Sola fides sufficit</p>\n<p><strong>5.</strong><br>Tantum ergo Sacramentum</p>\n<p>Veneremur cernui</p>\n<p>Et antiquum documentum</p>\n<p>Novo cedat ritui</p>\n<p>Praestet fides supplementum</p>\n<p>Sensuum defectui</p>\n<p><strong>6.</strong><br>Genitori, Genitoque</p>\n<p>Laus et jubilatio</p>\n<p>Salus, honor, virtus quoque</p>\n<p>Sit et benedictio</p>\n<p>Procedenti ab utroque</p>\n<p>Compar sit laudatio. Amen</p>\n<p><strong>English Translation:</strong></p>\n<p>Sing my tongue the Savior\'s glory</p>\n<p>Of His flesh the mystery sing</p>\n<p>Of the Blood all price exceeding</p>\n<p>Shed by our immortal King</p>\n<p>Destined for the world\'s redemption</p>\n<p>From a noble womb to spring</p>', '2026-04-08 19:32:21', '2026-04-08 19:32:21', 'communion'),
	(166, 'TANTUM ERGO SACRAMENTUM', 'St. Thomas Aquinas', NULL, '<p><strong>Latin:</strong></p>\n<p>Tantum ergo Sacramentum</p>\n<p>Veneremur cernui</p>\n<p>Et antiquum documentum</p>\n<p>Novo cedat ritui</p>\n<p>Praestet fides supplementum</p>\n<p>Sensuum defectui</p>\n<p>Genitori, Genitoque</p>\n<p>Laus et jubilatio</p>\n<p>Salus, honor, virtus quoque</p>\n<p>Sit et benedictio</p>\n<p>Procedenti ab utroque</p>\n<p>Compar sit laudatio. Amen</p>\n<p><strong>English:</strong></p>\n<p>Down in adoration falling</p>\n<p>Lo the sacred Host we hail</p>\n<p>Lo o\'er ancient forms departing</p>\n<p>Newer rites of grace prevail</p>\n<p>Faith for all defects supplying</p>\n<p>Where the feeble senses fail</p>\n<p>To the everlasting Father</p>\n<p>And the Son who reigns on high</p>\n<p>With the Holy Spirit proceeding</p>\n<p>Forth from each eternally</p>\n<p>Be salvation honor blessing</p>\n<p>Might and endless majesty. Amen</p>', '2026-04-08 19:32:21', '2026-04-08 19:32:21', 'communion'),
	(167, 'HAIL HOLY QUEEN ENTHRONED ABOVE', 'traditional', NULL, '<p><strong>1.</strong><br>Hail holy Queen enthroned above</p>\n<p>O Maria</p>\n<p>Hail Mother of mercy and of love</p>\n<p>O Maria</p>\n<p><strong>Chorus:</strong></p>\n<p>Triumph all ye cherubim</p>\n<p>Sing with us ye seraphim</p>\n<p>Heaven and earth resound the hymn</p>\n<p>Salve salve salve Regina</p>\n<p><strong>2.</strong><br>Our life our sweetness here below</p>\n<p>O Maria</p>\n<p>Our hope in sorrow and in woe</p>\n<p>O Maria</p>\n<p><strong>3.</strong><br>As exiles all to you we cry</p>\n<p>O Maria</p>\n<p>Come soothe with hope our misery</p>\n<p>O Maria</p>\n<p><strong>4.</strong><br>Turn then most gracious advocate</p>\n<p>O Maria</p>\n<p>Toward us your eyes compassionate</p>\n<p>O Maria</p>\n<p><strong>5.</strong><br>O gentle loving holy one</p>\n<p>O Maria</p>\n<p>Make us each day more like your Son</p>\n<p>O Maria</p>\n<p><strong>6.</strong><br>And when from death to life we\'ve passed</p>\n<p>O Maria</p>\n<p>Show us your Son our Lord at last</p>\n<p>O Maria</p>', '2026-04-08 19:32:21', '2026-04-08 19:32:21', 'general'),
	(168, 'ADORO TE DEVOTE', 'St. Thomas Aquinas', NULL, '<p><strong>Latin:</strong></p>\n<p>Adoro te devote, latens Deitas</p>\n<p>Quae sub his figuris vere latitas</p>\n<p>Tibi se cor meum totum subjicit</p>\n<p>Quia te contemplans totum deficit</p>\n<p><strong>English:</strong></p>\n<p>Godhead hid devoutly I adore Thee</p>\n<p>Who truly art within the forms before me</p>\n<p>To Thee my heart I bow with bended knee</p>\n<p>As failing quite in contemplating Thee</p>\n<p>Visus tactus gustus in te fallitur</p>\n<p>Sed auditu solo tuto creditur</p>\n<p>Credo quidquid dixit Dei Filius</p>\n<p>Nil hoc verbo Veritatis verius</p>\n<p>Sight touch and taste in Thee are each deceived</p>\n<p>The ear alone most safely is believed</p>\n<p>I believe all the Son of God has spoken</p>\n<p>Than Truth\'s own word there is no truer token</p>\n<p>O memoriale mortis Domini</p>\n<p>Panis vivus vitam praestans homini</p>\n<p>Praesta menti meae de te vivere</p>\n<p>Et te illi semper dulce sapere</p>\n<p>O Thou memorial of our Lord\'s own dying</p>\n<p>O living bread to mortals life supplying</p>\n<p>Make Thou my soul henceforth on Thee to live</p>\n<p>Ever a taste of heavenly sweetness give</p>', '2026-04-08 19:32:21', '2026-04-08 19:32:21', 'communion'),
	(169, 'AVE VERUM CORPUS', 'traditional', NULL, '<p><strong>Latin:</strong></p>\n<p>Ave verum corpus natum</p>\n<p>De Maria Virgine</p>\n<p>Vere passum immolatum</p>\n<p>In cruce pro homine</p>\n<p>Cujus latus perforatum</p>\n<p>Unda fluxit et sanguine</p>\n<p>Esto nobis praegustatum</p>\n<p>In mortis examine</p>\n<p><strong>English:</strong></p>\n<p>Hail true body born</p>\n<p>Of the Virgin Mary</p>\n<p>Who truly suffered sacrificed</p>\n<p>On the cross for man</p>\n<p>From whose pierced side</p>\n<p>Blood streamed and flowed</p>\n<p>Be for us a foretaste</p>\n<p>Of the test of death</p>', '2026-04-08 19:32:21', '2026-04-08 19:32:21', 'communion'),
	(170, 'O SALUTARIS HOSTIA', 'St. Thomas Aquinas', NULL, '<p><strong>Latin:</strong></p>\n<p>O salutaris Hostia</p>\n<p>Quae caeli pandis ostium</p>\n<p>Bella premunt hostilia</p>\n<p>Da robur fer auxilium</p>\n<p>Uni trinoque Domino</p>\n<p>Sit sempiterna gloria</p>\n<p>Qui vitam sine termino</p>\n<p>Nobis donet in patria</p>\n<p><strong>English:</strong></p>\n<p>O saving Victim who of heaven</p>\n<p>Opens the gate</p>\n<p>Wars press hostile</p>\n<p>Give strength bear aid</p>\n<p>To the One and Threefold Lord</p>\n<p>May there be eternal glory</p>\n<p>Who life without end</p>\n<p>To us may give in the Fatherland</p>', '2026-04-08 19:32:21', '2026-04-08 19:32:21', 'communion'),
	(171, 'STABAT MATER DOLOROSA', 'traditional', NULL, '<p><strong>1.</strong><br>Stabat mater dolorosa</p>\n<p>Juxta crucem lacrimosa</p>\n<p>Dum pendebat filius</p>\n<p>Cuius animam gementem</p>\n<p>Contristatam et dolentem</p>\n<p>Pertransivit gladius</p>\n<p><strong>English:</strong></p>\n<p>At the cross her station keeping</p>\n<p>Stood the mournful Mother weeping</p>\n<p>Close to Jesus to the last</p>\n<p>Through her heart His sorrow sharing</p>\n<p>All His bitter anguish bearing</p>\n<p>Now at length the sword had passed</p>\n<p>O how sad and sore distressed</p>\n<p>Was that Mother highly blest</p>\n<p>Of the sole-begotten One</p>\n<p>Christ above in torment hangs</p>\n<p>She beneath beholds the pangs</p>\n<p>Of her dying glorious Son</p>', '2026-04-08 19:32:21', '2026-04-08 19:32:21', 'general'),
	(172, 'VENI CREATOR SPIRITUS', 'traditional', NULL, '<p><strong>1.</strong><br>Veni creator Spiritus</p>\n<p>Mentes tuorum visita</p>\n<p>Imple superna gratia</p>\n<p>Quae tu creasti pectora</p>\n<p><strong>2.</strong><br>Qui diceris Paraclitus</p>\n<p>Altissimi donum Dei</p>\n<p>Fons vivus ignis caritas</p>\n<p>Et spiritalis unctio</p>\n<p><strong>3.</strong><br>Tu septiformis munere</p>\n<p>Dextrae Dei tu digitus</p>\n<p>Tu rite promissum Patris</p>\n<p>Sermone ditans guttura</p>\n<p><strong>4.</strong><br>Accende lumen sensibus</p>\n<p>Infunde amorem cordibus</p>\n<p>Infirma nostri corporis</p>\n<p>Virtute firmans perpeti</p>\n<p><strong>5.</strong><br>Hostem repellas longius</p>\n<p>Pacemque dones protinus</p>\n<p>Ductore sic te praevio</p>\n<p>Vitemus omne noxium</p>\n<p><strong>6.</strong><br>Per te sciamus da Patrem</p>\n<p>Noscamus atque Filium</p>\n<p>Teque utriusque Spiritum</p>\n<p>Credamus omni tempore</p>\n<p><strong>7.</strong><br>Deo Patri sit gloria</p>\n<p>Et Filio qui a mortuis</p>\n<p>Surrexit ac Paraclito</p>\n<p>In saeculorum saecula</p>\n<p><strong>English:</strong></p>\n<p>Come Holy Ghost Creator blest</p>\n<p>And in our hearts take up Thy rest</p>\n<p>Come with Thy grace and heavenly aid</p>\n<p>To fill the hearts which Thou hast made</p>', '2026-04-08 19:32:21', '2026-04-08 19:32:21', 'holy_spirit'),
	(173, 'PANIS ANGELICUS', 'St. Thomas Aquinas', NULL, '<p><strong>Latin:</strong></p>\n<p>Panis angelicus fit panis hominum</p>\n<p>Dat panis caelicus figuris terminum</p>\n<p>O res mirabilis manducat Dominum</p>\n<p>Pauper pauper servus et humilis</p>\n<p>Te trina Deitas unaque poscimus</p>\n<p>Sic nos tu visita sicut te colimus</p>\n<p>Per tuas semitas duc nos quo tendimus</p>\n<p>Ad lucem quam inhabitas</p>\n<p><strong>English:</strong></p>\n<p>Heavenly bread that becomes the bread for all mankind</p>\n<p>Bread from the angelic host that is the end of all imaginings</p>\n<p>O miraculous thing this Body of God will nourish</p>\n<p>Even the poorest the most humble of servants</p>\n<p>O God one substance in Three Persons we beseech Thee</p>\n<p>Come to visit us as we adore Thee</p>\n<p>Guide us on Thy paths whither we direct our course</p>\n<p>To the light wherein Thou dost dwell</p>', '2026-04-08 19:32:21', '2026-04-08 19:32:21', 'communion'),
	(174, 'REGINA CAELI', 'traditional', NULL, '<p><strong>Latin:</strong></p>\n<p>Regina caeli laetare alleluia</p>\n<p>Quia quem meruisti portare alleluia</p>\n<p>Resurrexit sicut dixit alleluia</p>\n<p>Ora pro nobis Deum alleluia</p>\n<p><strong>English:</strong></p>\n<p>Queen of heaven rejoice alleluia</p>\n<p>For He whom thou wast worthy to bear alleluia</p>\n<p>Has risen as He said alleluia</p>\n<p>Pray for us to God alleluia</p>\n<p>Gaude et laetare Virgo Maria alleluia</p>\n<p>Quia surrexit Dominus vere alleluia</p>\n<p>Rejoice and be glad O Virgin Mary alleluia</p>\n<p>For the Lord has truly risen alleluia</p>', '2026-04-08 19:32:21', '2026-04-08 19:32:21', 'general'),
	(175, 'SALVE REGINA', 'traditional', NULL, '<p><strong>Latin:</strong></p>\n<p>Salve Regina mater misericordiae</p>\n<p>Vita dulcedo et spes nostra salve</p>\n<p>Ad te clamamus exsules filii Hevae</p>\n<p>Ad te suspiramus gementes et flentes</p>\n<p>In hac lacrimarum valle</p>\n<p>Eia ergo advocata nostra</p>\n<p>Illos tuos misericordes oculos ad nos converte</p>\n<p>Et Iesum benedictum fructum ventris tui</p>\n<p>Nobis post hoc exsilium ostende</p>\n<p>O clemens o pia o dulcis Virgo Maria</p>\n<p><strong>English:</strong></p>\n<p>Hail holy Queen Mother of mercy</p>\n<p>Hail our life our sweetness and our hope</p>\n<p>To thee do we cry poor banished children of Eve</p>\n<p>To thee do we send up our sighs mourning and weeping</p>\n<p>In this valley of tears</p>\n<p>Turn then most gracious advocate</p>\n<p>Thine eyes of mercy toward us</p>\n<p>And after this our exile show unto us</p>\n<p>The blessed fruit of thy womb Jesus</p>\n<p>O clement O loving O sweet Virgin Mary</p>', '2026-04-08 19:32:21', '2026-04-08 19:32:21', 'general'),
	(176, 'KYRIE ELEISON', 'traditional', NULL, '<p><strong>Greek:</strong></p>\n<p>Kyrie eleison</p>\n<p>Christe eleison</p>\n<p>Kyrie eleison</p>\n<p><strong>English:</strong></p>\n<p>Lord have mercy</p>\n<p>Christ have mercy</p>\n<p>Lord have mercy</p>\n<p><strong>Latin:</strong></p>\n<p>Kyrie eleison</p>\n<p>Christe eleison</p>\n<p>Kyrie eleison</p>\n<p>Domine miserere nobis</p>\n<p>Christe miserere nobis</p>\n<p>Domine miserere nobis</p>', '2026-04-08 19:32:21', '2026-04-08 19:32:21', 'general'),
	(177, 'GLORIA IN EXCELSIS DEO', 'traditional', NULL, '<p><strong>1.</strong><br>Gloria in excelsis Deo</p>\n<p>Et in terra pax hominibus bonae voluntatis</p>\n<p>Laudamus te benedicimus te</p>\n<p>Adoramus te glorificamus te</p>\n<p>Gratias agimus tibi propter magnam gloriam tuam</p>\n<p><strong>2.</strong><br>Domine Deus Rex caelestis</p>\n<p>Deus Pater omnipotens</p>\n<p>Domine Fili unigenite Iesu Christe</p>\n<p>Domine Deus Agnus Dei Filius Patris</p>\n<p>Qui tollis peccata mundi miserere nobis</p>\n<p>Qui tollis peccata mundi suscipe deprecationem nostram</p>\n<p>Qui sedes ad dexteram Patris miserere nobis</p>\n<p><strong>3.</strong><br>Quoniam tu solus Sanctus</p>\n<p>Tu solus Dominus</p>\n<p>Tu solus Altissimus Iesu Christe</p>\n<p>Cum Sancto Spiritu in gloria Dei Patris</p>\n<p>Amen</p>\n<p><strong>English:</strong></p>\n<p>Glory to God in the highest</p>\n<p>And on earth peace to people of good will</p>\n<p>We praise you we bless you</p>\n<p>We adore you we glorify you</p>\n<p>We give you thanks for your great glory</p>\n<p>Lord God heavenly King</p>\n<p>O God almighty Father</p>\n<p>Lord Jesus Christ Only Begotten Son</p>\n<p>Lord God Lamb of God Son of the Father</p>\n<p>You take away the sins of the world have mercy on us</p>\n<p>You take away the sins of the world receive our prayer</p>\n<p>You are seated at the right hand of the Father have mercy on us</p>\n<p>For you alone are the Holy One</p>\n<p>You alone are the Lord</p>\n<p>You alone are the Most High Jesus Christ</p>\n<p>With the Holy Spirit in the glory of God the Father</p>\n<p>Amen</p>', '2026-04-08 19:32:22', '2026-04-08 19:32:22', 'gloria'),
	(178, 'CHIZARA M', 'Jude Nnam', NULL, '<p><strong>Refrain:</strong></p>\n<p>I zara mo mgbe mkporo Gi eh</p>\n<p>Chukwu zara mo</p>\n<p>Chineke zara mo mgbe mkporo Ya eh</p>\n<p><strong>Chorus:</strong></p>\n<p>Butenu egwu ogene</p>\n<p>K\'anyi jee n\'altar Ya</p>\n<p>Butenu onyinye d\'ich\'iche</p>\n<p>K\'anyi jee be Chukwu o</p>\n<p><strong>1.</strong><br>O gini ka m g\'eji kele Gi o, Chukwu mo</p>\n<p>Naranu ekele mo, n\'Obioma Gi o</p>\n<p>O bu gini eh, ka m g\'eji kelee Gi o</p>\n<p>Naranu ekele e n\'Obioma Gi o</p>\n<p><strong>2.</strong><br>Mgbe ebili mmiri nk\'uwa n\'ebughari mo</p>\n<p>Ok\'ifufe fere mo, oyi mara mo</p>\n<p>Ih\'onyinye kacha mma ka m ji bia n\'ihu Gi o</p>\n<p>Onyinye si n\'obi, n\'adi Gi mma</p>', '2026-04-08 19:32:22', '2026-04-08 19:32:22', 'offertory'),
	(179, 'OLISA', 'Jude Nnam', NULL, '<p><strong>Chorus:</strong></p>\n<p>K\'anyi kelee Ya n\'orulu Ya</p>\n<p>Kelee Ya n\'okwesiri Ya</p>\n<p>Kelee Ya n\'oziere Ya</p>\n<p>Kelee Ya</p>\n<p>Olisa, Olisa</p>\n<p>Akam di nelu o, Olisa</p>\n<p><strong>1.</strong><br>Olisa, Onye nwe mba nile</p>\n<p>Olisa, Onye nwe uwa nile</p>\n<p>Ike a k\'uwa nile di n\'aka Gi</p>\n<p>Olisa, Akam di nelu o</p>\n<p><strong>2.</strong><br>Olisa, Onye nwe ike nile</p>\n<p>Olisa, Onye nke mma nile</p>\n<p>Ebube a k\'uwa nile di n\'aka Gi</p>\n<p>Olisa, Akam di nelu o</p>\n<p><strong>3.</strong><br>Olisa, Onye nwe mmeri nile</p>\n<p>Olisa, Onye nke eze nile</p>\n<p>Obioma Gi n\'ebukwu m anya</p>\n<p>Olisa, Akam di nelu o</p>', '2026-04-08 19:32:22', '2026-04-08 19:32:22', 'praise'),
	(180, 'TOBENNA', 'Jude Nnam', NULL, '<p><strong>Chorus:</strong></p>\n<p>Tobenna, To-be-nna</p>\n<p>Tobe Chukwu oma</p>\n<p>Umunne m bianu</p>\n<p>K\'anyi tobe Chukwu</p>\n<p>Tobe Chineke</p>\n<p>Chukwu Ony\'onyinye</p>\n<p>Na ara onyinye nk\'anyi n\'ebunye Ya</p>\n<p><strong>1.</strong><br>Tobenna, tobe Chukwu</p>\n<p>Onye nwe ike nile</p>\n<p>Onye nke mma nile</p>\n<p>Onye nwe mmeri nile</p>\n<p><strong>2.</strong><br>Tobenna, tobe Chineke</p>\n<p>Onye nke ndu nile</p>\n<p>Onye nke uwa nile</p>\n<p>Onye nke ebube nile</p>\n<p><strong>3.</strong><br>Tobenna, tobe Eze</p>\n<p>Onye nke ala nile</p>\n<p>Onye nke elu nile</p>\n<p>Onye nke ihe nile</p>', '2026-04-08 19:32:22', '2026-04-08 19:32:22', 'praise'),
	(181, 'WHY CAN\'T YOU SAY THANK YOU', 'Jude Nnam', NULL, '<p><strong>Chorus:</strong></p>\n<p>Why can\'t you say thank you</p>\n<p>To the One who made you</p>\n<p>Why can\'t you say thank you</p>\n<p>To the Lord who saved you</p>\n<p>Why can\'t you say thank you</p>\n<p>For all His blessings</p>\n<p>Why can\'t you say thank you</p>\n<p>To the King of kings</p>\n<p><strong>1.</strong><br>For the air that you breathe</p>\n<p>For the food that you eat</p>\n<p>For the life that you live</p>\n<p>Why can\'t you say thank you</p>\n<p><strong>2.</strong><br>For the love that He gives</p>\n<p>For the peace that He brings</p>\n<p>For the joy in your heart</p>\n<p>Why can\'t you say thank you</p>\n<p><strong>3.</strong><br>For the cross that He bore</p>\n<p>For the blood that He shed</p>\n<p>For the life that He gave</p>\n<p>Why can\'t you say thank you</p>', '2026-04-08 19:32:22', '2026-04-08 19:32:22', 'praise'),
	(182, 'KPAM SHIRI RIO CHUKWU', 'Jude Nnam', NULL, '<p><strong>Chorus:</strong></p>\n<p>Kpam shiri rio Chukwu</p>\n<p>Kpam shiri rio</p>\n<p>Kpam shiri rio Chukwu</p>\n<p>Kpam shiri rio</p>\n<p><strong>1.</strong><br>Chukwu b\'ike m</p>\n<p>O n\'enye m aka</p>\n<p>Chukwu b\'ndu m</p>\n<p>O n\'azoputa m</p>\n<p><strong>2.</strong><br>Chukwu b\'ife m</p>\n<p>O n\'edu mje edu</p>\n<p>Ife m mara mma</p>\n<p>Nwube nwube</p>\n<p><strong>3.</strong><br>Chineke elekwasago</p>\n<p>Manye ebere Ya</p>\n<p>Ez\'ebube elekwasago</p>\n<p>Manya mara Ya</p>', '2026-04-08 19:32:22', '2026-04-08 19:32:22', 'general'),
	(183, 'BIAM JAA YA MMA', 'Jude Nnam', NULL, '<p><strong>Chorus:</strong></p>\n<p>Biam jaa Ya mma</p>\n<p>Biam jaa Ya mma</p>\n<p>Biam jaa Ya mma</p>\n<p>Chukwu nke mma</p>\n<p><strong>1.</strong><br>O bu Chukwu nke mma</p>\n<p>O bu Chukwu nke ike</p>\n<p>O bu Chukwu nke ebube</p>\n<p>Jaa Ya mma</p>\n<p><strong>2.</strong><br>O bu Chukwu nke ndu</p>\n<p>O bu Chukwu nke udo</p>\n<p>O bu Chukwu nke ife</p>\n<p>Jaa Ya mma</p>\n<p><strong>3.</strong><br>O bu Chukwu nke ngozi</p>\n<p>O bu Chukwu nke imere</p>\n<p>O bu Chukwu nke ebere</p>\n<p>Jaa Ya mma</p>', '2026-04-08 19:32:22', '2026-04-08 19:32:22', 'praise'),
	(184, 'PRAISE TO THE HOLIEST', 'Pending', NULL, '<p>VERSE 1</p><p>Praise to the holiest in the height</p><p>And in the depth be praised,</p><p>In all his words most wonderful,</p><p>Most sure in all his ways.</p><p><br></p><p>VERSE 2</p><p>O loving wisdom of our God!</p><p>When all was sin and shame,</p><p>A second Adam to the fight</p><p>And to the rescue came.</p><p><br></p><p>VERSE 3</p><p>O wisest love! that flesh and blood</p><p>Which did in Adam fail,</p><p>Should strive afresh against their foe,</p><p>Should strive and should prevail.</p><p><br></p><p>VERSE 4</p><p>And that a higher gift than grace</p><p>Should flesh and blood refine,</p><p>God\'s presence and his very self,</p><p>And essence all divine.</p><p><br></p><p>VERSE 5</p><p>O generous love! that he who smote</p><p>In man for man the foe,</p><p>The double agony in man</p><p>For man should undergo.</p><p><br></p><p>VERSE 6</p><p>And in the garden secretly,</p><p>And on the cross on high,</p><p>Should teach his brethren, and inspire</p><p>To suffer and to die.</p><p><br></p><p><br></p><p>VERSE 7</p><p>Praise to the holiest in the height</p><p>And in the depth be praise,</p><p>In all his words most wonderful,</p><p>Most sure in all his ways.</p><p><br></p>', '2026-06-08 13:40:44', '2026-06-08 13:40:44', 'Entrance'),
	(185, 'Kyrie', 'Pending', NULL, '<p><br></p><p>Ky-ri-e, Elei-son</p><p>Ky-ri-e, Elei-son 2x</p><p><br></p><p>Chri-ste, Ele-ison</p><p>Chri-ste, Elei-son 2x</p><p><br></p><p>Ky-ri-e, Elei-son</p><p>Ky-ri-e, Elei-son</p><p><br></p>', '2026-06-08 13:41:16', '2026-06-08 13:41:16', 'Kyrie'),
	(187, 'Do you believe in one God, in one God', 'Jude Nnam', NULL, '<p>Chorus</p><p>Do you believe in one God, in one God in Jesus the son of God&nbsp;</p><p>In one God, in one Lord, who created Heaven and earth&nbsp;</p><p>in Jesus the son of God the savior of the world.</p><p><br></p><p>VERSE1</p><p>Conceived by the power of the spirit born in the virgin Mary,&nbsp;</p><p>He suffered under Pontius Pilate was crucified and died.</p><p><br></p><p>VERSE 2</p><p>He was buried in the earth, He rose up on the’ third day</p><p>He reigns with the father in Heaven, He will come to judge the world.</p><p><br></p><p>VERSE 3</p><p>I believe in the Ho-ly Spi-rit, the Holy Ca-tho-lic Church,</p><p>The co-mmu-nion of Saints, the for-give-ness of sin.</p><p><br></p><p>VERSE 4</p><p>The dead will rise on the last day to share in the life of God</p><p>A life that lasts for ev-er, In the glory of the Lord.</p><p><br></p>', '2026-06-08 13:43:07', '2026-06-08 13:43:07', 'Credo'),
	(188, 'Sanctus Libera', 'Pending', NULL, '<p>Sanctus, Sanctus, Sanctus&nbsp;</p><p><br></p><p>Sanctus Dominus Deus Sabaoth.</p><p>Pleni sunt caeli et terra gloria tua.</p><p>Sanctus Dominus Deus Sabaoth.</p><p>Pleni sunt caeli Glo-ria tua</p><p><br></p><p>Hosanna in excelsis. 2x</p><p><br></p><p>Benedic-tus benedictus qui venit in no-mine&nbsp;</p><p>Benedictus in nomine Do-mini 2x</p><p><br></p><p>Hosanna in excelsis.</p><p><br></p>', '2026-06-08 13:43:56', '2026-06-08 13:43:56', 'Sanctus'),
	(189, 'Agnus Dei, qui tollis peccata mundi,', 'Pending', NULL, '<p>Agnus Dei, qui tollis peccata mundi,&nbsp;</p><p>Lamb of God who takes away, the sins of the world</p><p>Have mer-cy on us, have mer-cy on us. 2x</p><p><br></p><p>Agnus Dei, qui tollis peccata mundi,&nbsp;</p><p>Lamb of God who takes away, the sins of the world</p><p>Grant us peace</p><p><br></p>', '2026-06-08 13:44:31', '2026-06-08 13:44:31', 'Agnus Dei'),
	(194, 'ONE BREAD, ONE BODY', 'Pending', NULL, '<p><br></p><p><br></p><p>One bread, one body, one Lord of all, one cup of blessing which we bless.</p><p>And we, though many, throughout the earth, we are one body in this one Lord.</p><p><br></p><p>Chorus</p><p>Gentile or Jew, servant or free, woman or man no more.</p><p>One bread, one body, one Lord of all, one cup of blessing which we bless.</p><p>And we, though many, throughout the earth, we are one body in this one Lord.</p><p><br></p><p>Many the gifts, many the works, one in the Lord of all.</p><p>One bread, one body, one Lord of all, one cup of blessing which we bless.</p><p>And we, though many, throughout the earth, we are one body in this one Lord.</p><p><br></p><p>Grain for the fields, scattered and grown, gathered to one for all.</p><p>One bread, one body, one Lord of all, one cup of blessing which we bless.</p><p>And we, though many, throughout the earth, we are one body in this one Lord.</p><p><br></p>', '2026-06-08 13:47:11', '2026-06-08 13:47:11', 'Communion'),
	(195, 'I am the Bread of Life', 'Pending', NULL, '<p><br></p><p>I am the bread of life.</p><p>He who comes to me shall not hunger;</p><p>he who believes in me shall not thirst.</p><p>No one can come to me</p><p>unless the Father draw him.</p><p><br></p><p>And I will raise him up,</p><p>and I will raise him up,</p><p>and I will raise him up on the last day.</p><p><br></p><p>The bread that I will give</p><p>is my flesh for the life of the world,</p><p>and he who eats of this bread,</p><p>he shall live for ever,</p><p>he shall live for ever.</p><p><br></p><p>Unless you eat</p><p>of the flesh of the Son of Man</p><p>and drink of his blood,</p><p>and drink of his blood,</p><p>you shall not have life within you.</p><p><br></p><p>I am the resurrection,</p><p>I am the life.</p><p>He who believes in me</p><p>even if he die,</p><p>he shall live forever.</p><p><br></p><p>Yes, Lord, I believe</p><p>that you are the Christ,</p><p>the Son of God,</p><p>who has come</p><p>into the world.</p><p><br></p>', '2026-06-08 13:48:07', '2026-06-08 13:48:07', 'Communion'),
	(196, 'GREAT VICTOR', 'Pending', NULL, '<p><br></p><p>Chorus:</p><p>Great Victor, Lord Jesus Christ!</p><p>Here we are in Your dwelling place.</p><p>With songs of praise and thanksgiving,</p><p>We honor You, Victorious King!</p><p>(Repeat Chorus)</p><p><br></p><p>Verse 1:</p><p>When the road is rough and the journey seems too long,</p><p>You are the strength of my life, my ever-present song.</p><p>Through the darkest night to the brightest day,</p><p>You are the comfort of my soul, my Restorer, Victorious King! [1]</p><p><br></p><p>Verse 2:</p><p>You draw near to the broken-hearted,</p><p>You heal the wounds that have torn us apart.</p><p>In You we find our shelter and our grace,</p><p>We worship You, Victorious King!</p><p><br></p><p>Verse 3:</p><p>You\'re the source of happiness,</p><p>Bringing peace when I am in distress.</p><p>You are the comfort of my soul,</p><p>My Restorer, Victorious King!</p><p><br></p>', '2026-06-08 13:48:43', '2026-06-08 13:48:43', 'Dismissal'),
	(197, 'Lord God Almighty (‎Holy Holy Holy )', 'Pending', NULL, '<p><br></p><p>VERSE 1</p><p>Holy, holy, holy!</p><p>Lord God almighty!</p><p>Early in the morning our song shall rise to thee;</p><p>Holy, holy, holy!</p><p>merciful and mighty!</p><p>God in three persons, blessed Trinity!</p><p><br></p><p>VERSE 2</p><p>Holy, holy, holy!</p><p>all the saints adore thee.</p><p>Casting down their golden crowns</p><p>around the glassy sea;</p><p>Cherubim and seraphim falling down before thee,</p><p>Which wert, and art and evermore shalt be.</p><p><br></p><p>VERSE 3</p><p>Holy, holy, holy!</p><p>Lord God almighty!</p><p>All thy works shall praise thy name, on earth,</p><p>and sky, and sea;</p><p>Holy, holy, holy!</p><p>merciful and mighty!</p><p>God in three persons, blessed Trinity.</p><p><br></p><p>VERSE 4</p><p>Holy, holy, holy!</p><p>though the darkness hide thee,</p><p>Though the eye of sinful man thy glory</p><p>may not see, Only thou art holy, there is none beside thee</p><p>Perfect in power, in love, and purity.</p><p><br></p>', '2026-06-08 13:49:48', '2026-06-08 13:49:48', 'Entrance'),
	(199, 'Ondu Menyi Alo', 'Pending', NULL, '<p>Ondu Menyi Alo (x2)</p><p>Menyi alo, menyi alo</p><p>Ondu menyi alo, menyi alo</p><p><br></p><p>Christi Menyi, Christi menyi alo,</p><p>Christi menyi alo,&nbsp;</p><p>Menyi alo, menyi alo</p><p><br></p><p>Ondu Menyi Alo (x2)</p><p>Menyi alo, menyi alo</p><p>Ondu menyi alo, menyi alo</p><p><br></p>', '2026-06-08 13:51:34', '2026-06-08 13:51:34', 'Kyrie'),
	(200, 'ARA E GBE E GA', 'Jude Nnam', NULL, '<p><br></p><p>Ogo ni f\'olorun loke orun</p><p>Alaafia sini laye fawon Eda oninu rere</p><p><br></p><p>&nbsp;</p><p><br></p><p>Babawa agbe oga afiyi a\'tola fun o ogoye f\'olurunwa</p><p><br></p><p>Ara e gbega ope ye f\'olorun iyi ye f\'olorun ogoye f\'olurunwa ogoye f\'olurunwa Amin</p><p><br></p><p>&nbsp;</p><p><br></p><p>Oluwa olorunwa odo agunta olorun&nbsp;iwoto nko ese ayelo saanu funnwa gbotiwa</p><p><br></p><p><br></p><p>Iwonikan lenimimo oluwa toga julo Jesu omo baba ninu isokan emimimo</p>', '2026-06-08 13:52:33', '2026-06-08 13:52:33', 'Gloria'),
	(201, 'Chi Obioma', 'Pending', NULL, '<p><br></p><p>&nbsp;</p><p>1. Chim merem obioma mgbem n’enweghi Olol’anya chim merem obi oma eh 2X.</p><p>&nbsp;</p><p>Chukwu bu so mma</p><p>chim merem obioma eh chim merem obi oma eh chim merem obi oma eh</p><p>Agada gbachiri uzo Dike</p><p>chim merme obi oma eh chim merem obi oma eh chim merem Obi oma eh</p><p>Okike kere uwa Eze chim merem obi oma eh chim merem Obi oma eh chim merem obi oma eh Omerem ihe oma eh</p><p>chim merem Obi oma eh Chim merem Obi oma eh chim merem Obi oma eh.</p><p>&nbsp;</p><p>2.&nbsp;Ekele dikwara dikwara gi n’ibu odogwu chim merem obi oma eh 2X.</p><p>&nbsp;</p><p>3. Otito dikwara dikwara gi n’ibu chukwu chim merem obi oma eh! 2X</p><p>&nbsp;</p><p>4. Chukwu idi ugwu olil’anya umu-uwa no Mgbere de Chim merem obioma Eh! 2X.</p><p><br></p>', '2026-06-08 13:53:32', '2026-06-08 13:53:32', 'Offertory'),
	(202, 'OJOCHENEMI/OJOCHEGBE', 'Jude Nnam', NULL, '<p><br></p><p>REFRAIN</p><p>&nbsp;</p><p>Ojochenemi o if God is for us who can be against us&nbsp;</p><p>Ojochegbe God has done great&nbsp;</p><p>I will shout for joy Praise His name my awesome God You have done great things</p><p>&nbsp;</p><p>Verse 1</p><p>&nbsp;</p><p>I trust in God wherever I may be upon the land or on the rolling sea for come what may&nbsp;</p><p>from day to day&nbsp;</p><p>Omnipotent God He cares for me</p><p>&nbsp;</p><p>Verse 2</p><p>&nbsp;</p><p>He makes the rose an object of His cares&nbsp;</p><p>He guides the eagle through the pathless air&nbsp;</p><p>and surely He remembers me Omnipotent God He cares for me</p><p>&nbsp;</p><p>Verse 3.</p><p>I trust in God for in the lion’s den on battle field or in the prison Pen through praise and blame&nbsp;</p><p>through flood and flame&nbsp;</p><p>Omnipotent God He cares for me</p><p>&nbsp;</p><p>Verse 4</p><p>The valley may be dark the shadows deep but still the Shepherd guards his lonely sheep and through the gloom He’ll lead me home Omnipotent God He cares for me</p>', '2026-06-08 13:54:29', '2026-06-08 13:54:29', 'Offertory'),
	(203, 'Mungode Allah', 'Pending', NULL, '<p><br></p><p>Intro</p><p><br></p><p>Mungode Allah</p><p><br></p><p>Mungode Allah</p><p><br></p><p>Mungode Allah</p><p><br></p><p>Mungode Allah</p><p><br></p><p>&nbsp;</p><p><br></p><p>&nbsp;</p><p><br></p><p>Chorus</p><p><br></p><p>Domin ka kawo mu awa nara nayo</p><p><br></p><p>Domin ka kawo mu awa nara nayo</p><p><br></p><p>Mungode Allah</p><p><br></p><p>Mungode Allah</p><p><br></p><p>Mungode Allah</p><p><br></p><p>Mungode Allah</p><p><br></p><p>Allah Sarki</p><p><br></p><p>Allah Sarki</p><p><br></p><p>Allah Sarki</p><p><br></p><p>&nbsp;</p><p><br></p><p>Verse 1</p><p><br></p><p>Da ye wa suke abubu wa nda ka ba mu</p><p><br></p><p>Da ye wa suke abubu wa nda ka ba mu</p><p><br></p><p>Mungode Allah</p><p><br></p><p>Mungode Allah</p><p><br></p><p>&nbsp;</p><p><br></p><p>Chorus</p><p><br></p><p>&nbsp;</p><p><br></p><p>Verse 2</p><p><br></p><p>Da ye wa suke jin dadi nda ka ba mu</p><p><br></p><p>Da ye wa suke jin dadi nda ka ba mu</p><p><br></p><p>Mungode Allah</p><p><br></p><p>Mungode Allah</p><p><br></p><p>&nbsp;</p><p><br></p><p>Chorus</p><p><br></p><p>&nbsp;</p><p><br></p><p>Verse 3</p><p><br></p><p>Da ye wa suke al barka nda mu kerbi</p><p><br></p><p>Da ye wa suke al barka nda mu kerbi</p><p><br></p><p>Mungode Allah</p><p><br></p><p>Mungode Allah</p><p><br></p><p>&nbsp;</p><p><br></p><p>Chorus</p><p><br></p><p>&nbsp;</p><p><br></p><p>Verse 4</p><p><br></p><p>Da kuma ruwansama nda ka ba mu</p><p><br></p><p>Da kuma ruwansama nda ka ba mu</p><p><br></p><p>Mungode Allah</p><p><br></p><p>Mungode Allah</p><p><br></p><p>&nbsp;</p><p><br></p><p>Chorus</p><p><br></p><p>&nbsp;</p><p><br></p><p>Verse 5</p><p><br></p><p>Da kuma hasken rana nda ka ba mu</p><p><br></p><p>Da kuma hasken rana nda ka ba mu</p><p><br></p><p>Mungode Allah</p><p><br></p><p>Mungode Allah</p><p><br></p><p>&nbsp;</p><p><br></p><p>Chorus</p><p><br></p><p>&nbsp;</p><p><br></p><p>Verse 6</p><p><br></p><p>Da kuma iska nda mu kerbi nda ka ba ma mu</p><p><br></p><p>Da kuma iska nda mu kerbi nda ka ba ma mu</p><p><br></p><p>Mungode Allah</p><p><br></p><p>Mungode Allah</p><p><br></p><p>&nbsp;</p><p><br></p>', '2026-06-08 13:55:16', '2026-06-08 13:55:16', 'Offertory'),
	(204, '‎It\'s payback time', 'Jude Nnam', NULL, '<p><br></p><p>I believe that Jesus died for me</p><p>A sacrifice beyond my understanding</p><p>Offering himself in place of me</p><p>Oh! How can I repay the Lord?</p><p><br></p><p>Father, to you we offer</p><p>Jesus, to you this gift we bring</p><p>Holy Ghost accept this offering</p><p>Which we offer unto to you</p><p><br></p><p>I believe all that the scripture say</p><p>About the Lord, beyond my understanding</p><p>Forgiveness beyond comprehension</p><p>Oh! How can I repay the Lord?</p><p><br></p><p>Father, to you we offer</p><p>Jesus, to you this gift we bring</p><p>Holy Ghost accept this offering</p><p>Which we offer unto to you&nbsp;</p><p>‎</p><p><br></p>', '2026-06-08 13:56:44', '2026-06-08 13:56:44', 'Consecration'),
	(205, 'Mimo L\'olodumare', 'Pending', NULL, '<p>&nbsp;Call: Mimo L\'olodumare Res: Mimo Mimo Mimo&nbsp;Mimo O L\'oluwa&nbsp;&nbsp;</p><p><br></p><p>Verse 1:&nbsp;</p><p>Orun Oun aye yin O l\'ogo o&nbsp;</p><p>Res: Mimo Mimo Mimo&nbsp;&nbsp;&nbsp;&nbsp;Mimo O L\'oluwa&nbsp;&nbsp;</p><p>Call: Hosanah loke Orun o&nbsp;</p><p>Res: Hosanah loke orun</p><p>&nbsp;o&nbsp;&nbsp;</p><p>&nbsp;Verse 2&nbsp;</p><p>Call: Ibukun ni f\'eni t\'onbo&nbsp;wa L\'oruko Oluwa o&nbsp;</p><p>Res: Mimo Mimo Mimo&nbsp;&nbsp;&nbsp;&nbsp;Mimo O L\'oluwa&nbsp;</p><p>Call: Hosanah loke Orun o Res: Hosanah loke orun o</p>', '2026-06-08 13:57:29', '2026-07-24 14:23:54', 'Sanctus'),
	(207, 'Jesus Loves Even Me', 'Pending', NULL, '<p><br></p><p>1 I am so glad that our Father in heaven</p><p>Tells of His love in the Book He has given;</p><p>Wonderful things in the Bible I see,</p><p>This is the dearest, that Jesus loves me.</p><p><br></p><p>Refrain:</p><p>I am so glad that Jesus loves me,</p><p>Jesus loves me, Jesus loves me;</p><p>I am so glad that Jesus loves me,</p><p>Jesus loves even me.</p><p><br></p><p>2 Though I forget Him and wander away,</p><p>Kindly He follows wherever I stray;</p><p>Back to His dear loving arms would I flee,</p><p>When I remember that Jesus loves me. [Refrain]</p><p><br></p><p>3 O, if there\'s only one song I can sing,</p><p>When in His beauty I see the great King,</p><p>This shall my song in eternity be:</p><p>O, what a wonder that Jesus loves me! [Refrain]</p><p><br></p>', '2026-06-08 13:58:52', '2026-06-08 13:58:52', 'Communion'),
	(208, '‎All hail adored trinity (tune Old Hundredth)', 'Pending', NULL, '<p><br></p><p>1 All hail, adored Trinity!</p><p>All hail, eternal Unity!</p><p>O God the Father, God the Son,</p><p>And God the Spirit, ever One.</p><p><br></p><p>2 Three persons praise we evermore,</p><p>One only God our hearts adore:</p><p>In thy sure mercy, ever kind,</p><p>May we your strong protection find.</p><p><br></p><p>3 O Trinity! O Unity!</p><p>Be present as we worship thee;</p><p>And with the songs that angels\' sing</p><p>Unite the hymns of praise we bring.</p><p><br></p>', '2026-06-08 13:59:24', '2026-06-08 13:59:24', 'Communion'),
	(209, 'EVERYDAY GOD', 'Bernadette Farrel', NULL, '<p><br></p><p>Earth\'s creator (everyday God)</p><p>Loving Maker (O Jesus)</p><p>You who shaped us (O Spirit)</p><p>Recreate us (come be with us)</p><p><br></p><p>In your presence (everyday God)</p><p>We are gathered (O Jesus)</p><p>You have called us (O Spirit)</p><p>To restore us (come be with us)</p><p><br></p><p>Life of all lives (everyday God)</p><p>Love of all loves (O Jesus)</p><p>Hope of all hopes (O Spirit)</p><p>Light of all lights (come be with us)</p><p><br></p><p>In our resting (everyday God)</p><p>In our rising (O Jesus)</p><p>In our hoping (O Spirit)</p><p>In our waiting (come be with us)</p><p><br></p><p>In our dreaming (everyday God)</p><p>In our daring (O Jesus)</p><p>In our searching (O Spirit)</p><p>In our sharing (come be with us)</p><p><br></p><p>God of laughter (everyday God)</p><p>God of sorrow (O Jesus)</p><p>Home and shelter (O Spirit)</p><p>Strong and patient (come be with us)</p><p><br></p><p>Way of freedom (everyday God)</p><p>Star of morning (O Jesus)</p><p>Timeless healer (O Spirit)</p><p>Flame eternal (come be with us)</p><p><br></p><p>Word of gladness (everyday God)</p><p>Word of mercy (O Jesus)</p><p>Word of friendship (O Spirit)</p><p>Word of challenge (come be with us)</p><p><br></p><p>Gentle father (everyday God)</p><p>Faithful brother (O Jesus)</p><p>Tender sister (O Spirit)</p><p>Loving mother (come be with us)</p><p><br></p><p>Our beginning (everyday God)</p><p>Our unfolding (O Jesus)</p><p>Our enduring (O Spirit)</p><p>Journey\'s ending (come be with us)</p><p><br></p><p>Alleluia (everyday God)</p><p>Now and always (O Jesus)</p><p>Alleluia (O Spirit)</p><p>Through all ages (come be with us)</p><p><br></p>', '2026-06-08 14:00:42', '2026-06-08 14:00:42', 'Communion'),
	(211, '‎Glory to the Trinity', 'Sam Ezugwu', NULL, '<p><br></p><p><br></p><p>VERSE 1</p><p>Sing praise to the living God, Glory Halleluia.</p><p>Come adore the living God, Glory Halleluia,</p><p>Though sun and moon may pass away,</p><p>&nbsp;&nbsp;&nbsp;His word will ever stay</p><p>His power is forevermore, Glory Halleluia.</p><p><br></p><p>CHORUS</p><p>Glory to the Trinity, the undivided unity.</p><p>The Father; Son and Spirit One,</p><p>From whom all life and goodness come.</p><p><br></p><p>VERSE 2</p><p>To the living God we sing, Glory, Halleluia,</p><p>Let our love and praises ring, Glory, Halleluia.</p><p>To His sons, He always</p><p>&nbsp;&nbsp;&nbsp;gives His mercy and His love.</p><p>Praise Him now forevermore, Glory, Halleluia.</p><p><br></p><p>VERSE 3</p><p>To the God who cannot die, Glory, Halleluia</p><p>To the living God we cry, Glory, Halleluia</p><p>He promised to be with us</p><p>&nbsp;&nbsp;&nbsp;and He lives in everyone</p><p>Love Him now forevermore, Glory, Halleluia.</p><p><br></p>', '2026-06-08 14:02:10', '2026-06-08 14:02:10', 'Communion'),
	(212, 'BE WITH US GOD', 'Pending', NULL, '<p>Chorus:</p><p>Be with us Father we need your blessings,</p><p>Be with us son, we need your presence,</p><p>Be with us spirit we need your power,</p><p>As we come to worship you Lord.</p><p><br></p><p>Verse 1:</p><p>Standing in your presence Father,</p><p>We\'re declaring our love for you.</p><p>Watching and waiting with face lifted high up,</p><p>As we long for your power from high,</p><p>We raise our voice in praise, in worship to you our God.</p><p><br></p><p><br></p><p>Verse 2:</p><p>King of kings, Lord of lords, mighty redeemer,</p><p>The creator of heaven and earth,</p><p>Lord we bring ourselves before you,</p><p>Take our hearts so filled with love,</p><p>We raise our voice in praise, in worship to you our God.</p><p><br></p><p><br></p><p>Verse 3:</p><p>Lord we raise our voice to you, with praises on our lips,</p><p>All creation bow before you.</p><p>Everyone shall call you Lord, you are the maker of all things living,</p><p>Come and rule over all our hearts.</p><p><br></p>', '2026-07-17 13:12:21', '2026-07-17 13:12:21', 'Entrance'),
	(214, 'ONYENWEANYI BIKO MEE EBERE', 'Pending', NULL, '<p>Onyenwanyi biko mee ebere doo</p><p>onyenwani mee ebere, mee ebere oh me ebere</p><p>onyenwanyi mee ebere</p><p><br></p><p>christi, christi, christi mee ebere</p><p><br></p><p>Onyenwanyi biko mee ebere doo</p><p>onyenwani mee ebere, mee ebere oh me ebere</p><p>onyenwanyi mee ebere</p><p><br></p>', '2026-07-17 13:16:51', '2026-07-17 13:16:51', 'Kyrie'),
	(215, 'OJIMA', 'Momoh St Gabriels', NULL, '<p>Ojima cheyi ojo kidatate</p><p>Ojima cheyi ojo kidatate</p><p>Ojima cheyi ojo kidatate 2x</p><p><br></p><p>Verse 1</p><p>Kpai edeko k’ichi’eyi</p><p>Amen okpakpa efilei</p><p>Awa kelewe, Awa duwawe</p><p>A d’ojima uwe, A ch’ugbe de we</p><p>Verse 2</p><p>Todu Ojima lile ewe,</p><p>A danyekwu gw’uwe</p><p>Ondu k’ich’ojo,onu eyi ojale</p><p>Ojo Ata odo bogagwu</p><p>Kpai Jesu Kristi,</p><p>Ondu wa omakate eyi Ata</p><p><br></p><p>Verse 3</p><p>Ondu k’ich’ojo, omala eyi ojo,</p><p>we kia k’ebienee, ilerinyo</p><p>Gb’aduwa ewa ondu wa</p><p><br></p><p>Verse 4</p><p>Uwe k’ewguwgu a woto e ojo,</p><p>chejumomi wa ondu wa</p><p>Todu k’uwe, kate ch’ina,</p><p>uwe kate ch’e ondu,</p><p>Uwe kate O Jesu Kristi</p><p><br></p><p>Verse 5</p><p>Uwe kpai, A f’ina dama</p><p>Ef’Ojima, eyi ojo ata</p><p>Amin Amin Amin</p><p><br></p>', '2026-07-17 13:17:34', '2026-07-17 13:17:34', 'Gloria'),
	(216, 'Earthly gifts', 'Pending', NULL, '<p>Earthly gifts we offer you O God.</p><p>Receive us, O God,</p><p>And bless us, shower your blessings upon us.</p><p>Receive us, O God,</p><p>and bless us, shower your blessings upon us.</p><p><br></p><p>1&nbsp;Our hearts we give you, full of thanks</p><p>come come come, come and bless your people,</p><p>Receive our hearts, we bring to you.</p><p>Come come come, come and bless your people.</p><p><br></p><p>2.&nbsp;We give You, gifts, bread and wine,</p><p>come come, come and bless your people,</p><p>Receive our gifts, we bring to you.</p><p>come come, come and bless your people,</p><p>3. We give You gifts from our hearts, come</p><p>come come come, come and bless your people,</p><p>Receive our gifts, we give to you.</p><p>come come come, come and bless your people,</p><p><br></p><p>4.We give You praise, praise and thanks,</p><p>come come come, come and bless your people,</p><p>Receive our praise, we give to you.</p><p>come come come, come and bless your people</p><p><br></p>', '2026-07-17 13:18:41', '2026-07-17 13:18:41', 'Consecration'),
	(217, 'LIKE INCENSE', 'Pending', NULL, '<p><br></p><p>Verse 1</p><p><br></p><p>Like incense rises up to you&nbsp;&nbsp;</p><p>Let our offering&nbsp;&nbsp;</p><p><br></p><p><br></p><p>Rise up to you oh&nbsp;&nbsp;</p><p>Let your blessings fall on us&nbsp;&nbsp;</p><p>Like morning dew&nbsp;&nbsp;</p><p>Morning dew</p><p><br></p><p>Chorus&nbsp;&nbsp;</p><p><br></p><p>My God my Lord bless me&nbsp;&nbsp;</p><p>My Lord bless me&nbsp;&nbsp;</p><p>My Lord bless me</p><p><br></p><p>2.a</p><p><br></p><p>My God my Lord, answer me.&nbsp;&nbsp;</p><p>My Lord answer me, my Lord answer me</p><p><br></p><p>2.b</p><p><br></p><p>I will praise you my Lord&nbsp;&nbsp;</p><p>I will praise you with all my heart.</p><p><br></p><p>3.a</p><p><br></p><p>My God my Lord heal me.&nbsp;&nbsp;</p><p>My Lord heal me, my Lord heal me</p><p><br></p><p><br></p><p>3.b</p><p><br></p><p>I will bless you my Lord,&nbsp;&nbsp;</p><p>I will bless you with all my heart</p><p><br></p>', '2026-07-17 13:21:38', '2026-07-17 13:21:38', 'Consecration'),
	(218, 'Holy Holy Holy(mass of saint Jude)', 'Jude Nnam', NULL, '<p>Holy Is the Lord</p><p>Holy Is the Lord</p><p>Holy Is the Lord</p><p><br></p><p>Heaven and earth O Lord (Heaven and Earth)</p><p>Are full of your Great Glory, Hossana</p><p><br></p><p>Hosa, Hossana</p><p>Hosa, Hossana</p><p>Hosa Hossana, in the highest</p><p>Hosa, Hossana</p><p>Hosa, Hossana</p><p>Hosa Hossana, Heaven and earth are full of your glory</p><p>Hosa, Hossana</p><p>Hosa, Hossana</p><p>Hosa Hossana, in the highest</p><p><br></p><p>Blessed is He who comes</p><p>He who comes</p><p>In the name of the Lord (Of the Lord)</p><p>Blessed is He who comes</p><p>He who comes</p><p>In the name of the Lord,</p><p><br></p><p>&nbsp;Hossana</p><p>Holy Is the Lord</p><p>Holy Is the Lord</p><p>Holy Is the Lord</p><p>Heaven and earth O Lord (Heaven and Earth)</p><p>Are full of your Great Glory, Hossana</p><p><br></p>', '2026-07-17 13:23:02', '2026-07-17 13:23:02', 'Sanctus'),
	(219, 'WAYONGU', 'Pending', NULL, '<p>Wan yongu u aondo</p><p>We uter asorabo aataregh kera, zungwe see mho onum ( 2x)&nbsp;</p><p><br></p><p>Wan yongu u aondo We uter asorabo ataregh kera, na se na se beem</p><p><br></p>', '2026-07-17 13:24:12', '2026-07-17 13:24:12', 'Agnus Dei'),
	(220, 'ONYEKACHUKWU', 'Pending', NULL, '<p><br></p><p>Chineke mo onyeoma mmadu chukeu</p><p>Iyokoko o kwa gi ji ndu o&nbsp;</p><p>Onye g’aso mo ka chineke si aso m n’obi</p><p>Chukwu oma so gi ka m ji aba odogwu</p><p><br></p><p>CHORUS&nbsp;</p><p>Onye ka chukwu, onye di ka chukwu ike nke m kwu aba</p><p>Lee lee lee, lee lee lee na Chineke</p><p>Na chi eze na ndu mo</p><p><br></p><p>1.Un’ahugo iheoma chukwu n’eme n’obim</p><p>Onye ka Chukwu ajuju ka m na aju nuo</p><p>Chimu n’edumo chimarobi mo</p><p>Olisa mo okwa gi ka m choro bia</p><p><br></p><p>2.O bu onye nyiri Jesu onye&nbsp;</p><p>onye ga asoomo ka chukwu si aso&nbsp;</p><p>onyiri gi o onyiri gi o onyiri gi o&nbsp;</p><p>Onyiri chukwu adighi mancha</p><p><br></p><p>3.Ngwa leezinu iheoma chukwu&nbsp;n’emere now’gbenye</p><p>Gini ka gi onwe gi noo n’etiiyo koko</p><p>O bu gini ka gi onwe gi n’eche</p><p>Chukwu olisa doo</p><p>Okwa gi ka m choro bia o ye</p><p><br></p><p>Unu ahugoa ahuhu nkea anago nuo&nbsp;</p><p>Chineke anwugor’anyi onwu ihunanya n’elu obe</p><p>O bu onye g’anwunuo ka chinekesiri nwuo</p><p>Chima mkpa mo chimar’obi mo</p><p><br></p><p>Onye ka chukwu, onye di ka chukwu ike nke m kwu aba</p><p>Lee lee lee, lee lee lee na Chineke</p><p>Na chi eze na ndu mo</p><p><br></p><p>Onye di ka chukwu</p><p><br></p>', '2026-07-17 13:25:35', '2026-07-17 13:25:35', 'Communion'),
	(221, 'ALL THE EARTH (PSALM 100)', 'pending', NULL, '<p><strong>Chorus:</strong><br>All the earth proclaim the Lord,<br>Sing your praise to God.</p>\n<p><strong>1.</strong><br>Serve you the Lord, heart filled with gladness,<br>Come into His Presence singing for joy!</p>\n<p><strong>2.</strong><br>Know that the Lord is our Creator.<br>Yes, He is our Father; we are His sons.</p>\n<p><strong>3.</strong><br>We are the sheep of His green pasture,<br>For we are His people; He is our God.</p>\n<p><strong>4.</strong><br>Enter His gates bringing thanksgiving,<br>O enter His courts while singing His praise.</p>\n<p><strong>5.</strong><br>Our Lord is good, His love enduring,<br>His word is abiding now with all people.</p>\n<p><strong>6.</strong><br>Honour and praise be to the Father,<br>The Son, and the Spirit, world without end.</p>', '2026-07-24 13:38:18', '2026-07-24 13:38:18', 'processional'),
	(222, 'ALL CREATURES OF OUR GOD AND KING', 'pending', NULL, '<p><strong>1.</strong><br>All creatures of our God and King,<br>Lift up your voice and with us sing,<br>Alleluia! Alleluia!<br>Thou burning sun with golden beam,<br>Thou silver moon with softer gleam,<br>Alleluia! Alleluia!</p>\n<p><strong>Chorus:</strong><br>Alleluia! Oh, praise Him! Alleluia!</p>\n<p><strong>2.</strong><br>Thou rushing wind that art so strong,<br>Ye clouds that sail in heav’n along,<br>Alleluia! Alleluia!<br>Thou rising morn, in praise rejoice;<br>Ye light of evening, find a voice,<br>Alleluia! Alleluia!</p>\n<p><strong>3.</strong><br>Thou flowing water, pure and clear,<br>Make music for thy Lord to hear,<br>Alleluia! Alleluia!<br>Thou fire so masterful and bright,<br>That gives to man both warmth and light,<br>Alleluia! Alleluia!</p>\n<p><strong>4.</strong><br>Dear Mother Earth, who day by day<br>Unfoldest blessings on our way,<br>Alleluia! Alleluia!<br>The flow’rs and fruits that in thee grow,<br>Let them his glory also show,<br>Alleluia! Alleluia!</p>', '2026-07-24 13:38:18', '2026-07-24 13:38:18', 'entrance'),
	(223, 'O LORD HAVE MERCY', 'pending', NULL, '<p>O Lord have mercy<br>O Lord have mercy<br>O Christ have mercy<br>O Christ have mercy<br>O Lord have mercy<br>O Lord have mercy</p>', '2026-07-24 13:38:18', '2026-07-24 13:38:18', 'kyrie'),
	(224, 'GLORY TO GOD ON HIGH', 'pending', NULL, '<p>Glory to God on high<br>Glory to God<br>Glory to God on high<br>Glory to God in the highest<br>And peace to his people on earth<br>We praise you, We bless you,<br>We adore you,<br>We glorify your name<br>We give you thanks O Lord<br>for your great glory<br>Lord God Almighty Father<br>Lord Jesus Christ<br>Only begotten son<br>Lord God Lamb of God<br>son of the father.<br>you take away the sin<br>Of the world<br>Have mercy on us<br>son of the father.<br>you take away the sin<br>The sins of the world<br>Have mercy receive our prayer Lord<br>You are Seated at the right hand<br>Right hand of the father<br>Have mercy on us Lord<br>Have Mercy, have Mercy on us<br>For you alone are the holy one<br>You alone are the Lord<br>You alone are most high<br>Jesus Christ With the Holy Spirit<br>In the Glory of God the father.<br>Alleleuia, Amen</p>', '2026-07-24 13:38:18', '2026-07-24 13:38:18', 'gloria'),
	(225, 'ALLELUIA', 'pending', NULL, '<p>Alleluia Alleuia</p>', '2026-07-24 13:38:18', '2026-07-24 13:38:18', 'alleluia'),
	(226, 'I BELIEVE', 'pending', NULL, '<p><strong>Chorus:</strong><br>Do you believe<br>I believe in God the father, yes<br>I believe in God the son<br>I believe in God the holy spirit,<br>Three in one God</p>\n<p><strong>1.</strong><br>The Almighty father,<br>creator of heaven and earth,<br>And in Jesus Christ his only son our lord,<br>Who was conceded by the holy spirit.</p>\n<p><strong>2.</strong><br>Of the virgin Mary born,<br>suffered under Pontius Pilate,<br>He was crucified,<br>he suffered death, and was buried,</p>\n<p><strong>3.</strong><br>He descended into hell,<br>he rose up on the third day,<br>he ascended into heaven,<br>seated at the right hand of the father</p>\n<p><strong>4.</strong><br>He will come again,<br>he will come in glory to judge<br>the living and the dead,<br>as the scripture has for told</p>\n<p><strong>5.</strong><br>I believe in the holy spirit,<br>the holy Catholic church,<br>the communion of saints,<br>the forgiveness of sins</p>\n<p><strong>6.</strong><br>The resurrection,<br>resurrection of the body,<br>and life everlasting.<br>Amen. Amen.</p>', '2026-07-24 13:38:18', '2026-07-24 13:38:18', 'creed'),
	(227, 'HEAR OUR HUMBLE PRAYER', 'pending', NULL, '<p>Hear our humble prayer mercy on your people Lord<br>He has heard my prayer I am rejoicing, I am relieved, my God is good, I will praise him</p>', '2026-07-24 13:38:19', '2026-07-24 13:38:19', 'prayer_of_the_faithful'),
	(228, 'OCEAN OF MERCY', 'pending', NULL, '<p><strong>Chorus:</strong><br>Ocean of mercy<br>receive our gifts; receive us Oh Lord (receive),<br>Receive our earthly gifts<br>from the hands of Your priests<br>like the sacrifice of Abel</p>\n<p><strong>1.</strong><br>The gifts we give you, Oh my Lord.<br>Receive our gifts; receive us Oh Lord<br>Receive us, receive us, receive us my Lord.<br>Receive our gifts, receive us Oh Lord!</p>\n<p><strong>2.</strong><br>The bread we lift up to you, my Lord.<br>Receive our gifts; receive us Oh Lord<br>Bless us, bless us, bless us my Lord.<br>Receive our gifts, receive us Oh Lord!</p>\n<p><strong>3.</strong><br>The wine in chalice, take my Lord.<br>Receive our gifts; receive us Oh Lord<br>Protect us, protect us, protect us my Lord.<br>Receive our gifts, receive us Oh Lord!</p>\n<p><strong>4.</strong><br>Our hearts we give you, Oh my Lord.<br>Receive our gifts; receive us Oh Lord<br>Receive us, receive us, receive us my Lord.<br>Receive our gifts, receive us Oh Lord!</p>', '2026-07-24 13:38:19', '2026-07-24 13:38:19', 'offertory'),
	(229, 'HOLY HOLY (SANTUS)', 'pending', NULL, '<p>Holy holy holy<br>Lord God of host,<br>Heaven and earth<br>are full of your glory.<br>Hossana<br>In the highest,<br>Hossana in the highest.<br>Hossana Holy Holy Holy<br>Blessed is he<br>who comes in the name<br>The name of the lord.<br>Hossana<br>In the highest,<br>Hossana in the highest.<br>Hossana Holy Holy Holy</p>', '2026-07-24 13:38:19', '2026-07-24 13:38:19', 'sanctus'),
	(230, 'O LAMB OF GOD (AGNUS DEI)', 'pending', NULL, '<p>O lamb of God you take away the sins of the world,<br>O lamb of God you take away the sins of the world.<br>Have mercy, have mercy, have mercy on us<br>Have mercy, have mercy, have mercy on us<br>O lamb of God you take away the sins of the world,<br>O lamb of God you take away the sins of the world.<br>Have mercy, have mercy, have mercy on us<br>Have mercy, have mercy, have mercy on us<br>O lamb of God you take away the sins of the world,<br>O lamb of God you take away the sins of the world.<br>Grant us, grant us, grant us peace<br>Grant us, grant us, grant us peace.</p>', '2026-07-24 13:38:19', '2026-07-24 13:38:19', 'agnus_dei'),
	(231, 'THE LORD\'S MY SHEPHERD', 'pending', NULL, '<p><strong>1.</strong><br>The Lord\'s my Shepherd, I’ll not want,<br>He makes me down to lie<br>In pastures green; he leadeth me<br>the quiet waters by.</p>\n<p><strong>2.</strong><br>My soul he doth restore again<br>And me to walk doth make<br>Within the paths of righteousness<br>E\'en for his own name sake.</p>\n<p><strong>3.</strong><br>Yea, though I walk through death\'s dark vale,<br>Yet will I fear no ill;<br>For thou art with me, and thy rod<br>And staff me comfort still.</p>\n<p><strong>4.</strong><br>My table thou hast furnished<br>In the presence of my foes:<br>My head thou dost with oil anoint<br>And my cup overflows.</p>\n<p><strong>5.</strong><br>Goodness and mercy all my life<br>Shall surely follow me;<br>And in God\'s house for evermore<br>My dwelling place shall be.</p>', '2026-07-24 13:38:19', '2026-07-24 13:38:19', 'communion'),
	(235, 'ALL THE EARTH (PSALM 100)', 'pending', NULL, '<p><strong>Chorus:</strong><br>All the earth proclaim the Lord,<br>Sing your praise to God.</p>\n<p><strong>1.</strong><br>Serve you the Lord, heart filled with gladness,<br>Come into His Presence singing for joy!</p>\n<p><strong>2.</strong><br>Know that the Lord is our Creator.<br>Yes, He is our Father; we are His sons.</p>\n<p><strong>3.</strong><br>We are the sheep of His green pasture,<br>For we are His people; He is our God.</p>\n<p><strong>4.</strong><br>Enter His gates bringing thanksgiving,<br>O enter His courts while singing His praise.</p>\n<p><strong>5.</strong><br>Our Lord is good, His love enduring,<br>His word is abiding now with all people.</p>\n<p><strong>6.</strong><br>Honour and praise be to the Father,<br>The Son, and the Spirit, world without end.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'processional'),
	(236, 'ALL CREATURES OF OUR GOD AND KING', 'pending', NULL, '<p><strong>1.</strong><br>All creatures of our God and King,<br>Lift up your voice and with us sing,<br>Alleluia! Alleluia!<br>Thou burning sun with golden beam,<br>Thou silver moon with softer gleam,<br>Alleluia! Alleluia!</p>\n<p><strong>Chorus:</strong><br>Alleluia! Oh, praise Him! Alleluia!</p>\n<p><strong>2.</strong><br>Thou rushing wind that art so strong,<br>Ye clouds that sail in heav’n along,<br>Alleluia! Alleluia!<br>Thou rising morn, in praise rejoice;<br>Ye light of evening, find a voice,<br>Alleluia! Alleluia!</p>\n<p><strong>3.</strong><br>Thou flowing water, pure and clear,<br>Make music for thy Lord to hear,<br>Alleluia! Alleluia!<br>Thou fire so masterful and bright,<br>That gives to man both warmth and light,<br>Alleluia! Alleluia!</p>\n<p><strong>4.</strong><br>Dear Mother Earth, who day by day<br>Unfoldest blessings on our way,<br>Alleluia! Alleluia!<br>The flow’rs and fruits that in thee grow,<br>Let them his glory also show,<br>Alleluia! Alleluia!</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(237, 'O LORD HAVE MERCY', 'pending', NULL, '<p>O Lord have mercy<br>O Lord have mercy<br>O Christ have mercy<br>O Christ have mercy<br>O Lord have mercy<br>O Lord have mercy</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'kyrie'),
	(238, 'GLORY TO GOD ON HIGH', 'pending', NULL, '<p>Glory to God on high<br>Glory to God<br>Glory to God on high<br>Glory to God in the highest<br>And peace to his people on earth<br>We praise you, We bless you,<br>We adore you,<br>We glorify your name<br>We give you thanks O Lord<br>for your great glory<br>Lord God Almighty Father<br>Lord Jesus Christ<br>Only begotten son<br>Lord God Lamb of God<br>son of the father.<br>you take away the sin<br>Of the world<br>Have mercy on us<br>son of the father.<br>you take away the sin<br>The sins of the world<br>Have mercy receive our prayer Lord<br>You are Seated at the right hand<br>Right hand of the father<br>Have mercy on us Lord<br>Have Mercy, have Mercy on us<br>For you alone are the holy one<br>You alone are the Lord<br>You alone are most high<br>Jesus Christ With the Holy Spirit<br>In the Glory of God the father.<br>Alleleuia, Amen</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'gloria'),
	(239, 'ALLELUIA', 'pending', NULL, '<p>Alleluia Alleuia</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'alleluia'),
	(240, 'I BELIEVE', 'pending', NULL, '<p><strong>Chorus:</strong><br>Do you believe<br>I believe in God the father, yes<br>I believe in God the son<br>I believe in God the holy spirit,<br>Three in one God</p>\n<p><strong>1.</strong><br>The Almighty father,<br>creator of heaven and earth,<br>And in Jesus Christ his only son our lord,<br>Who was conceded by the holy spirit.</p>\n<p><strong>2.</strong><br>Of the virgin Mary born,<br>suffered under Pontius Pilate,<br>He was crucified,<br>he suffered death, and was buried,</p>\n<p><strong>3.</strong><br>He descended into hell,<br>he rose up on the third day,<br>he ascended into heaven,<br>seated at the right hand of the father</p>\n<p><strong>4.</strong><br>He will come again,<br>he will come in glory to judge<br>the living and the dead,<br>as the scripture has for told</p>\n<p><strong>5.</strong><br>I believe in the holy spirit,<br>the holy Catholic church,<br>the communion of saints,<br>the forgiveness of sins</p>\n<p><strong>6.</strong><br>The resurrection,<br>resurrection of the body,<br>and life everlasting.<br>Amen. Amen.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'creed'),
	(241, 'HEAR OUR HUMBLE PRAYER', 'pending', NULL, '<p>Hear our humble prayer mercy on your people Lord<br>He has heard my prayer I am rejoicing, I am relieved, my God is good, I will praise him</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'prayer_of_the_faithful'),
	(242, 'OCEAN OF MERCY', 'pending', NULL, '<p><strong>Chorus:</strong><br>Ocean of mercy<br>receive our gifts; receive us Oh Lord (receive),<br>Receive our earthly gifts<br>from the hands of Your priests<br>like the sacrifice of Abel</p>\n<p><strong>1.</strong><br>The gifts we give you, Oh my Lord.<br>Receive our gifts; receive us Oh Lord<br>Receive us, receive us, receive us my Lord.<br>Receive our gifts, receive us Oh Lord!</p>\n<p><strong>2.</strong><br>The bread we lift up to you, my Lord.<br>Receive our gifts; receive us Oh Lord<br>Bless us, bless us, bless us my Lord.<br>Receive our gifts, receive us Oh Lord!</p>\n<p><strong>3.</strong><br>The wine in chalice, take my Lord.<br>Receive our gifts; receive us Oh Lord<br>Protect us, protect us, protect us my Lord.<br>Receive our gifts, receive us Oh Lord!</p>\n<p><strong>4.</strong><br>Our hearts we give you, Oh my Lord.<br>Receive our gifts; receive us Oh Lord<br>Receive us, receive us, receive us my Lord.<br>Receive our gifts, receive us Oh Lord!</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(243, 'HOLY HOLY (SANTUS)', 'pending', NULL, '<p>Holy holy holy<br>Lord God of host,<br>Heaven and earth<br>are full of your glory.<br>Hossana<br>In the highest,<br>Hossana in the highest.<br>Hossana Holy Holy Holy<br>Blessed is he<br>who comes in the name<br>The name of the lord.<br>Hossana<br>In the highest,<br>Hossana in the highest.<br>Hossana Holy Holy Holy</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'sanctus'),
	(244, 'O LAMB OF GOD (AGNUS DEI)', 'pending', NULL, '<p>O lamb of God you take away the sins of the world,<br>O lamb of God you take away the sins of the world.<br>Have mercy, have mercy, have mercy on us<br>Have mercy, have mercy, have mercy on us<br>O lamb of God you take away the sins of the world,<br>O lamb of God you take away the sins of the world.<br>Have mercy, have mercy, have mercy on us<br>Have mercy, have mercy, have mercy on us<br>O lamb of God you take away the sins of the world,<br>O lamb of God you take away the sins of the world.<br>Grant us, grant us, grant us peace<br>Grant us, grant us, grant us peace.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'agnus_dei'),
	(245, 'THE LORD\'S MY SHEPHERD', 'pending', NULL, '<p><strong>1.</strong><br>The Lord\'s my Shepherd, I’ll not want,<br>He makes me down to lie<br>In pastures green; he leadeth me<br>the quiet waters by.</p>\n<p><strong>2.</strong><br>My soul he doth restore again<br>And me to walk doth make<br>Within the paths of righteousness<br>E\'en for his own name sake.</p>\n<p><strong>3.</strong><br>Yea, though I walk through death\'s dark vale,<br>Yet will I fear no ill;<br>For thou art with me, and thy rod<br>And staff me comfort still.</p>\n<p><strong>4.</strong><br>My table thou hast furnished<br>In the presence of my foes:<br>My head thou dost with oil anoint<br>And my cup overflows.</p>\n<p><strong>5.</strong><br>Goodness and mercy all my life<br>Shall surely follow me;<br>And in God\'s house for evermore<br>My dwelling place shall be.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(246, 'I WILL FOLLOW JESUS', 'pending', NULL, '<p><strong>1.</strong><br>Sweet are the promises,<br>Kind is the word,<br>Dearer far than any message man ever heard;<br>Pure was the mind of Christ,<br>Sinless I see;<br>He the great example is, and pattern for me.</p>\n<p><strong>Chorus:</strong><br>Where He leads I’ll follow,<br>all the way.<br>Where He leads I’ll follow,<br>Follow Jesus ev’ry day.</p>\n<p><strong>2.</strong><br>Sweet is the tender love<br>Jesus hath shown,<br>Sweeter far than any love that mortals have known;<br>Kind to the erring one,<br>Faithful is He;<br>He the great example is, and pattern for me.</p>\n<p><strong>3.</strong><br>List\' to His loving words,<br>“Come unto Me;”<br>Weary, heavy-laden, there is sweet rest for thee;<br>Trust in His promises,<br>Faithful and sure;<br>Lean upon the Savior, and thy soul is secure.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(247, 'KEEP IN MIND (211)', 'pending', NULL, '<p><strong>Chorus:</strong><br>Keep in mind that Jesus Christ<br>has died for us and is risen from the dead.<br>He is our saving Lord,<br>He is Joy for all ages.</p>\n<p><strong>1.</strong><br>If we die with the Lord,<br>We shall live with the Lord.</p>\n<p><strong>2.</strong><br>If we endure with the Lord,<br>We shall reign with the Lord.</p>\n<p><strong>3.</strong><br>In him all our sorrow,<br>In him all our joy.</p>\n<p><strong>4.</strong><br>In him hope of glory,<br>In him all our Love.</p>\n<p><strong>5.</strong><br>In him our redemption,<br>In him all our grace.</p>\n<p><strong>6.</strong><br>In him our Salvation,<br>In him all our peace.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(248, 'BRING THEM IN (CHB 48)', 'pending', NULL, '<p><strong>1.</strong><br>Hark! ’tis the shepherd\'s voice I hear,<br>Out in the desert dark and dreary,<br>Calling the sheep who\'ve gone astray,<br>Far from the shepherd\'s fold away.</p>\n<p><strong>Chorus:</strong><br>Bring them in, bring them in,<br>Bring them in from the fields of sin.<br>Bring them in, bring them in,<br>Bring the wandering ones to Jesus.</p>\n<p><strong>2.</strong><br>Who\'ll go and help this shepherd kind,<br>Help Him the wandering ones to find?<br>Who\'ll bring the lost ones to the fold<br>Where they\'ll be sheltered from the cold?</p>\n<p><strong>3.</strong><br>Out in the desert hear their cry,<br>Out on the mountains wild and high.<br>Hark! ’tis the Master speaks to thee,<br>“Go find my sheep where-e\'er they be.”</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(249, 'MY STORY', 'pending', NULL, '<p><strong>1.</strong><br>When I remember what you\'ve done for me,<br>My heart leaps for joy for there\'s none like you,<br>When I remember that you died for me,<br>My heart leaps for joy for there\'s none like you<br>And so.</p>\n<p><strong>Chorus:</strong><br>I will give you all I have,<br>Receive<br>God my offering to you,<br>Which I offer with my friends today...<br>Transform them and transform us<br>Purify them and purify us,<br>In this sacrifice divine<br>Always Lord, you know that<br>I have given all I have.</p>\n<p><strong>2.</strong><br>There was a time in life when I thought all was<br>Lost, Lord I am a living testimony of your love<br>You changed my story of woes to joy,<br>Lord I am a living testimony of your Love<br>And so</p>\n<p><strong>3.</strong><br>Many cannot see, many cannot hear,<br>I am blessed with these glory be to God,<br>Many have no food many have no home I<br>Am blessed with these glory be to God<br>And so...</p>\n<p><strong>4.</strong><br>I will tell this story to my neighbors,<br>I will tell this story to all my friends,<br>I will sing for you, I will praise your name,<br>I will dance for you for there\'s none like you<br>And so.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(250, 'MY SOUL NOW GLORIFIES (MAGNIFICAT)', 'pending', NULL, '<p><strong>1.</strong><br>My soul now glorifies,<br>The Lord who is my Saviour,<br>Rejoice for who am I,<br>The God has shown me favour.</p>\n<p><strong>2.</strong><br>The world shall call me blessed<br>And ponder on my story,<br>In me is manifest<br>God\'s greatness and His glory.</p>\n<p><strong>3.</strong><br>For those who are is his friends<br>And keep His laws most holy,<br>His mercy is never ends,<br>And He exalts the lowly.</p>\n<p><strong>4.</strong><br>But by His power the great<br>The proud, the self-conceited,<br>The kings who sit in state,<br>Are humbled and defeated</p>\n<p><strong>5.</strong><br>He feeds the starving poor,<br>He guides His holy nation,<br>Fulfilling what He swore,<br>Long since in revelation.</p>\n<p><strong>6.</strong><br>Then glorify with me,<br>The Lord who is my Saviour<br>One Holy Trinity<br>Forever and forever.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(251, 'PRAISE MY SOUL THE KING OF HEAVEN', 'pending', NULL, '<p><strong>1.</strong><br>Praise, my soul, the King of Heaven;<br>To His feet thy tribute bring;<br>Ransomed, healed, restored, forgiven,<br>Evermore His praises sing:<br>Praise Him, praise Him, praise him, Praise him,<br>Praise the everlasting King.</p>\n<p><strong>2.</strong><br>Praise Him for His grace and favor<br>To our fathers in distress;<br>Praise Him still the same as ever,<br>Slow to chide, and swift to bless.<br>Praise Him, praise Him, Praise him, Praise him,<br>Glorious in His faithfulness.</p>\n<p><strong>3.</strong><br>Fatherlike He tends and spares us,<br>Well our feeble frame He knows;<br>In His hands He gently bears us,<br>Rescues us from all our foes.<br>Praise Him, praise Him, Praise him, Praise him,<br>Widely yet His mercy flows.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(252, 'BE WITH US LORD', 'pending', NULL, '<p><strong>Chorus:</strong><br>Be with us Father we need your blessings,<br>Be with us son, we need your presence,<br>Be with us spirit we need your power,<br>As we come to worship you Lord.</p>\n<p><strong>1.</strong><br>Standing in your presence Father,<br>We\'re declaring our love for you.<br>Watching and waiting with face lifted high up,<br>As we long for your power from high,<br>We raise our voice in praise, in worship to you our God.</p>\n<p><strong>2.</strong><br>King of kings, Lord of lords, mighty redeemer,<br>The creator of heaven and earth,<br>Lord we bring ourselves before you,<br>Take our hearts so filled with love,<br>We raise our voice in praise, in worship to you our God.</p>\n<p><strong>3.</strong><br>Lord we raise our voice to you, with praises on our lips,<br>All creation bow before you.<br>Everyone shall call you Lord, you are the maker of all things living,<br>Come and rule over all our hearts.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(253, 'GLÓRIA IN EXCÉLSIS DEO', 'pending', NULL, '<p><strong>Chorus:</strong><br>Gloria in excel-sis,<br>Gloria in excelsis De-o,<br>Gloria in excel-sis,<br>Gloria in excelsis De-o.</p>\n<p><strong>1.</strong><br>Et in terra pax homínibus<br>bonae voluntátis<br>Laudámus te, benedícimus te,<br>adorámus te, glorificámus te,<br>grátias ágimus tibi propter magnam glóriam tuam,</p>\n<p><strong>2.</strong><br>Dómine Deus,<br>Rex cæléstis,Deus Pater<br>omnípotens.<br>Dómine Fili Unigénite, Jesu Christe,<br>Dómine Deus,</p>\n<p><strong>3.</strong><br>Agnus Dei, Fílius Patris,<br>Qui tollis peccáta mundi, miserére nobis;<br>Qui tollis peccáta mundi, súscipe de-precati-ónem nostram.</p>\n<p><strong>4.</strong><br>Qui sedes ad déxteram Patris,<br>miserére nobis.<br>Quóniam tu solus Sanctus,<br>tu solus Dóminus,<br>tu solus Altíssimus,<br>Jesu Christe,<br>cum Sancto Spíritu,<br>in glória Dei Patris. Amen</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'gloria'),
	(254, 'CREDO (LATIN)', 'pending', NULL, '<p>Credo in unum Deum,<br>Patrem omnipotentem, factorem caeli et terrae,<br>visibilium omnium et invisibilium.</p>\n<p>Et in unum Dominum Iesum Christum,<br>Filium Dei unigenitum,<br>et ex Patre natum ante omnia saecula.</p>\n<p>Deum de Deo, lumen de lumine,<br>Deum verum de Deo vero,<br>genitum, non factum, consubstantialem Patri:<br>per quem omnia facta sunt.</p>\n<p>Qui propter nos homines<br>et propter nostram salutem<br>descendit de caelis.</p>\n<p>Et incarnatus est de Spiritu Sancto<br>ex Maria Virgine, et homo factus est.</p>\n<p>Crucifixus etiam pro nobis sub Pontio Pilato;<br>passus et sepultus est,<br>et resurrexit tertia die, secundum Scripturas,<br>et ascendit in caelum, sedet ad dexteram Patris.</p>\n<p>Et iterum venturus est cum gloria,<br>iudicare vivos et mortuos,<br>cuius regni non erit finis.</p>\n<p>Et in Spiritum Sanctum, Dominum et vivificantem:<br>qui ex Patre Filioque procedit.</p>\n<p>Qui cum Patre et Filio simul adoratur<br>et conglorificatur:<br>qui locutus est per prophetas.</p>\n<p>Et unam, sanctam,<br>catholicam et apostolicam Ecclesiam.<br>Confiteor unum baptisma in remissionem, peccatorum.<br>Et exspecto resurrectionem mortuorum,<br>et vitam venturi saeculi. Amen.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'creed'),
	(255, 'GOD IS LOVE', 'pending', NULL, '<p><strong>Chorus:</strong><br>God is love,<br>And he who abides in love abides in God,<br>And God in him.</p>\n<p><strong>1.</strong><br>The love of Christ has gathered us together<br>Let us rejoice in him and be glad.</p>\n<p><strong>2.</strong><br>Be this shall all know that we are his disciples<br>If we have love, one for another.</p>\n<p><strong>3.</strong><br>Owe no man anything except to love one another<br>For he who loves his neighbour will fulfil the whole law.</p>\n<p><strong>4.</strong><br>O carry one another\'s burdens<br>And so you will fulfil the law of Christ.</p>\n<p><strong>5.</strong><br>The cup of blessing which we bless<br>Is it not fellowship in the blood of Christ?</p>\n<p><strong>6.</strong><br>The bread which we break,<br>Is it not fellowship in the body of Christ?</p>\n<p><strong>7.</strong><br>We many are one bread, one body,<br>For we all partake of the one bread.</p>\n<p><strong>8.</strong><br>This is the bread that came down from heaven,<br>He who eats this bread live forever.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(256, 'MY FAITH HAS FOUND A RESTING PLACE (I NEED NO OTHER ARGUMENT)', 'pending', NULL, '<p><strong>1.</strong><br>My faith has found a resting place,<br>Not in device nor creed;<br>I trust the Ever-living One,<br>His wounds for me shall plead.</p>\n<p><strong>Chorus:</strong><br>I need no other argument,<br>I need no other plea;<br>It is enough that Jesus died,<br>And that He died for me.</p>\n<p><strong>2.</strong><br>Enough for me that Jesus saves,<br>This ends my fear and doubt;<br>A sinful soul I come to Him,<br>He’ll never cast me out.</p>\n<p><strong>3.</strong><br>My heart is leaning on the Word,<br>The written Word of God,<br>Salvation by my Savior’s name,<br>Salvation through His blood.</p>\n<p><strong>4.</strong><br>My great Physician heals the sick,<br>The lost He came to save;<br>For me His precious blood He shed,<br>For me His life He gave.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(257, 'WHO AM I', 'pending', NULL, '<p><strong>1.</strong><br>Amazing grace! how sweet the sound!<br>That saved a wretch like me;<br>I once was lost, but now am found;<br>Was blind, but now I see.<br>’Twas grace that taught my heart to fear,<br>And grace my fears relieved;<br>How precious did that grace appear,<br>The hour I first believed!</p>\n<p><strong>Chorus:</strong><br>Who am I?<br>That he knows my name so well?<br>Who am I?<br>That he loves me so much?<br>Who am I?<br>That I shall possess, within the veil, I life of joy and peace,<br>who am I? I life of join and peace, who am I?.</p>\n<p><strong>2.</strong><br>Through many dangers, toils and snares,<br>I have already come:<br>’Tis grace that brought me safe thus far,<br>And grace will lead me home.<br>Yes, when this heart and flesh shall fail,<br>And mortal life shall cease,<br>I shall possess within the veil,<br>A life of joy and peace.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(258, 'I LOVE MY SAVIOUR TOO', 'pending', NULL, '<p><strong>1.</strong><br>Jesus, my heavenly King, loves me, I know, Praises to Him I sing, onward I go; Closely to Him I cling, blessings still flow, I love my Savior, too.</p>\n<p><strong>Chorus:</strong><br>Yes I truly love my blessed Savior, blessed Saviour and ever He loves me too;<br>Humbly now I seek His grace and favor(grace and favour) In everything I do.</p>\n<p><strong>2.</strong><br>Walking with Him each day, lovelight doth shine, Doing His will alway, never repine; Kneeling to Him I pray, "Thy will, not mine," I love my Savior, too..</p>\n<p><strong>3.</strong><br>Happy to serve my friend, lean on His arm, Rapture will never end, nothing alarm; Voices will sweetly blend, under His charm, I love my Savior, too.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(259, 'HOLY GOD WE PRAISE YOUR NAME', 'pending', NULL, '<p><strong>1.</strong><br>Holy God, we praise your name;<br>Lord of all, we bow before you!<br>All on earth your sceptre claim,<br>All in heaven above adore you,<br>Infinite your vast domain,<br>Everlasting is your reign!</p>\n<p><strong>2.</strong><br>Hark! the loud celestial hymn,<br>Angel choirs above are raising!<br>Cherubim and Seraphim,<br>In unceasing chorus praising,<br>Fill the heavens with sweet accord,<br>Holy, holy, holy, Lord!</p>\n<p><strong>3.</strong><br>Holy Father, Holy Son!<br>Holy Spirit, Three we name you,<br>While in essence only One,<br>Undivided God we ’claim you,<br>And adoring bend the knee,<br>While we own the mystery.</p>\n<p><strong>4.</strong><br>Spare your people, Lord, we pray,<br>By a thousand snares surrounded;<br>Keep us without sin today;<br>Never let us be confounded,<br>Lo, I put my trust in you –<br>Never Lord, abandon me.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(260, 'COME WORSHIP THE LORD', 'pending', NULL, '<p><strong>Chorus:</strong><br>Come worship the Lord of Lord, the King of glory<br>Come into his presence and praise his holy name.<br>Come let us adore him and praise his holy name,<br>Let us worship his majesty who\'s on his throne above.</p>\n<p><strong>1.</strong><br>Serve you the Lord, heart filled with gladness,<br>Come into His Presence singing for joy!<br>Know that the Lord is our Creator.<br>Yes, He is our Father; we are His sons.</p>\n<p><strong>2.</strong><br>We are the sheep of His green pasture,<br>For we are His people; He is our God.<br>Enter His gates bringing thanksgiving,<br>O enter His courts while singing His praise.</p>\n<p><strong>3.</strong><br>Our Lord is good, His love enduring,<br>His word is abiding now with all people.<br>Honour and praise be to the Father,<br>The Son, and the Spirit, world without end.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(261, 'LORD PURIFY OUR GIFTS', 'pending', NULL, '<p><strong>1.</strong><br>Lord accept our offering please Sanctify bread and wine<br>Make it worthy unto you<br>Please receive our gift</p>\n<p><strong>Chorus:</strong><br>Lord purify our gift<br>At the hands of your priest<br>Make it a living sacrifice<br>Please receive our gift<br>Make it a living sacrifice<br>Please receive our gift</p>\n<p><strong>2.</strong><br>Lord bless your people<br>Please sanctify our hearts and mind<br>Make us one in communion<br>Please receive our gift</p>\n<p><strong>3.</strong><br>Lord we are calling upon your name<br>(Please receive our gift)<br>Your children are calling upon your name<br>(Please receive our gift)<br>We offer together our gift at the altar<br>(Please receive our gift)<br>As a sign of remembrance as Jesus commanded<br>(Please receive our gift)</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(262, 'GOD OF MERCY AND COMPASSION', 'pending', NULL, '<p><strong>1.</strong><br>God of mercy and compassion<br>Look with pity upon me<br>Father, let me call thee Father<br>Tis\' thy child returns to thee<br>Jesus Lord, I ask for mercy<br>Let me not implore in vain<br>All my sins I now detest them<br>Never will I sin again</p>\n<p><strong>2.</strong><br>By my sins I have deserved<br>Death and endless misery<br>Hell with all its pains and torments<br>And for all eternity</p>\n<p><strong>3.</strong><br>By my sins I have abandoned<br>Right and claim to heaven above<br>Where the saints rejoice forever<br>In a boundless sea of love</p>\n<p><strong>4.</strong><br>See our Saviour, bleeding, dying<br>On the cross of Calvary<br>To that cross my sins have nail\'d him<br>Yet he bleeds and dies for me</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(263, 'IN THE LORD I\'LL BE EVER THANKFUL', 'pending', NULL, '<p>In the Lord I\'ll be ever thankful,<br>In the Lord I\'ll rejoice.<br>Look to God, do not be afraid,<br>Lift up your voices, the Lord is near;<br>Lift up your voices the Lord is near.</p>\n<p>You are my salvation.<br>I trust in you.<br>I shall not be afraid,<br>You are my strength,<br>You are my song.<br>The Lord is my Rock<br>The Lord is my fortress.<br>My God, You are my refuge and my shield.</p>\n<p>My God, You are at my right hand,<br>He is worthy of praise.<br>The Lord shall save me.<br>My soul shall sing to You,<br>Your act and wonderous things O God.<br>Let me speak more of Your act O Lord.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(264, 'DO YOU KNOW MY JESUS?', 'pending', NULL, '<p><strong>1.</strong><br>Have you a heart that’s weary, tending a load of care;<br>Are you a soul that’s seeking Rest from the burden you bear?</p>\n<p><strong>Chorus:</strong><br>Do you know, do you know, my Jesus, do you know, do you know my friend,<br>Have you heard, have you heard He loves you, and that He will abide till the end?</p>\n<p><strong>2.</strong><br>Where is your heart, O pilgrim, what does your light reveal?<br>Who hears your call for comfort when naught but sorrow you feel?</p>\n<p><strong>3.</strong><br>Who knows your disappointments, who hears each time you cry;<br>Who understands your heart aches, who dry the tears from your eyes?</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(265, 'WHEN I SURVEY', 'pending', NULL, '<p><strong>1.</strong><br>When I survey the wondrous cross,<br>On which the prince of Glory died,<br>My richest gain I count but loss,<br>And poor contempt on all my pride.</p>\n<p><strong>2.</strong><br>Forbid it Lord, that I should boast,<br>Save in the death of Christ my God;<br>All the vain things that charm me most,<br>I sacrifice them to His blood.</p>\n<p><strong>3.</strong><br>See! from His head, His hands, His feet,<br>Sorrow and love flow mingled down!<br>Did e’er such love and sorrow meet,<br>Or thorns compose so rich a crown?</p>\n<p><strong>4.</strong><br>Were the whole realm of nature mine,<br>That were an offering far too small;<br>Love so amazing, so Divine,<br>Demands my soul, my life, my all.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(266, 'O COME AND MOURN WITH ME A WHILE', 'pending', NULL, '<p><strong>1.</strong><br>O come and mourn with me a while,<br>See Mary calls us to her side;<br>O come and let us mourn with her,<br>Jesus, our Love, is crucified.</p>\n<p><strong>2.</strong><br>Have we no tears to shed for Him;<br>While soldiers scoff and Jews deride?<br>Ah! look how patiently He hangs;<br>Jesus, our Love, is crucified.</p>\n<p><strong>3.</strong><br>How fast His feet and hands are nailed;<br>His blessed tongue with thirst is tied;<br>His failing eyes are blind with blood;<br>Jesus, our Love, is crucified.</p>\n<p><strong>4.</strong><br>Seven times He spoke, seven words of love,<br>And all three hours His silence cried<br>For Mercy on the souls of men;<br>Jesus, our Love, is crucified.</p>\n<p><strong>5.</strong><br>O break, O break hard heart of mine;<br>Thy weak self-love and guilty pride<br>His Pilate and His Judas were;<br>Jesus, our Love, is crucified.</p>\n<p><strong>6.</strong><br>A broken heart, a fount of tears,<br>Ask and they will not be denied;<br>A broken heart love\'s cradle is;<br>Jesus, our Love, is crucified.</p>\n<p><strong>7.</strong><br>O love of God! O sin of man!<br>In this dread act your strength is tried<br>And victory remains with love;<br>Jesus, our Love is crucified.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(267, 'MY LORD AND MY GOD', 'pending', NULL, '<p><strong>Chorus:</strong><br>You are my Lord; my God I can’t do without you<br>My Lord my God my all.<br>I give thee Lord my all, Lord take and sanctify,<br>My Lord my God my all.</p>\n<p><strong>1.</strong><br>Here is the bread, here is the wine,<br>Christ is with us, Breaking the bread, He is the Bread.<br>Here is the bread, here is the wine. Christ is with us.<br>Blessing the wine, he is the Wine.</p>\n<p><strong>2.</strong><br>Here is the Grace, here is the peace.<br>Christ is with us, knowing His grace deep in our hearts.<br>Here is the Grace, here is the peace,<br>Christ is us, finding His peace deep in our soul.</p>\n<p><strong>3.</strong><br>Sharing the bread, sharing the wine.<br>Christ is with us, sharing the bread, healing my heart,<br>Sharing the bread, sharing the wine.<br>Christ is with us, sharing the wine, healing my soul</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(268, 'WHATSOEVER YOU DO', 'pending', NULL, '<p><strong>Chorus:</strong><br>Whatsoever you do to the least of my brothers<br>That you do unto me.</p>\n<p><strong>1.</strong><br>When I was hungry you gave me to eat,<br>When I was thirsty you gave me to drink,<br>Now enter into the home of my Father.</p>\n<p><strong>2.</strong><br>When I was homeless you opened your door,<br>When I was naked you gave me your coat,<br>Now enter into the home of my Father.</p>\n<p><strong>3.</strong><br>When I was weary you helped me find rest,<br>When I was anxious you calmed all my fears,<br>Now enter into the home of my Father.</p>\n<p><strong>4.</strong><br>When I was restless, you listened and cared,<br>When I was lonely you gave me your love,<br>Now enter into the home of my Father.</p>\n<p><strong>5.</strong><br>When in a prison you came to my cell,<br>When on a sick bed, you cared for my needs,<br>Now enter into the home of my Father.</p>\n<p><strong>6.</strong><br>In a strange country you made me at home,<br>Seeking employment you found me a job,<br>Now enter into the home of my Father.</p>\n<p><strong>7.</strong><br>Hurt in the battle, you bound up my wounds,<br>Searching for kindness you held out your hand,<br>Now enter into the joy of my Father.</p>\n<p><strong>8.</strong><br>When I was laughed at, you stood at my side,<br>When I was happy, you shared in my joy,<br>Now enter into the home of my Father.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(269, 'WHY CAN\'T YOU SAY THANK YOU', 'pending', NULL, '<p><strong>Chorus:</strong><br>We bring our gift to you O Lord,<br>All that we have we bring to you O Lord,<br>Stretch out your hand and pour your blessings on your children<br>Here we are O Lord, asking for your blessings<br>On our families and friends.</p>\n<p><strong>1.</strong><br>The Lord created you, you are beautiful,<br>He designed you and made you unique, O Yes!<br>This is a miracle of creation,<br>O it\'s Wonderful!<br>Why can\'t you say thank you?</p>\n<p><strong>2.</strong><br>Did I hear you say that God left you without a gift,<br>Were you born with deformation? O No!<br>Your legs, your hands, your senses are intact.<br>How much did you pay?<br>Why can\'t you say thank you?</p>\n<p><strong>3.</strong><br>If you really insist that you are without a gift<br>Find time to visit the hospital, O yes!<br>Go round the streets and see the beggers,<br>Then come back with gratitude.<br>Why can\'t you say thank you?</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(270, 'THE LORD BLESS AND KEEP YOU', 'pending', NULL, '<p>The Lord bless you and keep you;<br>the Lord lift his countenance upon you, and give you peace;<br>the Lord make his face to shine upon you, and be gracious unto you.<br>Amen, amen.......</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(271, 'IN CHRIST ALONE', 'pending', NULL, '<p><strong>1.</strong><br>In Christ alone my hope is found<br>He is my light, my strength, my song<br>This cornerstone, this solid ground<br>Firm through the fiercest drought and storm<br>What heights of love, what depths of peace<br>When fears are stilled, when strivings cease<br>My comforter, my all in all<br>Here in the love of Christ I stand</p>\n<p><strong>2.</strong><br>In Christ alone who took on flesh<br>Fullness of God in helpless babe<br>This gift of love and righteousness<br>Scorned by the ones He came to save<br>Till on that cross as Jesus died<br>The wrath of God was satisfied<br>For every sin on Him was laid<br>Here in the death of Christ I live</p>\n<p><strong>3.</strong><br>There in the ground His body lay<br>Light of the world by darkness slain<br>Then bursting forth in glorious day<br>Up from the grave He rose again<br>And as He stands in victory<br>Sin\'s curse has lost its grip on me<br>For I am His and He is mine<br>Bought with the precious blood of Christ</p>\n<p><strong>4.</strong><br>No guilt in life, no fear in death<br>This is the power of Christ in me<br>From life\'s first cry to final breath<br>Jesus commands my destiny<br>No power of hell, no scheme of man<br>Can ever pluck me from His hand<br>Till He returns or calls me home<br>Here in the power of Christ I\'ll stand</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(272, 'OH, THE LOVE OF MY LORD', 'pending', NULL, '<p><strong>1.</strong><br>Oh, the love of my Lord is the essence<br>of all that I love here on earth.<br>All the beauty I see he has given to me<br>and his giving is gentle as silence.</p>\n<p><strong>2.</strong><br>Every day, every hour, every moment<br>have been blessed by the strength of his love,<br>At the turn of each tide,<br>he is there at my side,<br>and his touch is as gentle as silence.</p>\n<p><strong>3.</strong><br>There\'s been times when I\'ve turned<br>from his presence,<br>And I\'ve walked other paths, other ways.<br>But I\'ve called on his name in the dark<br>of my shame,<br>And his mercy was gentle as silence.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(273, 'WE LONG TO SEE THEE SO', 'pending', NULL, '<p><strong>1.</strong><br>We long to see Thee so,<br>To see the newly Born<br>We long for Christmas morn,<br>The sands of time run slow.</p>\n<p><strong>Chorus:</strong><br>O come, O come, O come,<br>Our Saviour dear to be,<br>O come, O come, O come,<br>We have no King but thee.</p>\n<p><strong>2.</strong><br>We long to see Thee so,<br>To see the Angels glory,<br>To hear their midnight story,<br>And with Thee Shepherds go.</p>\n<p><strong>3.</strong><br>We long to see Thee so,<br>No other joys can please us,<br>We want Thee Baby Jesus,<br>The sands of time run slow.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(274, 'I REJOICE WHEN I HEARD THEM SAY (PSALM 122)', 'pending', NULL, '<p><strong>Chorus:</strong><br>We shall go up into God’s house with<br>shouts of joy<br>We shall go into house of the Lord</p>\n<p><strong>1.</strong><br>I rejoiced when I heard them say:<br>“Let us go to God\'s house,”<br>And now our feet are standing<br>Within your gates, O Jerusalem.</p>\n<p><strong>2.</strong><br>Jerusalem is built as a city<br>strongly compact.<br>It is there that the tribes go up,<br>the tribes of the Lord.</p>\n<p><strong>3.</strong><br>For Israel\'s law it is<br>There to praise the Lord\'s name,<br>There were set the thrones of judgment,<br>Of the house of David.</p>\n<p><strong>4.</strong><br>For the peace of Jerusalem, pray:<br>“Peace be to your homes!<br>May peace reign in your walls,<br>In your palaces, peace!”</p>\n<p><strong>5.</strong><br>For love of my brethren and friends,<br>I say: “Peace upon you!”<br>For love of the house of the Lord,<br>I will ask for your good.</p>\n<p><strong>6.</strong><br>Praise the Father, the Son and Holy Spirit<br>Both now and forever,<br>The God who is, who was and is to come<br>At the end of the ages.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(275, 'I BELIEVE IN ONE GOD', 'pending', NULL, '<p><strong>Refrain:</strong><br>Bass: In one God the father.<br>All: I believe in one God the father</p>\n<p><strong>1.</strong><br>I believe in one God, the Father<br>Almighty, maker of heaven and earth,<br>of all things visible and invisible.</p>\n<p><strong>2.</strong><br>I believe in one Lord Jesus Christ,<br>the Only Son of God,<br>begotten of the Father.<br>God from God, Light from Light</p>\n<p><strong>3.</strong><br>True God from true God,<br>begotten, not made,<br>consubstantial with the Father;<br>through him all things were made.</p>\n<p><strong>4.</strong><br>For us men and for our salvation<br>He came down from heaven,<br>and by the Holy Spirit was incarnate of the<br>Virgin Mary, and became man.</p>\n<p><strong>5.</strong><br>For our sake he was crucified under Pontius Pilate,<br>he suffered death and was buried.</p>\n<p><strong>6.</strong><br>And rose again on the third day<br>in accordance with the Scriptures.<br>He ascended into heaven<br>and is seated at the right hand of the Father.</p>\n<p><strong>7.</strong><br>He will come again in glory<br>to judge the living and the dead<br>and his kingdom will have no end.</p>\n<p><strong>8.</strong><br>I believe in the Holy Spirit,<br>The Lord, the giver of life,<br>who proceeds from the Father and the Son,</p>\n<p><strong>9.</strong><br>Who with the Father and the Son<br>is adored and glorified,<br>who has spoken through the prophets.</p>\n<p><strong>10.</strong><br>I believe in one holy catholic and apostolic Church.<br>I confess one Baptism for the forgiveness of sins</p>\n<p><strong>11.</strong><br>And I look forward to the resurrection<br>To the resurrection of the dead<br>and the life of the world to come.<br>Bass: Amen, Amen, Amen<br>All: Amen, Amen.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'creed'),
	(276, 'EARTHLY GIFTS', 'pending', NULL, '<p><strong>Chorus:</strong><br>Earthly gifts we offer you O God.<br>Receive us, O God,<br>And bless us, shower your blessings upon us.<br>Receive us, O God,<br>and bless us, shower your blessings upon us.</p>\n<p><strong>1.</strong><br>Our hearts we give you, full of thanks<br>come come come, come and bless your people,<br>Receive our hearts, we bring to you.<br>Come come come, come and bless your people.</p>\n<p><strong>2.</strong><br>We give You, gifts, bread and wine,<br>come come, come and bless your people,<br>Receive our gifts, we bring to you.<br>come come, come and bless your people.</p>\n<p><strong>3.</strong><br>We give You gifts from our hearts, come<br>come come come, come and bless your people,Receive our gifts, we give to you.<br>come come come, come and bless your people.</p>\n<p><strong>4.</strong><br>We give You praise, praise and thanks,<br>come come come, come and bless your people,<br>Receive our praise, we give to you.<br>come come come, come and bless your people.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(277, 'IN THANKSGIVING AND LOVE', 'pending', NULL, '<p><strong>REFRAIN:</strong><br>O yes in the presence of the Lord, I will bring my gift in thanksgiving and love<br>There is joy in my heart it is flowing like a river<br>I will praise the Lord<br>In thanksgiving and love</p>\n<p><strong>1.</strong><br>God our Father everlasting king, please accept this gift we offer<br>In thanksgiving and love<br>Take our bread upon Your altar and the wine in the chalice<br>In thanksgiving and love</p>\n<p><strong>2.</strong><br>With thankful hearts and joyful songs, we approach Your Holy Alter<br>In thanksgiving and love<br>Bearing gifts of Your creation, we return what You have given<br>In thanksgiving and love</p>\n<p><strong>3.</strong><br>To You Father now we offer with the Host and with the chalice<br>In the thanksgiving and love<br>All we have and all our being in this sacrifice most Holy<br>In thanksgiving and love</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(278, 'EAT THIS BREAD', 'pending', NULL, '<p><strong>REFRAIN:</strong><br>Eat this bread drink this cup come to me and never be hungry<br>Eat this bread drink this cup trust in me and you will have rest</p>\n<p><strong>1.</strong><br>I am the bread of life a true bread sent from the Father</p>\n<p><strong>2.</strong><br>Your ancestors ate manner in the desert it is the bread that came down from heaven</p>\n<p><strong>3.</strong><br>Eat my flesh and drink my blood and I will raise you up on the last day</p>\n<p><strong>4.</strong><br>Anyone who eat this bread will live forever</p>\n<p><strong>5.</strong><br>If you believe and eat this bread you will have eternal life</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(279, 'THE COMING OF THE LORD', 'pending', NULL, '<p>lift up your heads O gates, and make the high straight, prepare to celebrate the coming of the lord. Your waiting will soon end<br>God\'s glory will descend, rise up and welcome in the coming of the lord! The coming of the lord.</p>\n<p>Prepare the way for the coming of the lord x2</p>\n<p>The ancient words foretell, God\'s with us, he will dwell, Christ our Emmanuel &amp; all will see the glory of the lord.</p>\n<p>lift up your heads O gates, and make the high straight, prepare to celebrate the coming of the lord. Your waiting will soon end<br>God\'s glory will descend, rise up and welcome in the coming of the lord! The coming of the lord.</p>\n<p>(Cantor )<br>O come o come Emmanuel and Ransome captive Israel.<br>O come o come prepare the way .<br>O come prepare the way, prepare the way,<br>O come prepare the way of the lord and then the deaf will hear, the blind will see him clear , the mute will find their voice, the lame will leap for joy. Prepare the way of the coming of the lord. Rejoice, rejoice, Emmanuel, our God will come to us, prepare the way for the coming of the lord.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(280, 'WAIT FOR THE LORD', 'pending', NULL, '<p>Wait for the Lord, whose day is near<br>Wait for the Lord, be strong take heart</p>\n<p><strong>1.</strong><br>Prepare the way for the Lord<br>Make a straight path for Him</p>\n<p><strong>2.</strong><br>The Glory of the Lord shall be revealed<br>All the Earth will see the Lord</p>\n<p><strong>3.</strong><br>Rejoice in the Lord always,<br>God is at Hand<br>Joy and gladness for all who seek the Lord</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(281, 'COME GOD’S CHILDREN (CHB 49)', 'pending', NULL, '<p>Come God\'s children let us sing, alleluia.<br>Bringing gifts to praise our King, alleluia.<br>Drawing close in heart and mind, alleluia.<br>That by his aid the truth we\'ll find, alleluia.<br>We offer gifts of bread and wine, alleluia.<br>In Christ our Lord, the Son Divine, alleluia.<br>In joyful song our voices raise, alleluia.<br>To God above we offer praise, alleluia.<br>We must love him with all our heart, alleluia.<br>As a whole and not a part, alleluia.<br>Come God\'s children let us sing, alleluia.<br>Bringing gifts to praise our King, alleluia.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(282, 'PAPA YOU DO WELL', 'pending', NULL, '<p><strong>1.</strong><br>Since the time of Adam<br>Come reach today soh<br>I never see anybody wey dey like my papa God<br>(Because) I don go many places see many things hear many tori,<br>The main topic na the good good things wey God dey do</p>\n<p>(Because) I don go many places see many things hear many tori,<br>The main topic na the good good things wey God dey do</p>\n<p>Mighty father we dey hail you,<br>We dey praise you,<br>You be baba Ewoo, you do well (2x)</p>\n<p>You dey make me wonder<br>Make me happy,<br>You dey give me joy<br>You dey make me jolly<br>Sotey I dey denge pose<br>I dey make Iyanga<br>For all the blessings wey you give me dey boku-boku<br>Na im make I come<br>To come hail you Lord<br>Na im make I come to say thank you.</p>\n<p>(Baba you do well)<br>Mungode, Ese oh, Daalu oh, Uwese<br>Anya oh, Agba oh<br>Magode papa you do well<br>Anya anya!!!<br>Obulu, Doo Jesu, Masu yebo, Se-ba-su we<br>Imokon- fi, Tinji-gwe-je<br>We thank you papa you do</p>\n<p>Mighty father we dey hail you,<br>We dey praise you,You be baba Ewoo, you do well</p>\n<p><strong>2.</strong><br>Anytime I ask you dey give me<br>Anytime I seek I dey find<br>Anytime I knock you dey open your door<br>Anytime I call you dey answer</p>\n<p>You dey make me wonder, Make me happy,<br>You dey give me joy, You dey make me jolly<br>Sotey I dey denge pose, I dey make Iyanga<br>For all the blessings wey you give me dey boku-boku<br>Na im make I come,  To come hail you Lord<br>Na im make I come to say thank you.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(283, 'GREAT VICTOR', 'pending', NULL, '<p><strong>REFRAIN:</strong><br>Great Victor Lord Jesus Christ here we are in Your dwelling place with songs of praise and thanksgiving we honor You Victorious King</p>\n<p><strong>1.</strong><br>You take all my quilt away for you have turn the darkest night to brightest day</p>\n<p><strong>2.</strong><br>You are the comforter of my soul my restorer victorious king</p>\n<p><strong>3.</strong><br>Love that conquers every fear for I know in the midst of trouble you draw near</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(284, 'COME FOLLOW ME', 'pending', NULL, '<p><strong>1.</strong><br>Come follow me<br>I am going to that great city where Jesus reigns</p>\n<p><strong>REFRAIN:</strong><br>Come follow me,<br>the Lord is calling on you and me,<br>come follow me come follow me,<br>come come come come come come come come follow me…</p>\n<p><strong>2.</strong><br>Come follow me<br>I am going to mount Zion where Jesus is King.</p>\n<p><strong>3.</strong><br>Come follow me<br>I am going, I am going , I am going</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(285, 'K’ANYI JEE N’OBI EZE', 'pending', NULL, '<p>Obi na aso muo aiyeiye obi na aso muo o<br>Mgbe m nuru ka ha na asi eh<br>Ka anyi jeenu n\'ulo nso,<br>Ka anyi jeenu n\'obi Eze eh<br>Onye ihe nile di n\'aka ya<br>Onye ji aka ya diri n\'onwe ya<br>Onye n\'enwero mbido<br>Nke oji enwe njedebe oh<br>Chineke Eze ukwu<br>Nwanne m were anuri bata<br>K\'anyi kelee chineke Onyeoma.</p>\n<p><strong>1.</strong><br>Osebuluwa Nara ekele<br>Onye nwe mmadu abiara m be gi<br>Anyi si ka anyi bia kpooro gi isi ala<br>n\'ihi na emere anyi ebuka<br>Ogologo ndu I na enye anyi<br>Aru Ike anyi di gi n\'aka<br>Ji na ede anyi na ako bu oru aka gi<br>Umu na uba anyi bu oru aka gi<br>Ya ka anyi ji bia n\'iru gi<br>Ikporo gi isiala aiyeye</p>\n<p><strong>2.</strong><br>Lee iheoma nile di n\'uwa ebube ebube ebube<br>ugwu na ndida n\'ile hancha bu oruaka ya<br>Onwa na Kpakpando nwannem okwa chukwu<br>Kere ha anu elu na anu mmiri na anuala tobe Chukwu<br>Uwa na iheoma nile di n\'ime ya bu nke giezi chukwu gi n\'elekota ha<br>onyeze chineke abiaram be gi omalicha</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(286, 'O BONG TUA NYIN MBOM', 'pending', NULL, '<p>O bong Obong tu a nyin  mbom o bong tu a nyin mbom,  o bong Obong tu a nyin mbom.</p>\n<p>Christ tua nyin mbom<br>tua nyin mbom, tu a nyin mbom Christ tua nyin mbom, Christ tu a nyin mbom.</p>\n<p>O bong Obong tu a nyin mbom o bong tua nyin mbom, o bong Obong tu a nyin mbom.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'kyrie'),
	(287, 'GLORY TO GOD ON HIGH (NIGERIAN STYLE)', 'pending', NULL, '<p>Glory to God, Glory to God, Glory to God on high.</p>\n<p><strong>1.</strong><br>Glory to God in the highest!<br>Peace to his people on earth.<br>Lord God, Almighty Father (We raise our voices)</p>\n<p><strong>2.</strong><br>The most high God heavenly King,<br>we worship you, we give you thanks,<br>we praise you for your glory.(We raise our voices)</p>\n<p><strong>3.</strong><br>Jesus Christ, only Son of the Father,<br>Lord God, Lamb of God and Saviour<br>you take away the sin of the men(We raise our voices)</p>\n<p><strong>4.</strong><br>Lamb of God have mercy on us;<br>you are equal to the father<br>Kindly receive our petitions(We raise our voices)</p>\n<p><strong>5.</strong><br>You alone are the Holy One,<br>you alone are the Lord,<br>you alone are the Most High God(We raise our voices)</p>\n<p><strong>6.</strong><br>Jesus you reign with the Father<br>Christ you reign with the spirit<br>Before time and for ever(We raise our voices)</p>\n<p><strong>7.</strong><br>Amen Alleluia Amen ×2<br>Glory to God on high(We raise our voices)</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'gloria'),
	(288, 'IN THE FATHER I BELIEVE', 'pending', NULL, '<p><strong>Chorus:</strong><br>In the Father, I believe  Yes, I believe<br>In the Spirit I believe three in one , I believe ( 2 times)</p>\n<p><strong>1.</strong><br>I believe in one God, the Father Almighty<br>And in Jesus the son of God, maker of heaven and earth</p>\n<p><strong>2.</strong><br>He was conceived by the spirit, born of the Virgin Mary<br>Suffered death and was crucified, under Pontius Pilate</p>\n<p><strong>3.</strong><br>He descended into hell, He rose on the third day.<br>He ascended into heaven seated at the right hand of God.</p>\n<p><strong>4.</strong><br>He will come again in glory, to judge the living and dead.<br>And His kingdom will have no end, and His kingdom will have no end.</p>\n<p><strong>5.</strong><br>I believe in the Spirit, the Catholic and Apostolic church,<br>The communion of saints, the forgiveness of sins</p>\n<p><strong>6.</strong><br>I look forward, to the resurrection of the dead.<br>And the life of the world to come, in the glory of the Lord.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'creed'),
	(289, 'DADA KABATI', 'pending', NULL, '<p><strong>Chorus:</strong><br>Dada kabati bin ka ti goro<br>Kaba tibinka ti goro<br>Dada kabati bin ka ti goro<br>Dada kabati bin ka tu ji ra<br>bin ka tu ji ra a sap ta goro</p>\n<p><strong>VERSE 1:</strong><br>Kabi ita mi kabi ita mi<br>Kaba en mi ji ra I sap ta goro<br>Tiyi tiu en na gun ghu tsai su go ro<br>Tsai su go ro na fa rin ci ki ki ni ti go diya</p>\n<p><strong>VERSE 2:</strong><br>Kaba mini kaba mini<br>Kaba enmi ji ra I sap tagoro<br>Tsaisu go ro na farin ci ki<br>Kini ti go diya<br>Kini ti go diya</p>\n<p><strong>VERSE 3:</strong><br>Timagi di nu ida tha namatha ra mo-wa sap ta goro</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(290, 'O MAI TSARKI', 'pending', NULL, '<p><strong>1.</strong><br>O Mai Tsarki<br>O o Mai tsarki<br>Ubangiji Ubangiji<br>Allah Mai rudunan o<br>O Mai Tsarki (Allah),<br>(Allahmai tsarki)<br>Sama da Kasa a cike suke da-darajarka.</p>\n<p><strong>Chorus:</strong><br>Hossanna, a cikin samaniya<br>Hossanna, a cikin samaniya o 2x</p>\n<p><strong>2.</strong><br>O Mai Tsarki<br>O Mai Tsarki<br>Mai albarkane ya Mai tsarki o<br>Wande yeke zuwa<br>Wande yake zuwa<br>A cikin sunan Ubangiji<br>Hossanna, a cikin samaniya o 2x</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'sanctus'),
	(291, 'WAN YONGU (TIV AGNUS DEI)', 'pending', NULL, '<p>Wan yon-gu u Aon-do<br>We u u-ter a sora bo<br>A ta-regh ke-ra ke-ra<br>Zun gwe se m-ho-o num</p>\n<p>Wan yon-gu u Aon-do<br>We u u-ter a sora bo<br>A ta-regh ke-ra ke-ra<br>Na se, na se be-em</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'agnus_dei'),
	(292, 'JESU VBU WE EUCHARISTIA', 'pending', NULL, '<p>E te do gh\'osa i jesu vbuwe Eucharistia wa do gh\'osa i Jesu vbuwe eucharistia La re do e noe ogha mi i mie fan ib da noda ogha mi mie fan Uyi\'osa</p>\n<p><strong>1.</strong><br>Wa hia gima dorie vbareaghon<br>O wan norie vbareagbon omiagbon nenwafe o<br>E-te wa ya yi o gha mie we fan mamiosa kpo logbe wahyia diogh\'osalobua</p>\n<p><strong>2.</strong><br>Wa hia gima rie i fungbi jesu<br>O wan no ri funegb\'i jesu e- ghiwhu o<br>Rhumhudi Jesu we Ogha rio kpae gbe mamiosa kpo logbe Wahya dogh\'osalobua.</p>\n<p><strong>3.</strong><br>Wa hia gima yegbe k\'osalobua<br>o wan noye gbe ko salua e ghi de o,<br>Eten wa ya yi o ghamie we fan ma miosa kpo logbe Wahya diogh\'o salobua.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(293, 'JESUS AHA NA-ATOM UTO', 'pending', NULL, '<p>Jesus aha n’atom uto Jesus aha n’atom uto Jesus aha kachasi ebube site n’ugwu rue na ndi da, Jesus aha gi di uto Jesus, Jesus, Jesus aha kachasi Ebube n’enye ndu ebighi ebi</p>\n<p><strong>1.</strong><br>Ihunaya nke Jesus,<br>Ihunaya nke Jesus,<br>Ihunaya nke Jesus enweghi mgbanwe obula<br>Ihunaya Ihunaya Ihunaya Ihunaya Ihunaya nke Jesus na digi de o.</p>\n<p><strong>2.</strong><br>N’ime nkpagbum nile n’ime ahu hum nile n’ime nsogbum nile<br>Jesus n’azoputa  obu Jesus obu Jesus obu Jesus n’azoputa mo<br>n’azoputa nke Jesus n’a digi de o.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(294, 'MAKE ME A CHANNEL OF YOUR PEACE', 'pending', NULL, '<p><strong>1.</strong><br>Make me a channel of your peace<br>Where there is hatred let me bring your love<br>Where there is injury, your pardon Lord<br>And where there is doubt true faith in You</p>\n<p><strong>2.</strong><br>Make me a channel of your peace<br>Where there is despair in life let me bring hope<br>Where there is darkness only light<br>And where there\'s sadness ever joy</p>\n<p><strong>Chorus:</strong><br>Oh, Master grant that I may never seek<br>So much to be consoled as to console<br>To be understood as to understand<br>To be loved as to love with all my soul</p>\n<p><strong>3.</strong><br>Make me a channel of your peace<br>It is in pardoning that we are pardoned<br>It is in giving to all men that we receive<br>And in dying that we are born to eternal life.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(295, 'MUNGODE ALLAH', 'pending', NULL, '<p><strong>Chorus:</strong><br>Domin Ka kawo mu awa nara nayo<br>Domin Ka kawo mu awa nara nayo mungode Allah<br>Mungode Allah<br>Mungode Allah<br>Mungode Allah, Allah sariki.</p>\n<p><strong>Verse1:</strong><br>Da ye-wa suke abubuwa nda kaba mu 2x  mungode Allah</p>\n<p><strong>Verse2:</strong><br>Da ye wa suke Jindadi nda ka bamu</p>\n<p><strong>Verse 3:</strong><br>Da ye wa suke Albarka nda mu kerbi</p>\n<p><strong>Verse 4:</strong><br>Da kuma ruwan sama nda Ka ba mu</p>\n<p><strong>Verse 5:</strong><br>Da kuma hasken rana nda kaba mu</p>\n<p><strong>Verse 6:</strong><br>Da kuma iska nda mu kerbi nda Ka ba mu</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(297, 'PRIESTLY PEOPLE', 'pending', NULL, '<p><strong>Chorus:</strong><br>Priestly people Kingly people Holy people<br>God\'s chosen people sing praise to the Lord</p>\n<p>We sing to you o Christ beloved son of the Father<br>We give you praise O wisdom ever lasting and Word of God</p>\n<p>We sing to you O Son born of Mary the Virgin<br>We give you praise our Brother born to heal us Our saving Lord</p>\n<p>We sing to you O brightness of splendour and glory<br>We give you praise O Morning Star announcing the coming day</p>\n<p>We sing to you O light bringing men out of darkness<br>We give you praise O guiding Light who shows us the way to heaven</p>\n<p>We sing to you Messiah foretold by the Prophets<br>We give you praise O son of David and son of Abraham</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(298, 'OBI EZE CHUKWU', 'pending', NULL, '<p>Ebea bu ebe di egwu nkea b"ulo nso Chukwu onu Uzo nke eligwe aga akpo ya obi eze Chukwu di nso</p>\n<p><strong>1.</strong><br>O Nna ji Ike Nile anyi abiago ikpo isi ala Nye<br>Gi, meere anyi Ebere anyi biara nobi gi Chukwu</p>\n<p><strong>2.</strong><br>Anyi biara nihu gi Chineke inye gi ekele kwesiri gi , Gee nti Nuru ekpere anyi, anyi biara nobi gi Chukwu</p>\n<p><strong>3.</strong><br>Gee nti Nuru olu anyi gee nti Nuru aririo anyi,<br>denye aha anyi n"akwukwo ndu  anyi biara nobi gi Chukwu</p>\n<p><strong>4.</strong><br>Anyi ga efe gi uwatuwa Biko, Chukwu Mee ka anyi binyere gi<br>Ka Ngozi rukwasi anyi Chineke anyi biara nobi gi Chukwu</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(299, 'OROVWORI NA RUEDON', 'pending', NULL, '<p>Orovwori na ruedon na ruedon ravware Orovwori naruedon,<br>(Orovwori naruedon)<br>Orovwori naruedon, Na ruedon ravware<br>Orovwori naruedon<br>(Orovwori naruedon)<br>Orovwori na ruedon,<br>na ruedon, na ruedon,<br>ravware.</p>\n<p>Ikristi naruedon naruedon ravware<br>Ikristi naruedon<br>(IKristi naruedon)<br>Ikristi naruedon naruedon  ravware<br>Ikristi naruedon<br>(Ikristi naruedon)<br>Ikristi naruedon<br>na ruedon, na ruedon<br>ravware</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'kyrie'),
	(300, 'OJIMA CHEYI OJO', 'pending', NULL, '<p><strong>CHORUS:</strong><br>Ojima Cheyi Ojo,  k’ida ta te<br>Ojima Cheyi ojo k’ida ta te<br>Ojima Cheyi Ojo,  k’ida ta te<br>Ojima Cheyi ojo k’ida ta a te.</p>\n<p><strong>1.</strong><br>Kpai edebo k’iche we,<br>Amen okpo kpa efile<br>Awa k’ele we,<br>Awa d’uguwe adojima uwe, Achugbe dewe</p>\n<p><strong>2.</strong><br>Todu Ojima lile ewe,<br>Ada nyekwugwo we ondu<br>k’ichojo Onuaye ojale<br>ojo ata odobogagwu,<br>kpai jesu Kristi ondu wa o makate eyi ata.</p>\n<p><strong>3.</strong><br>Ondu k’iche ojo,<br>Omale eyi ojo,<br>wekia k’ebiene<br>Ile rinyo,<br>gbaduwa ewa onduwa</p>\n<p><strong>4.</strong><br>Uwe k’egwugwuawato e ojo, cheju mo miwa ondu wa,<br>Todu k’uwe kate ch’ina<br>uwe, kate che ondu,<br>uwe kate o, Jesu Kristi</p>\n<p><strong>5.</strong><br>Uwe kpai, Af’ina dama<br>Ef’ojima Eyi ojo ata,<br>Amen, Amen, Amen.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'gloria'),
	(301, 'SETIA AKA GI NARA', 'pending', NULL, '<p><strong>Chorus:</strong><br>Setia aka gi nara Aja anyi na achu,<br>setia aka gi nara Aja anyi na achu Nara Aja ekele umu gi na achu n\'altar gi di nso nihu ebube eze gi</p>\n<p>Aja anyi na achunyere gi bu Maka afo oma gi na ngozi gi na ogo gi Nile Nara Aja ekele umu gi na achu n\'altar gi di nso nihu ebube eze gi</p>\n<p>Achicha ukochukwu n\'erughari bu onyinye anyi butere gi nara Aja ekele umu gi na achu n\'altar gi di nso nihu ebube eze gi</p>\n<p>Iko nke nzoputa k\'anyi n\'ehunyere gi na akpoku aha gi si nara Aja ekele umu gi na achu n\'altar gi di nso nihu ebube eze gi</p>\n<p>Nwaturu ejiri chuo aja nwaturu ejiri chuo aja Onye na achu Aja ma burukwa ihe ejiri chuo aja  di nso</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(302, 'EYEN ERONG ABASI', 'pending', NULL, '<p>Eyen erong Abasi emi...emende<br>M\'i diok\'m kpo<br>Ererim bot efep<br>tua tua yi mbom<br>Tua yin bom tua yin bom</p>\n<p>Eyen erong Abasi emi...emende<br>M\'i diok\'m kpo<br>Erim bot efep<br>No yin noyin emem<br>Noyin emem noyin emem</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'agnus_dei'),
	(303, 'ANCIENT WORDS', 'pending', NULL, '<p><strong>1.</strong><br>Holy words long preserved<br>For our walk in this world<br>They resound with GOD\'s own heart<br>O let the ancient words impart</p>\n<p>Words of life, words of hope<br>Give us strength, help us cope<br>In this world where e\'er we roam<br>Ancient word will guide us home.</p>\n<p><strong>Chorus:</strong><br>Ancient words ever true<br>Changing me and changing you<br>We have come with open hearts<br>Oh let the ancient words impart</p>\n<p><strong>2.</strong><br>Holy words of our faith<br>Handed down to this age<br>Came to us through sacrifice<br>Oh heed the faithful words of Christ</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(304, 'ANDINO UWEM', 'pending', NULL, '<p><strong>1.</strong><br>Oboñ enyoñ y\'inyan y\'soñ, O! bo itoro Ye Uboñ<br>Nam nnyin ima kpafi ikpoñ,<br>O! Andino, O! Andino</p>\n<p><strong>Chorus:</strong><br>O! Andino, (uwen ke mfon)<br>O! Andino, (nson idem)<br>O! Andino, (uwen ke mfon)<br>O! Andino, (nfon idem)<br>nam nyim ima kpa fi ikpon<br>O! Andino, O! Andino</p>\n<p><strong>2.</strong><br>Afo Oboñ One uwem, Udia ñko yinsoñ idem<br>Okoro ye kpukpru mm\'eno<br>O! Andino, O! Andino</p>\n<p><strong>3.</strong><br>Afo one ikpom Eyen Eno okpon akan Efen<br>man edifak nnyin mi k\'isan<br>O! Andino, O! Andino</p>\n<p><strong>4.</strong><br>Se nnyin inode fi k\'ison, ikemkekem y\'ata uboñ<br>edinode nnyin ke enyoñ<br>O! Andino, O! Andino</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(305, 'O COME, ALL YE FAITHFUL', 'pending', NULL, '<p><strong>1.</strong><br>O come all ye faithful,<br>Joyful and triumphant,<br>O come ye, O come ye to Bethlehem;<br>Come and behold Him,<br>Born the King of angels:</p>\n<p><strong>Chorus:</strong><br>O come, let us adore Him,<br>O come, let us adore Him,<br>O come, let us adore Him,<br>Christ the Lord.</p>\n<p><strong>2.</strong><br>Sing, choirs of angels,<br>Sing in exultation,<br>Sing, all ye citizens of heaven above,<br>Glory to God<br>In the highest glory:</p>\n<p><strong>3.</strong><br>Saviour, we greet you,<br>Born this happy morning,<br>Jesus, to you be all glory given;<br>Word of the Father,<br>Now in the flesh appearing.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(306, 'HARK! THE HERALD ANGELS SING', 'pending', NULL, '<p><strong>1.</strong><br>Hark! the herald angels sing:<br>"Glory to the new-born King;<br>Peace on earth and mercy mild:<br>God and sinners reconciled."\nJoyful, all ye nations, rise,<br>Join the triumph of the skies;<br>With angelic hosts proclaim,<br>"Christ is born in Bethlehem."</p>\n<p><strong>Chorus:</strong><br>Hark! the herald angels sing:<br>"Glory to the new-born King."</p>\n<p><strong>2.</strong><br>Hail the heav\'n-born Prince of Peace!<br>Hail the Sun of righteousness!<br>Light and life to all He brings,<br>Risen with healing in His wings.<br>Mild He lays His glory by,<br>Born that man no more may die;<br>Born to raise the sons of earth,<br>Born to give them second birth.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(307, 'LORD HAVE MERCY (ON YOUR SERVANT)', 'pending', NULL, '<p>Lord have Mercy, Lord have Mercy<br>On your servant Lord have Mercy.<br>God Almighty Just and faithful,<br>Lord have Mercy, Lord Have Mercy.</p>\n<p>Christ have mercy, Christ have mercy,<br>Gift of Heaven Christ have Mercy,<br>Light of Truth and light of Justice,<br>Christ have Mercy, Christ Have Mercy.</p>\n<p>Lord have Mercy, Lord have mercy<br>On your servant Lord have Mercy.<br>God Almighty Just and faithful,<br>Lord have Mercy, Lord Have Mercy.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'kyrie'),
	(308, 'GLORY, ALL GLORY', 'pending', NULL, '<p><strong>Chorus:</strong><br>Glory, all glory, glory to God,<br>in the highest<br>and on earth peace to people of Goodwill,<br>glory to God in the highest,<br>and on Earth peace to people of Goodwill</p>\n<p><strong>1.</strong><br>We praise you we bless you we adore you we glorify you, we give you<br>thanks for your great glory, Lord God heavenly king O Lord Almighty Father.</p>\n<p><strong>2.</strong><br>Lord Jesus Christ only begotten son<br>Lord God lamb of God, son of the father<br>you take away the sins of the world,<br>have mercy, have mercy have mercy on us, have mercy have mercy have mercy on us</p>\n<p><strong>3.</strong><br>You take away the sins of the world,<br>receive our prayer, you are seated at the right hand, of the father<br>have mercy, have mercy have mercy on us, have mercy have mercy have mercy on us</p>\n<p><strong>4.</strong><br>For you alone are the Holy one, you alone are the Lord<br>you alone are the most high Jesus Christ<br>with the Holy Spirit,<br>in the glory of the father Amen, Amen, A---men</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'gloria'),
	(309, 'MARY\'S BOY CHILD', 'pending', NULL, '<p><strong>1.</strong><br>Long time ago in Bethlehem<br>So the Holy Bible says,<br>Mary\'s Boy Child Jesus Christ,<br>Was born on Christmas Day.</p>\n<p><strong>Chorus:</strong><br>Hark now hear the angels sing,<br>A new King born today,<br>And man will live for evermore,<br>Because of Christmas Day.</p>\n<p><strong>2.</strong><br>While shepherds watched their flocks by night,<br>They saw a bright new shining star,<br>They heard a choir sing,<br>The music seemed to come from afar.</p>\n<p><strong>3.</strong><br>Now Joseph and his wife Mary,<br>Came to Bethlehem that night,<br>She found no place to bear her child,<br>Not a single room was in sight.</p>\n<p><strong>4.</strong><br>By and by they found a little nook,<br>In a stable all forlorn,<br>And in a manger cold and dark,<br>Mary\'s little boy was born</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(310, 'CALYPSO CAROL', 'pending', NULL, '<p>See him alying on a bed of straw;<br>Draughty stable with an open door,<br>Mary cradling the babe she bore;<br>The prince of glory is his name.</p>\n<p><strong>Refrain:</strong><br>Oh, now carry me to Bethlehem<br>to see the Lord appear to men;<br>Just as poor as was the stable then,<br>The prince of glory when he came.</p>\n<p>Star of silver sweep across the skies,<br>show where Jesus in the manger lies.<br>Shepherds swiftly from your stupor rise<br>to see the Saviour of the world.</p>\n<p>Mine are riches from thy poverty,<br>From thine innocence, eternity;<br>Mine, forgiveness by thy death for me,<br>Child of sorrow for my joy.</p>\n<p>Angels, sing agan the song you sang,<br>bring God\'s glory to the heart of man;<br>Sing the Bethl\'hem\'s little baby can<br>be salvation to the soul.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(311, 'SILENT NIGHT', 'pending', NULL, '<p><strong>1.</strong><br>Silent night, holy night,<br>All is calm, all is bright,<br>’Round yon Virgin Mother and Child;<br>Holy infant, so tender and mild,<br>Sleep in heavenly peace,<br>Sleep in heavenly peace.</p>\n<p><strong>2.</strong><br>Silent night, holy night,<br>Shepherds quake at the sight,<br>Glories stream from heaven afar,<br>Heav’nly hosts sing alleluia.<br>Christ, the Saviour, is born,<br>Christ, the Saviour, is born.</p>\n<p><strong>3.</strong><br>Silent night, holy night,<br>Son of God, love\'s pure light,<br>Radiant beams from your holy face,<br>With the dawn of redeeming grace,<br>Jesus, Lord, at your birth,<br>Jesus, Lord, at your birth!</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(312, 'ONCE IN ROYAL DAVID\'S CITY', 'pending', NULL, '<p><strong>1.</strong><br>Once in royal David\'s city,<br>Stood a lowly cattle shed,<br>Where a mother laid her Baby,<br>In a manger for His bed.<br>Mary was that Mother mild,<br>Jesus Christ, her little Child.</p>\n<p><strong>2.</strong><br>He came down to earth from heaven,<br>Who is God and Lord of all;<br>And His shelter was a stable,<br>And His cradle was a stall,<br>With the poor and mean and lowly,<br>Lived on earth, our Saviour holy.</p>\n<p><strong>3.</strong><br>And our eyes at last shall see Him,<br>Through His own redeeming love,<br>For that Child so dear and gentle,<br>Is our Lord in Heaven above;<br>And He leads His children on,<br>To the place where He is gone.</p>\n<p><strong>4.</strong><br>Not in that poor lowly stable,<br>With the oxen standing by;<br>We shall see Him but in heaven,<br>Set at God\'s right hand on high.<br>When like star His children crowned,<br>All in white shall wait around.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(313, 'WHILE SHEPHERDS WATCHED', 'pending', NULL, '<p><strong>1.</strong><br>While shepherds watched their flocks by night,<br>All seated on the ground;<br>The angel of the Lord came down,<br>And glory shone around,<br>And glory shone around.</p>\n<p><strong>2.</strong><br>“Fear not!” said he – for mighty dread<br>Had seized their troubled mind, -<br>“Glad tidings of great joy I bring,<br>To you and all mankind,<br>To you and all mankind.”</p>\n<p><strong>3.</strong><br>To you, in David\'s town, this day,<br>Is born of David\'s line<br>The Saviour, who is Christ the Lord;<br>And this shall be the sign,<br>And this shall be the sign.</p>\n<p><strong>4.</strong><br>“The heavenly Babe you there shall find<br>To human view displayed,<br>All meanly wrapped in swathing bands,<br>And in a manger laid,<br>And in a manger laid."</p>\n<p><strong>5.</strong><br>Thus spoke the seraph – and forthwith<br>Appeared a shining throng<br>Of angels, praising God, who thus<br>Addressed their joyful song,<br>Addressed their joyful song.</p>\n<p><strong>6.</strong><br>“All glory be to God on high!<br>And on the earth be peace!<br>Good-will hence forth from heaven to men<br>Begin and never cease,<br>Begin and never cease!"</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(314, 'JOY TO THE WORLD', 'pending', NULL, '<p><strong>1.</strong><br>Joy to the world! the Lord is come;<br>Let earth receive her King.<br>Let ev’ry heart prepare Him room,<br>And heav\'n and nature sing,<br>And heav\'n and nature sing,<br>And heav\'n and heav\'n and nature sing.</p>\n<p><strong>2.</strong><br>Joy to the world! the Saviour reigns;<br>Let men their songs employ.<br>While fields and floods, rocks, hills and plains,<br>Repeat the sounding joy,<br>Repeat the sounding joy,<br>Repeat, repeat the sounding joy.</p>\n<p><strong>3.</strong><br>He rules the world, with truth and grace,<br>And makes the nations prove,<br>The glories of his righteousness,<br>And wonders of his love,<br>And wonders of his love,<br>And wonders, and wonders of his love.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(315, 'FELIZ NAVIDAD', 'pending', NULL, '<p>Feliz Navidad<br>Feliz Navidad<br>Feliz Navidad<br>Prospero Ano y Felicidad.</p>\n<p>Feliz Navidad<br>Feliz Navidad<br>Feliz Navidad<br>Prospero Ano y Felicidad.</p>\n<p>I wanna wish you a Merry Christmas<br>I wanna wish you a Merry Christmas<br>I wanna wish you a Merry Christmas<br>From the bottom of my heart.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(316, 'ANYI ABIAWO CHINEKE', 'pending', NULL, '<p><strong>CHORUS:</strong><br>Anyia biawo Chineke anyia biawo Nna Anyia bia w’I kele gi gozia nyi Chukwu</p>\n<p><strong>Verse 1:</strong><br>Bianu umu Chineke Kanyi kele mu Nna bianu ndi kwere na Okpara ya Jesu</p>\n<p><strong>Verse 2:</strong><br>Too nu Chineke onye kere uwa nile toonu Chineke Onye ne chekwa bay a</p>\n<p><strong>Verse 3:</strong><br>Chukwu ebuka Chukwu ebuka ngozi ya kariria kari nebanyi no keleya keleya kelenu Chukwu</p>\n<p><strong>Verse 4:</strong><br>Gibu Nna nweke I anyi motu</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(317, 'ONYE NWANYI MEE EBERE', 'pending', NULL, '<p>Onye nwanyi mee ebere do Onyenwanyi<br>Onye nwanyi mee ebere do Onyenwanyi<br>Biko mee, mee, meer’anyi ebere<br>Biko mee, mee, meer’anyi ebere do.</p>\n<p>Kristi mee ebere do Kristi<br>Kristi mee ebere do Kristi<br>Biko mee, mee, meer’anyi ebere<br>Biko mee, mee, meer’anyi ebere do.</p>\n<p>Onye nwanyi mee ebere do Onyenwanyi<br>Onye nwanyi mee ebere do Onyenwanyi<br>Biko mee, mee, meer’anyi ebere<br>Biko mee, mee, meer’anyi ebere do.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'kyrie'),
	(318, 'OTITO DIRI CHINEKE', 'pending', NULL, '<p>Otito diri chineke, n’elu ka sie lu, udo diri ndi mmadu, ndi ihe ha na so chukwu.</p>\n<p><strong>Verse 1:</strong><br>Anyi’e too gi anyi’ekwuputa oruoma gi, anyi’e sekpuoro gi, anyi’e doo gi e bube.<br>Anyi’e kele gi nihi nukwu ebube gi, Osebuluwa Chukwu Otitio diri Chineke</p>\n<p><strong>Verse 2:</strong><br>Eze eluigwe Chukwu Nna ji ike niile, Onyeweanyi Jesu Christi, S’out nwa chineke muru.<br>Dinwenu anyi bu Chukwu Nwaturu nke Chineke,Nwa nke Nna otitio diri chineke.</p>\n<p><strong>Verse 3:</strong><br>Onye ne kpochapu njo, njo nk,u wa, mee ra anyi ebere, mee ra anyi ebere.<br>Onye ne kpochapu njo, njo nk’u wa, nara aririo anyi Otito diri chineke</p>\n<p><strong>Verse 4:</strong><br>Onye na no n’aka nri Nna, meeranyi ebere, nihi na so gi di aso, so gi bu dinwenu<br>So ngi bu Jesu Christi, kacha di elu nyere muo nso n’ebube Chukwu Nna, Otito diri Chineke</p>\n<p>Amen.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'gloria'),
	(319, 'MUN ZO GARE KA', 'pending', NULL, '<p>Mun zo Ya Ubangiji mun zo mun zo gare Ka Ubangiji mun zo Albarkace mu Ubangiji mun zo Ya Allah mun zo Sacramenti mai dadi Mun zo Ya Ubangiji mun zo mun zo gare Ka Ubangiji mun zo Albarkace mu Ubangiji mun zo Ya Allah mun zo</p>\n<p><strong>Verse 1:</strong><br>Sacrament mai dadi mun zo Sacramenti mai dadi mun zo Sacramenti mai dadi zuwa bikin mai Tsarki O ya Ubangiji Allah na mun zo a baza din Ka mun zo kusa zuwa Eucharista mai Tsarki mun zo Ka Albarkace mu Yesu mun zo jikin da jinin Ka zamu karbi Yesu mai dadi Ka Albarkace yaya Ka Yesu mai dadi munzo O sacramenti mai dadi mun zo</p>\n<p><strong>Verse 2:</strong><br>Ni ne gurasa mai rai wanda ya zo wuri na bazei ji nyunwa ba wanda y aba da gaskiya bazei ji kishi ba ba mai zuwa gare ni sai ta wurin uba na</p>\n<p><strong>Verse 3:</strong><br>Sai ka ci daga jikin dan mutum kuma ka sha jinin sa O baza ka samu rai a jikin k aba kuma ka sha jinin sa O baza ka samu rai a jikin k aba</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(320, 'J’AVWARE JIR OGHENE', 'pending', NULL, '<p>I hwo r’akpo n’e jobi Jiro Oghene vwe jiro Erhime kpar’o de r’Oghene kpenu</p>\n<p>Oghene me vwo ro ro gan gan vwo k’a vware akpo okpo kpo vwo vwi mue me avware gho vwo a vware</p>\n<p>Kpevw Oghene Ji rOghene kpevw Olori Jiro Oghene Kpevw’O si vwi Jir’Oghene Fikidie Oghene fejiro</p>\n<p>Ose si vwi oga a vware vwo ma fh’ughwu r’I Jesu Avware kpe vwo vwe Oro vwo hwo Vwo rhu no Ose ro tan arho avware un kpotor vwo ma rhughwu ri Jesu Avware kpe vwo vwe Oro vwo hwo  vwo fe go J’aware Jiro Oghene vwe jiro Erhime kparo dero Oghene kpenu O! Imonime</p>\n<p>Kparo dero oghene kpenu o!!</p>\n<p>KpewO-ghene , JirOghene  akpevwe kugbe ji ro diak Oghene Urin rink u gbe oghodiak Olori vwe jiro  O sivwi JirO’ghene Fikidie Oghene fejiro</p>\n<p>Emeka she ro dju vwu sui ne u rin rin k’Oghene ri fue vun r’o ye b’o dju vwu sui neji ro k’Oghene Jen I hwo r’akpo n’eje sui ne akpe vwe kOghene fikidie arho rib r vwede ko ihwo eje</p>\n<p>Urin rin dia kp Oghene be de<br>J’a vware ji rOghene Urin rin dia kOghene be de<br>J’a vware ji rOghene Urin rin dia kOghene be de Urin rin dia kOghene be de<br>Ogho dia k’oghene be de Urin rin dia kOghene be de</p>\n<p>Ejiro kugbe akpe vwe dia koghene nOse ri ribe de Urrin rin dia kOghene<br>E bru ba dia kOghene be de Urin rin dia kOghene be de<br>J’a vwa re ejiro Oghene Urin rin dia kOghene be de</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(321, 'LOVE GOES ON', 'pending', NULL, '<p>Love is patient, love is kind,<br>Never ending, never ending<br>Slow to anger. Rich in mercy<br>Love goes on beyond all time</p>\n<p>Love is faithful, love is true<br>Ever joyful and forgiving<br>Love endures when life is over<br>Love is old and love is new</p>\n<p>Love alone has shaped our soul<br>And our hearts are always restless<br>Until love becomes our purpose<br>New creation to unfold</p>\n<p>Love our journey, love our goals<br>Though our faith may move mountains<br>Love alone can heal the broken<br>Only love will make us whole</p>\n<p>Live, our saviour’s one command:<br>Love the way that I have loved you<br>With a towel and a basin<br>Washing feet with the servant’s hands</p>\n<p>There are three things that remain<br>When all other things have perished<br>Only faith, hope, love enduring<br>And the greatest gift is love</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(322, 'OJOCHENEMI/OJOCHEGBE', 'pending', NULL, '<p><strong>REFRAIN:</strong><br>Ojochenemi o if God is for us who can be against us<br>Ojochegbe God has done great<br>I will shout for joy Praise His name my awesome God You have done great things</p>\n<p><strong>Verse 1:</strong><br>I trust in God wherever I may be upon the land or on the rolling sea for come what may from day to day Omnipotent God He cares for me</p>\n<p><strong>Verse 2:</strong><br>He makes the rose an object of His cares He guides the eagle through the pathless air and surely He remembers me Omnipotent God He cares for me</p>\n<p><strong>Verse 3.:</strong><br>I trust in God for in the lion’s den on battle field or in the prison Pen through praise and blame through flood and flame Omnipotent God He cares for me</p>\n<p><strong>Verse 4:</strong><br>The valley may be dark the shadows deep but still the Shepherd guards his lonely sheep and through the gloom He’ll lead me home Omnipotent God He cares for me</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(323, 'SOM YA MME', 'pending', NULL, '<p>Som ya mme ya mme,</p><p>Som ya mme ya mme x 2</p><p><br></p><p>Verse1&amp;2, aze biarra ibe ye ibe obu o akunta</p><p>Aze biarra ibe ye ibe obu o akunta.</p><p><br></p><p>3&amp;4, se papa a se boniya ibe obu o akunta.</p><p>See papa a se boniya ibe obu o akunta</p>', '2026-07-24 13:53:06', '2026-07-24 13:59:15', NULL),
	(324, 'YES, I SHALL ARISE', 'pending', NULL, '<p><strong>CHORUS:</strong><br>Yes, I shall arise and return to my father.</p>\n<p><strong>VERSE 1:</strong><br>To you, O Lord, I lift up my soul;<br>In you, O my God, I place all my trust.</p>\n<p><strong>VERSE 2:</strong><br>Look down on me, have mercy, O Lord;<br>Forgive me my sins, behold all my grief.</p>\n<p><strong>VERSE 3:</strong><br>My heart and soul shall yearn for your face;<br>Be gracious to me and answer my plea.</p>\n<p><strong>VERSE 4:</strong><br>Do not withhold your goodness from me;<br>O Lord, may your love be deep in my soul.</p>\n<p><strong>VERSE 5:</strong><br>To you I pray, have pity on me;<br>My God, I have sinned against your great love.</p>\n<p><strong>VERSE 6:</strong><br>Mercy I cry, O Lord, wash me clean;<br>And whiter than snow my spirit shall be.</p>\n<p><strong>VERSE 7:</strong><br>Give me again the joy of your help;<br>Now open my lips, your praise I will sing.</p>\n<p><strong>VERSE 8:</strong><br>Happy is he forgiven by God;<br>His sins blotted out, his guilt is no more.</p>\n<p><strong>VERSE 9:</strong><br>You are my joy, my refuge and strength;<br>Let all upright hearts give praise to the Lord.</p>\n<p><strong>VERSE 10:</strong><br>My soul will sing, my heart will rejoice;<br>The blessing of the God will fill all my days.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(325, 'TAKE OUR BREAD', 'pending', NULL, '<p><strong>CHORUS:</strong><br>Take our bread, we ask you,<br>Take our hearts, we love you;<br>Take our lives, O Father, we are yours,<br>we are yours.</p>\n<p><strong>VERSE 1:</strong><br>Yours as we stand at the table you set;<br>Yours as we eat the bread our hearts can\'t forget,<br>We are a sign of your life with us yet,<br>We are yours, we are yours.</p>\n<p><strong>VERSE 2:</strong><br>Your holy people standing washed in your blood,<br>Spirit filled yet hungry we await your food,<br>We are poor, but we\'ve brought ourselves —<br>the best we could;<br>We are yours, we are yours.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(326, 'THE FUTURE LIES BEFORE ME', 'pending', NULL, '<p><strong>VERSE 1:</strong><br>Oh! I often sit and ponder,<br>When the sun is sinking low,<br>Where shall yonder future find me<br>Does but God in Heaven know,<br>Shall I be among the living,<br>Shall I mingle with the free,<br>Wheresoe\'er my path be leading,<br>Saviour, keep my heart with Thee.</p>\n<p><strong>CHORUS:</strong><br>Oh! the future lies before me,<br>And I know not where I\'ll be,<br>But where\'er my path be leading,<br>Saviour, keep my heart with Thee.</p>\n<p><strong>VERSE 2:</strong><br>Shall I be at work with Jesus,<br>Whilst He Leads me by the hand,<br>And to those around be saying,<br>Come and join this happy band.<br>Come for all things now are ready<br>Come His faithful followers be,<br>Oh where\'er my path be leading,<br>Saviour, keep my heart with Thee.</p>\n<p><strong>VERSE 3:</strong><br>But perhaps my work for Jesus,<br>Soon in future may be done,<br>All my earthly trials ended,<br>And my crown in heaven won,<br>Then forever with the ransom\'d<br>Thro’ eternity l’d be<br>Chanting hymns to Him who bought me,<br>With His Blood shed on the Tree</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(327, 'IT IS WELL WITH MY SOUL', 'pending', NULL, '<p><strong>VERSE 1:</strong><br>When peace, like a river,<br>attendeth my way,<br>When sorrows, like sea billows roll,<br>Whatever my lot, thou hast taught me to say:<br>"It is well, it is well, with my soul."</p>\n<p><strong>CHORUS:</strong><br>It is well, it is well,<br>With my soul, with my soul,<br>It is well, it is well, with my soul.</p>\n<p><strong>VERSE 2:</strong><br>Though Satan should buffet,<br>Though trials should come,<br>Let this blest assurance control;<br>That Christ has regarded my helpless estate,<br>and hath shed his own blood for my soul.</p>\n<p><strong>VERSE 3:</strong><br>My sin, O the bliss, of this glorious tho\'t,<br>My sin, not in part but the whole<br>Is nailed to the cross, and I bear it no more.<br>Praise the Lord, praise the Lord, O my soul!</p>\n<p><strong>VERSE 4:</strong><br>And Lord haste the day<br>when my faith shall be sight,<br>The clouds be rolled back as a scroll;<br>Th…</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(328, 'THROUGH THE LOVE OF CHRIST', 'pending', NULL, '<p>Through the love of God our Saviour,<br>all will be well.<br>Free and changeless is his favour,<br>all, all is well.<br>Precious is the blood that healed us,<br>perfect is the grace that sealed us,<br>strong the hand stretched forth to shield us,<br>all must be well.</p>\n<p><strong>2.</strong><br>Though we pass through tribulation,<br>all will be well.<br>Ours is such a full salvation,<br>all, all is well.<br>Happy, still in God confiding,<br>fruitful, if in Christ abiding,<br>holy, through the Spirit’s guiding,<br>all must be well.</p>\n<p><strong>3.</strong><br>We expect a bright tomorrow,<br>all will be well.<br>Faith can sing through days of sorrow,<br>\'All, all is well.\'<br>On our Father’s love relying,<br>Jesus every need supplying,<br>in our living, in our dying,<br>all must be well.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(329, 'PEACE BE STILL', 'pending', NULL, '<p><strong>1.</strong><br>Master, the tempest is raging!<br>The billows are tossing high!<br>The sky is o’ershadowed with blackness.<br>No shelter or help is nigh.<br>Carest thou not that we perish?<br>How canst thou lie asleep<br>When each moment so madly is threat’ning<br>A grave in the angry deep?</p>\n<p><strong>[Chorus]:</strong><br>The winds and the waves shall obey thy will:<br>Peace, be still.<br>Whether the wrath of the storm-tossed sea<br>Or demons or men or whatever it be,<br>No waters can swallow the ship where lies<br>The Master of ocean and earth and skies.<br>They all shall sweetly obey thy will:<br>Peace, be still; peace, be still.<br>They all shall sweetly obey thy will:<br>Peace, peace, be still.</p>\n<p><strong>2.</strong><br>Master, with anguish of spirit<br>I bow in my grief today.<br>The depths of my sad heart are troubled.<br>Oh, waken and save, I</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(330, 'GOD BE WITH YOU', 'pending', NULL, '<p><strong>VERSE 1:</strong><br>God be with you till we meet again!<br>By His counsels guide, uphold you;<br>With His sheep securely fold you;<br>God be with you till we meet again!</p>\n<p><strong>CHORUS:</strong><br>Till we meet!... Till meet!<br>Till we meet at Jesus feet...<br>Till we meet!... Till we meet!...<br>God be with you till we meet again!</p>\n<p><strong>VERSE 2:</strong><br>God be with you till we meet again!<br>’Neath His wings securely hide you;<br>Daily manna still provide you;<br>God be with you till we meet again!</p>\n<p><strong>VERSE 3:</strong><br>God be with you till we meet again!<br>When life\'s perils thick confound you;<br>Put his loving arms around you;<br>God be with you till we meet again!</p>\n<p><strong>VERSE 4:</strong><br>God be with you till we meet again!<br>Keep love\'s banner floating o\'er you;<br>Smite death\'s threatening wave before you;<br>God be with you till we meet again!</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(331, 'EVERYDAY GOD', 'pending', NULL, '<p>Earth\'s creator, Everyday God,<br>Loving Maker, O Jesus,<br>You who shaped us, O Spirit,<br>Recreate us, Come, be with us.</p>\n<p>In your presence, Everyday God,<br>We are gathered, O Jesus,<br>You have called us, O Spirit,<br>To restore us, Come, be with us.</p>\n<p>Life of all lives, Everyday God,<br>Love of all loves, O Jesus,<br>Hope of all hopes, O Spirit,<br>Light of all lights, Come, be with us.</p>\n<p>In our resting, Everyday God,<br>In our rising, O Jesus,<br>In our hoping, O Spirit,<br>In our waiting, Come, be with us.</p>\n<p>In our dreaming, Everyday God,<br>In our daring, O Jesus,<br>In our searching, O Spirit,<br>In our sharing, Come, be with us.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(332, 'COME TO ME ALL YOU THAT LABOR', 'pending', NULL, '<p><strong>1.</strong><br>Come to me all you that labour and are heavy burdened, come to me all you that labour, and i will give you rest for sure</p>\n<p><strong>CHORUS:</strong><br>Come to me now come to me now come to me now and I\'ill give you rest</p>\n<p><strong>2.</strong><br>I\'m the way the truth and the life Jesus said to him no one comes to the Father but through me, come to me now I say</p>\n<p><strong>3.</strong><br>All we like sheep have gone astray, we have gone away. God has laid on him all our sins, yet he calls us all to come</p>\n<p><strong>4.</strong><br>Day to day you toil for daily bread, and nothing to show, know that man lives not by bread alone , the word of God is the key</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(333, 'THE FIRST NOEL', 'pending', NULL, '<p><strong>VERSE 1:</strong><br>The first Noel, the angel did say,<br>Was to certain poor shepherds,<br>In fields as they lay,<br>In fields where they lay keeping their sheep,<br>On a cold winter\'s night,<br>That was so deep.</p>\n<p><strong>CHORUS:</strong><br>Noel, Noel, Noel, Noel,<br>Born is the King of Israel.</p>\n<p><strong>VERSE 2:</strong><br>They look\'d above and there saw a star,<br>That shone in the east beyond them afar,<br>And which to earth did give great light,<br>And so it continued by day and night.</p>\n<p><strong>VERSE 3:</strong><br>And by the light of that same Star,<br>Three wise men came from country far;<br>To seek for a King was their intent,<br>And to follow the star wherever it went.</p>\n<p><strong>VERSE 4:</strong><br>This star drew near to the north-west,<br>At length over Bethlehem seemed to rest,<br>And there it stayed by night and by day,<br>Right over the place where Jesus lay.</p>\n<p><strong>VERSE 5:</strong><br>Then entered in those wise men three<br>Most reverently with bended knee;<br>And offered there in His presence,<br>Both gold and myrrh with frankincense.</p>\n<p><strong>VERSE 6:</strong><br>Then let us all with one accord,<br>Sing praises to our heavenly Lord,<br>That made both heaven and earth of nought,<br>And with His blood mankind has bought.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(334, 'I GO ENTER HIS COURT', 'pending', NULL, '<p><strong>VERSE 1:</strong><br>I go enter his court with praise,<br>I go shout Alleluia,<br>Me I go enter his court with praise<br>Me I go shout Alleluia.</p>\n<p><strong>Chorus:</strong><br>O yeah my savior, o yeah my good Lord. X2</p>\n<p><strong>VERSE 2:</strong><br>I go enter his court with song,<br>I go shout Alleluia,<br>Me I go enter his court with song,<br>Me I go shout Alleluia</p>\n<p><strong>VERSE 3:</strong><br>I go enter his court with dance,<br>I go shout Alleluia,<br>Me I go enter his court with dance<br>Me I go shout Alleluia</p>\n<p><strong>VERSE 4:</strong><br>I go enter his court with thanks<br>I go shout Alleluia,<br>Me I go enter his court with thanks<br>Me I go shout Alleluia</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(335, 'WE HAVE COME, O LORD', 'pending', NULL, '<p><strong>CHORUS:</strong><br>We have come oh Lord to worship you,<br>we have come oh Lord to praise your holy name<br>We have come to give you thanks<br>We have come to honour you<br>Come and dwell with us (x2)</p>\n<p><strong>Verse 1:</strong><br>This is the day the Lord has made,<br>Let us rejoice and be glad in it.<br>This is the time to commune with the Lord,<br>Ah! Let us make the best of it</p>\n<p><strong>Verse 2:</strong><br>The Lord is kind and full of compassion,<br>He knows how very weak we are.<br>He is ready to forgive all our sins,<br>Ah let us make the best of it.</p>\n<p><strong>Verse 3:</strong><br>The Lord knows our hearts, he knows our needs,<br>He hears each time we call upon him<br>He is ready to answer our plea<br>ah let us make the best of it.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(336, 'DAUKAKA GA ALLAH (HAUSA)', 'pending', NULL, '<p><strong>Bass:</strong> Daukaka ga Allah cikin sama niya</p>\n<p><strong>CHORUS:</strong><br>Daukaka ga Allah,<br>Daukaka ga Allah<br>Daukaka ga Allah<br>Cikin sama niya</p>\n<p><strong>VERSE 1:</strong><br>Aduniya Kuma salama<br>Ga mutane na nufi mai kyau<br>Muna Muna yabonka, Muna albarka ceka</p>\n<p><strong>VERSE 2:</strong><br>Muna yi maka sujada<br>Muna muna daukaka ka<br>Munayi maka godiya,<br>Saboda dara jarka mai girma</p>\n<p><strong>VERSE 3:</strong><br>Ya ubangiji Allah<br>Sarkin Sarkin Sama<br>Allah Uba Mai iko duka<br>Allah Uba Mai iko duka</p>\n<p><strong>VERSE 4:</strong><br>Ya Ubangiji Yesu almasihu<br>Da maka da ici<br>Ya Ubangiji Allah<br>Dan tunkiya na Allah Dan Uba.</p>\n<p><strong>VERSE 5:</strong><br>Kai da ke ka-war da zunu-banduniya<br>kayi mana jinkai<br>kaida kekawa da zunuban duniya<br>ka ji addu \'awar-mu</p>\n<p><strong>VERSE 6:</strong><br>Kai da ka ke zaune<br>A hannun-dama na Uba,<br>Ka yi mana jinkai<br>kayi Mana jinkai</p>\n<p><strong>VERSE 7:</strong><br>Domin kai ka-dai Mai Tsarki ne,<br>Kai ka dai Ubangiji ne<br>kai ka dai madaukaki ne<br>Kai ka dai madaukaki ne</p>\n<p><strong>VERSE 8:</strong><br>Ya Yesu almasihu<br>tare da ruhu mai Tsarki,<br>Cikin dara ja Allah Uba<br>Amin Amin Amin</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'gloria'),
	(337, 'MIMO L\'OLUWA', 'pending', NULL, '<p>Mimo! Mimo! mimo l\'oluwa, Olorun awon omo ogun, Olorun awon omo ogun<br>Mimo! Mimo! mimo l\'oluwa, Olorun awon omo ogun, Olorun awon omo-ogun oh!</p>\n<p>Orun oun aye kun fun ogo re ye o, hosanna lo ke orun,<br>Hosa----nna, hosa----nna, hosa----nna, hosanna lo ke orun</p>\n<p>Ibukun ni fe ni t\'onbo wa l\'oroko Oluwa, hosanna loke orun<br>Hosa----nna, hosa----nna, hosa----nna, hosanna lo ke orun. (X2)</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'sanctus'),
	(338, 'REMEMBER ME', 'pending', NULL, '<p>In the night in which our Saviour was betray\'d,<br>He broke the bread and to His friends, He said:<br>"Take and eat, this is my body giv\'n for you;<br>take and drink, this blood of mine is shed for you.<br>Do this always to remember me<br>Remember me"</p>\n<p>In the night in which our Savior was denied,<br>He bowed His head, and to the Father cried:<br>"If it be your will, let this cup pass from me;<br>If it be your will, spare me this agony.<br>In my darkest hour will you remember me ?<br>Remember me."</p>\n<p>In the night in which my deepest doubt are known,<br>You come to me and I am not alone.<br>When I taste your blood and body giv\'n for me,<br>When I hear your prayer in dark Gethsemane,<br>Then I know you will remember me<br>Remember me.<br>O Lord, remember me. Remember me.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(339, 'MA NDI NA ELE ANYA CHINEKE', 'pending', NULL, '<p>Ma Ndi na ele Anya Chineke aga agbanwe Ike ha (2x)<br>Aga agbanwe Ike ha<br>Aga agbanwe Ike ha<br>Ike (4x)<br>Ike ha (7x)</p>\n<p>Ma ndi na ele Anya Chineke na ele Anya Chineke (2x)<br>Ma ndi na ele Anya Chineke ga agbanwe Ike ha</p>\n<p>Ha ga efego elu (3x)<br>Na nku dika ugo<br>Fego fego fego elu<br>Fego fego fego elu<br>Fego fego fego elu na nku dika ugo</p>\n<p>Ma ndi na ele Anya Chineke ga agbanwe Ike ha ndi na ele Anya Chineke ga agbanwe Ike ha</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(340, 'KABIYESI O', 'pending', NULL, '<p>Kabiyesi o Hossanna o eyin Jesu Christi o ba ai ku</p>\n<p>Egbega eyin Jesu o eyin Jesu Kristi oba ai ku</p>\n<p>Waka yin Jesu Ara mi o oba mimo Jesu oba ai ri</p>\n<p>Wa Juba Jesu oluwa o olodumare oba ai ku</p>\n<p>Oba iyi Jije o oluwa o wa gb ope was gbai yin awa omore</p>\n<p>Angeli l\'orun ebawa yin eyin Jesu Kristi o na ai kun</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(341, 'FATHER ACCEPT THE GIFTS WE OFFER', 'pending', NULL, '<p><strong>1.</strong><br>Father accept the gifts we offer,<br>Have mercy and hear our prayers<br>May Almighty God bless our offering,<br>Have mercy and hear our prayers</p>\n<p><strong>Chorus:</strong><br>May the Holy Spirit descend on the Altar<br>Sanctify our sacrifice<br>May it be acceptable, to the Father through the Son</p>\n<p><strong>2.</strong><br>Jesu we bring our gifts before you,<br>Have mercy and hear our prayers<br>Present them to the Father that His will may be done<br>Have mercy and hear our prayers</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(342, 'O COME, THOU WISDOM WHOSE DECREE', 'pending', NULL, '<p><strong>VERSE 1:</strong><br>O come, thou wisdom whose decree,<br>Doth govern all things peacefully,<br>The way of prudence here below,<br>And life hereafter deign to show.</p>\n<p><strong>CHORUS:</strong><br>Rejoice, rejoice Emmanuel,<br>Is born to save thee, Israel.</p>\n<p><strong>VERSE 2:</strong><br>O come, thou everlasting Lord,<br>Who once by Israel\'s host adored,<br>Thy dread commandment madest known,<br>In majesty of glory show.</p>\n<p><strong>VERSE 3:</strong><br>O Rod of Jesse, mystic bough,<br>From Satan\'s cruel snares do thou,<br>From death\'s grim dungeon, we implore<br>And hell\'s abyss thine own restore.</p>\n<p><strong>VERSE 4:</strong><br>O come, thou Key of David\'s store,<br>Unlock the heavenly gates once more;<br>Safe journey to thy courts bestow,<br>And shut the way that leads below.</p>\n<p><strong>VERSE 5:</strong><br>O come, thou Daystar seen on high,<br>With healing for our hearts draw nigh;<br>Do thou the mists of night dispel,<br>And death\'s foreboding darkness quell.</p>\n<p><strong>VERSE 6:</strong><br>O come, of Gentile hearts the King,<br>A world that needs thee ransoming,<br>And save thy servants, who confess<br>With humbled hearts their faithlessness.</p>\n<p><strong>VERSE 7:</strong><br>O come, o come, Emmanuel,<br>Redeem thy captive Israel,<br>That doth in exile homeless mourn,<br>Until her Saviour Christ be born.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(343, 'WONDERFUL MERCIFUL SAVIOR', 'pending', NULL, '<p><strong>Verse1:</strong><br>Wonderful, merciful Savior<br>Precious Redeemer and Friend<br>Who would have thought that a Lamb<br>Could rescue the souls of men<br>Oh, You rescue the souls of men</p>\n<p><strong>Chorus:</strong><br>You are the One that we praise<br>You are the One we adore<br>You give the healing and grace<br>Our hearts always hunger for<br>Oh, our hearts always hunger for</p>\n<p><strong>Verse2:</strong><br>Counselor, Comforter, Keeper<br>Spirit we long to embrace<br>You offer hope when our hearts have<br>Hopelessly lost our way<br>Oh, we\'ve hopelessly lost the way</p>\n<p><strong>Verse3:</strong><br>Almighty, infinite Father<br>Faithfully loving Your own<br>Here in our weakness You find us<br>Falling before Your throne<br>Oh, we\'re falling before Your throne</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(344, 'IN THE HOLLOW OF GOD\'S HAND', 'pending', NULL, '<p>With my Saviour ever near to guide me,<br>I am safe, whatever may betide me;<br>From the storm and tempest He will hide me<br>In the hollow of His hand!</p>\n<p>In the hollow of His hand! In the hollow of His hand!<br>I am safe, whatever may betide me, In the hollow of His hand!</p>\n<p>In His arms of love He doth enfold me;<br>Words of peace His voice Divine hath told me;<br>I am safe, for God Himself doth hold me<br>In the hollow of His hand!</p>\n<p>He will guard my soul, and leave me never;<br>From His love no power on earth shall sever;<br>And I know He\'ll keep me now and ever<br>In the hollow of His hand!</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(345, 'OUR OFFER', 'pending', NULL, '<p><strong>*Chorus*</strong><br>Take this our dear father Lord<br>Receive our gift and consecrate us<br>Take this, offering<br>Take this, our gift<br>Take and bless us in return</p>\n<p><strong>*Verse 1*</strong><br>We sing our song of Thanksgiving,<br>It\'s a joyful sacrifice<br>It draws our heart closer to you<br>Our voices we bring<br>Take and bless us in return</p>\n<p><strong>*Verse 2*</strong><br>The gift you gave we bring with us<br>The work of human hands<br>Will turn into the body of Christ<br>Our voices we bring<br>Take and bless us in return</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(346, 'HOW EXCELLENT IS THY LOVING-KINDNESS', 'pending', NULL, '<p>How excellent (2x) is thy loving-kindness<br>Is thy loving-kindness<br>O God (2x)</p>\n<p>Therefore the children of men {2x}<br>Put their trust, they put their trust<br>Under the shadow of thy wings.</p>\n<p>They shall be abundantly satisfied {3x})<br>With the fullness of thine house) 2x</p>\n<p>And thou shall make them drink of the rivers of thy pleasure} 2x<br>O continuous thy loving-kindness<br>And unto them that prosper, unto them that prosper<br>And thou shall make them drink of the rivers of thy pleasure</p>\n<p>How excellent (2x) is thy loving-kindness<br>Is thy loving-kindness<br>O God<br>How excellent {3x}<br>Is thy loving-kindness<br>O {3x} O God.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(347, 'O HOLY NIGHT', 'pending', NULL, '<p>O holy night! the stars are brightly shining;<br>It is the night of the dear Savior’s birth.<br>Long lay the world in sin and error pining,<br>Till He appeared and the soul felt its worth.<br>A thrill of hope- the weary world rejoices,<br>For yonder breaks a new and glorious morn!<br>Fall on your knees! O hear the angel voices!<br>O night divine, O night when Christ was born!<br>O night, O holy night, O night divine!</p>\n<p><strong>2.</strong> Led by the light of faith serenely beaming,<br>With glowing hearts by His cradle we stand.<br>So led by light of a star sweetly gleaming,<br>Here came the Wise Men from Orient land.<br>The King of kings lay thus in lowly manger,<br>In all our trials born to be our Friend.<br>He knows our need— to our weakness is no stranger.<br>Behold your King, before Him lowly bend!<br>Behold your King, before Him lowly bend!</p>\n<p><strong>3.</strong> Truly He taught us to love one another;<br>His law is love and His gospel is peace.<br>Chains shall He break, for the slave is our brother,<br>And in His name all oppression shall cease.<br>Sweet hymns of joy in grateful chorus raise we;<br>Let all within us praise His holy name.<br>Christ is the Lord! O praise His name forever!<br>His pow’r and glory evermore proclaim!<br>His pow’r and glory evermore proclaim!</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(348, 'THOU CROWNEST THE YEAR', 'pending', NULL, '<p>Thou crownest the year, thou crownest the year<br>and thy paths grow fatness.<br>They drop upon the dwellings of the wilderness<br>They drop upon the dwellings of the wilderness<br>And the little hills rejoice, the little hills rejoice<br>rejoice on every side, rejoice on every side.<br>And the little hills rejoice, the little hills rejoice<br>rejoice on every side, rejoice on every side.</p>\n<p>The pastures are clothed, are clothed with flocks<br>the valleys, the valleys are thick with corn<br>They laugh and shout for joy<br>They laugh and shout for joy<br>They laugh and shout for joy<br>They laugh and shout for joy<br>They shout for joy.......<br>Rejoice, rejoice<br>on every side rejoice.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(349, 'BEHOLD AMONG MEN', 'pending', NULL, '<p><strong>CHORUS:</strong><br>Behold among men the dwelling place of God, they shall be His people, and He shall be their Lord and God</p>\n<p><strong>Verse 1:</strong><br>People called by God through the word of the prophet, people brought together in the house of the Lord, people who attend to their Lord, the church of Christ the Lord!</p>\n<p><strong>Verse 2:</strong><br>Temple built by God by the martyrs and apostles; Holy temple built upon Christ the corner stone. Holy dwelling place f our God, the church of Christ the Lord!</p>\n<p><strong>Verse 3:</strong><br>People who are born in the waters of the spirit people who are marked by the seal of the spirit people in the spirit made one, the church of Christ the Lord!</p>\n<p><strong>Verse 4:</strong><br>People who are grafted in Jesus the Vine; branches bearing fruit in the grace of the Lord; branches rooted in His great love, the church of Christ the Lord!</p>\n<p><strong>Verse 5:</strong><br>People nourished now by the body of the Lord; people who sit down to the new paschal supper; who shall pass from death into life; the church of Christ the Lord!</p>\n<p><strong>Verse 6:</strong><br>People justified by the grace of the spirit; people who are heirs of an everlasting life; people now enlightened by Christ, the church of Christ the Lord!</p>\n<p><strong>Verse 7:</strong><br>People called in faith to be quickened by his life; people called by God from the darkness into light; Holy people called to be royal, the church of Christ the Lord!</p>\n<p><strong>Verse 8:</strong><br>People whom the Lord has acquired for His praise; people who put trust in the Lord Jesus Christ; people called by God for His own, the church of Christ the Lord!</p>\n<p><strong>Verse 9:</strong><br>People who proclaim the great glory of the Father; by the Lord Jesus Christ his only son; and in the spirit give praise, the church of Christ the Lord!</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(350, 'COME, SOUND HIS PRAISE ABROAD (PSALM 95)', 'pending', NULL, '<p><strong>VERSE 1:</strong><br>Come sound His praise abroad<br>And hymns of glory sing:<br>Jesus is the sovereign Lord,<br>The universal King.</p>\n<p><strong>CHORUS:</strong><br>Praise Ye the Lord, Alleluia!<br>Praise Ye the Lord Alleluia!<br>Alleluia, Alleluia, Alleluia!<br>Praise Ye the Lord.</p>\n<p><strong>VERSE 2:</strong><br>He formed the deeps unknown;<br>He gave the seas their bounds:<br>The watery worlds are all His own<br>And all the solid ground.</p>\n<p><strong>VERSE 3:</strong><br>Come, worship at His throne,<br>Come bow before the Lord:<br>We are His work, and not our own,<br>He formed us by His word.</p>\n<p><strong>VERSE 4:</strong><br>To-day attend His voice,<br>Nor dare provoke His rod:<br>Come like the people of His choice,<br>And own your gracious God.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(351, 'TAKE AND SANCTIFY', 'pending', NULL, '<p><strong>VERSES:</strong><br><strong>1.</strong> All that I am, all that I do<br>Everything I will ever make<br>Take my life and take my all<br>Everything I will ever make</p>\n<p><strong>2.</strong> All that I need, all that I pray<br>Everything I will ever have<br>Take my life and take my all<br>Everything I will ever have</p>\n<p><strong>3.</strong> All that I dream, all that I crave<br>Everything I will ever be<br>Take my life and take my all<br>Everything I will ever be</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(352, 'GOD LOVES A CHEERFUL GIVER', 'pending', NULL, '<p><strong>CHORUS:</strong><br>God loves a cheerful giver,<br>give all you\'ve got<br>He loves to hear you laughing.<br>When you\'re in an awkward spot.<br>When the odds add up against you,<br>it’s time to stop and sing:<br>“Praise God!” To Praise Him<br>is a joyous thing.</p>\n<p><strong>VERSE 1:</strong><br>Peter always made a fuss, Peter was impetuous,<br>He knew hard times when he denied his Lord,<br>But hardly had he fallen<br>when he got right up began again,<br>Christ named him His successor as his reward.</p>\n<p><strong>VERSE 2:</strong><br>Jonah was a gloomy sort,<br>he always had a sad report.<br>He ran from God, he ran and he set sail,<br>His journey\'s end was quite abrupt,<br>A fish came by and swallowed him up,<br>He spent three dark and dreary days<br>inside the whale.</p>\n<p><strong>VERSE 3:</strong><br>Holy job was richly blessed,<br>He lost it all but stood the test,<br>For Job was steadfast in his misery,<br>“God gives to me, He takes away,<br>Blessed be the name of God this day,”<br>And he was doubly blessed for his fidelity.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(353, 'EASTER SONG (MY LORD, HE DIED FOR A KINGDOM)', 'pending', NULL, '<p><strong>VERSE 1:</strong><br>My Lord, He died for a Kingdom,<br>To redeem the hearts of men,<br>Now my people, don\'t you weep,<br>He has risen from His sleep,<br>He lives again, alleluia.</p>\n<p><strong>CHORUS:</strong><br>Sing alleluia, the Lord is risen,<br>He is risen indeed alleluia!</p>\n<p><strong>VERSE 2:</strong><br>My Lord came forth like the morning<br>with the splendour of the sun,<br>Came triumphant from the womb,<br>from the darkness of the tomb,<br>the victory won, alleluia.</p>\n<p><strong>VERSE 3:</strong><br>My Lord united our mountains<br>with the everlasting hills,<br>Now the seasons and the sea<br>sing His song of victory,<br>rocks and rills, alleluia.</p>\n<p><strong>VERSE 4:</strong><br>My Lord renewed all creation<br>that had waited late and long,<br>Now we all with one accord<br>live and love the Risen Lord,<br>This is our song: alleluia.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(354, 'ALL OF MY LIFE', 'pending', NULL, '<p><strong>CHORUS:</strong><br>All of my life, I will praise the living God,<br>My heart full of joy, I will bless His holy name.</p>\n<p><strong>VERSE 1:</strong><br>Bless the Lord, O my soul!<br>And never forget his gifts.</p>\n<p><strong>VERSE 2:</strong><br>Bless the Lord, O my soul!<br>He pardons all our sin.</p>\n<p><strong>VERSE 3:</strong><br>Bless the Lord, O my soul!<br>He saves us from all harm.</p>\n<p><strong>VERSE 4:</strong><br>Bless the Lord, O my soul!<br>He fills our life with good.</p>\n<p><strong>VERSE 5:</strong><br>Bless the Lord, O my soul!<br>He keeps us ever young.</p>\n<p><strong>VERSE 6:</strong><br>Bless the Lord, O my soul!<br>His mercy never ends.</p>\n<p><strong>VERSE 7:</strong><br>Bless the Lord, O my soul!<br>His kindness never ends.</p>\n<p><strong>VERSE 8:</strong><br>Bless the Lord, O my soul!<br>His promises he keeps.</p>\n<p><strong>VERSE 9:</strong><br>Bless the Lord, O my soul!<br>He died to bring us life.</p>\n<p><strong>VERSE 10:</strong><br>Bless the Lord, O my soul!<br>He is the Bread of life.</p>\n<p><strong>VERSE 11:</strong><br>Bless the Lord, O my soul!<br>In him we find all love.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(355, 'ALL YOU WHO SEEK A COMFORT SURE', 'pending', NULL, '<p><strong>1.</strong><br>All you who seek a comfort sure<br>In trouble and distress,<br>Whatever sorrow vex the mind,<br>Or guilt the soul oppress.</p>\n<p><strong>Chorus:</strong><br>Jesus, who gave Himself for you<br>Upon the Cross to die,<br>Opens to you His Sacred Heart;<br>Oh, to that heart draw nigh.</p>\n<p><strong>2.</strong><br>You hear how kindly He invites;<br>You hear His words so blest:<br>"All you that labour, come to Me,<br>And I will give you rest."</p>\n<p><strong>3.</strong><br>What meeker than the Saviour\'s heart<br>As on the Cross He lay?<br>It did His murderers forgive<br>And for their pardon pray.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(356, 'I BELIEVE IN GOD', 'pending', NULL, '<p><strong>Refrain:</strong><br>Oh yes Lord I believe</p>\n<p><strong>1.</strong><br>Mighty Father I believe (refrain)<br>You created heaven and Earth (refrain)<br>I believe in Jesus Christ (refrain)<br>Everlasting son of God (refrain)</p>\n<p><strong>2.</strong><br>Equal in the father\'s pow\'r (refrain)<br>And through him all things were made (refrain)<br>He it was who saved us all (refrain)<br>And From heaven he came to earth (refrain)</p>\n<p><strong>3.</strong><br>Of the Virgin Mary born (refrain)<br>By the spirit was made flesh (refrain)<br>Suffered death and crucified (refrain)<br>And he rose up from the dead (refrain)</p>\n<p><strong>4.</strong><br>He ascended into heaven (refrain)<br>And his kingdom has no end (refrain)<br>In the spirit I believe (refrain)<br>Lord and vivifier of all (refrain)</p>\n<p><strong>5.</strong><br>With the Father and the Son (refrain)<br>He is adored and glorified (refrain)<br>I believe the Holy church (refrain)<br>And one baptism we professed (refrain)</p>\n<p><strong>6.</strong><br>I shall him in heaven (refrain)<br>Even in the world to come (refrain)<br>Amen amen amen Amen amen</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'creed'),
	(357, 'PAY BACK TIME', 'pending', NULL, '<p><strong>1.</strong><br>I believe that Jesus died for me<br>A Sacrifice beyond my understanding<br>Offering himself in place of me<br>Oh! how can I repay the lord?</p>\n<p><strong>CHORUS:</strong><br>Father to you we offer<br>Oh oh oh!<br>Jesus to you this gift we bring,<br>Holy ghost accept this offering<br>which we offer unto you.</p>\n<p><strong>2.</strong><br>I believe all that the scripture says<br>about the Lord beyond my understanding<br>Forgiveness beyond comprehension<br>Oh! how can I repay the Lord?</p>\n<p><strong>3.</strong><br>Teach me Lord to Love you as I ought<br>Oh! teach me Lord to Love you all my life time<br>Spreading Love where\'ve I find myself<br>Oh! how can I repay the Lord?</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(358, 'HOLY IS THE LORD', 'pending', NULL, '<p>Holy is the Lord,<br>Lord God of host.<br>Heaven and earth are full of your glory, Lord.<br>Hosanna, hosanna, hosanna in the highest.</p>\n<p>Holy is the Lord, God of power and might,<br>Blessed is he who comes in the name of the Lord.<br>Hosanna, hosanna, hosanna in the highest.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'sanctus'),
	(359, 'YOU ARE MY HIDING PLACE', 'pending', NULL, '<p><strong>Chorus:</strong><br>You are my hiding place, O Lord<br>You surround me with cries of deliverance.</p>\n<p><strong>1.</strong><br>Happy the man whose offence is forgiven, whose sin is remitted.<br>Happy the man to whom the Lord imputes no guilt, in whose spirit is no guile.</p>\n<p><strong>2.</strong><br>But now I have acknowledge my sins,<br>My guilt I did not hide, I said i will confess my offence to the Lord<br>And you Lord have forgiven, the guilt of my sin.</p>\n<p><strong>3.</strong><br>Rejoice! Rejoice! Rejoice in the Lord.<br>Exult! Exult, exult you just o come!<br>Ring out your joy all you upright of heart.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(360, 'GUIDE ME O THOU GREAT REDEEMER', 'pending', NULL, '<p><strong>1.</strong><br>Guide me O Thou great Redeemer,<br>Pilgrim through this barren land;<br>I am weak but thou art mighty,<br>Hold me with Thy powerful hand.</p>\n<p><strong>Chorus:</strong><br>Bread of heaven, Bread of heaven,<br>Feed me now and evermore;<br>Feed me now and evermore.</p>\n<p><strong>2.</strong><br>We gather Lord around your table<br>Waiting for the Bread of life.<br>Make us worthy, make us holy,<br>Take away all sin and strife.</p>\n<p><strong>3.</strong><br>Living bread come down from heaven,<br>He who eats it shall not die.<br>Come and eat and live forever,<br>You shall live with God on High.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(361, 'GREAT IS THY FAITHFULNESS', 'pending', NULL, '<p><strong>1.</strong><br>Great is Thy faithfulness, O God my Father;<br>There is no shadow of turning with Thee;<br>Thou changest not, Thy compassions, they fail not;<br>As Thou hast been, Thou forever will be.</p>\n<p><strong>Chorus:</strong><br>Great is Thy faithfulness!<br>Great is Thy faithfulness!<br>Morning by morning new mercies I see.<br>All I have needed Thy hand hath provided;<br>Great is Thy faithfulness, Lord, unto me!</p>\n<p><strong>2.</strong><br>Summer and winter and springtime and harvest,<br>Sun, moon and stars in their courses above,<br>Join with all nature in manifold witness<br>To Thy great faithfulness, mercy and love.</p>\n<p><strong>3.</strong><br>Pardon for sin and a peace that endureth,<br>Thine own dear presence to cheer and to guide;<br>Strength for today and bright hope for tomorrow,<br>Blessings all mine, with ten thousand beside!</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(362, 'O COME O COME EMMANUEL', 'pending', NULL, '<p><strong>1.</strong><br>O come, O come, Emmanuel,<br>And ransom captive Israel,<br>That mourns in lonely exile here,<br>Until the Son of God appear.</p>\n<p><strong>Chorus:</strong><br>Rejoice! Rejoice! Emmanuel<br>Shall come to thee, O Israel.</p>\n<p><strong>2.</strong><br>O come, Thou Rod of Jesse, free<br>Thine own from Satan\'s tyranny;<br>From depths of hell Thy people save,<br>And give them victory o\'er the grave.</p>\n<p><strong>3.</strong><br>O come, Thou Dayspring, from on high,<br>And cheer us by Thy drawing nigh;<br>Disperse the gloomy clouds of night,<br>And death\'s dark shadows put to flight.</p>\n<p><strong>4.</strong><br>O come, Thou Key of David, come<br>And open wide our heav\'nly home;<br>Make safe the way that leads on high,<br>And close the path to misery.</p>\n<p><strong>5.</strong><br>O come, Adonai, Lord of might,<br>Who to Thy tribes, on Sinai\'s height?<br>In ancient times didst give the law<br>In cloud and majesty and awe.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(363, 'ALL PEOPLE THAT ON EARTH', 'pending', NULL, '<p><strong>1.</strong><br>All people that on earth do dwell,<br>Sing to the Lord with cheerful voice;<br>Him serve with fear, his praise forth tell.<br>Come ye before him, and rejoice.</p>\n<p><strong>2.</strong><br>Know that the Lord is God indeed;<br>Without our aid he did us make;<br>We are his flock, he doth us feed,<br>And for his sheep he doth us take.</p>\n<p><strong>3.</strong><br>O enter then his gates with praise;<br>Approach with joy his courts so true;<br>Laud, and bless His name always.<br>For it is seemly so to do.</p>\n<p><strong>4.</strong><br>For why, the Lord our God is good;<br>His mercy is forever sure;<br>His truth at all times firmly stood,<br>And shall from age to age endure.</p>\n<p><strong>5.</strong><br>To Father, Son and Holy Ghost,<br>The God whom heaven and earth adore.<br>From men and from the angel host<br>Be praise and glory evermore.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(364, 'COME COME COME', 'pending', NULL, '<p><strong>1.</strong><br>Come come come let us offer our gift,<br>I\'ll offer my gift, to you oh Lord.<br>Come come come let us offer our gifts, the gift from my heart I will bring.</p>\n<p><strong>Refrain:</strong><br>Ciborium of bread, wine in chalice.<br>Gift from our hearts we bring to you.</p>\n<p><strong>2.</strong><br>Gather together sacrifice we offer, bringing all the sheeves which comes from our harvest. Father son and spirit accept this offering, gifts from my heart I will bring.</p>\n<p><strong>3.</strong><br>Oh Lord accept this gift we offer in your name, for the praise and glory of your name. O bless them oh Lord sanctify this gift we bring in your name</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(365, 'NWATURU CHUKWU (IGBO AGNUS DEI)', 'pending', NULL, '<p>Nwaturu chukwu, nwaturu chukwu onye n\'e kpochapu njo nkeru uwa mere\'anyi ebere, mere anyi ebere mere\'anyi ebere biko nna me ebere</p>\n<p>Nwaturu chukwu nwaturu chukwu onye n\'e kpochapu njo nkeru uwa nye anyi udo nye anyi udo nye\'anyi udo nna nye\'anyi udo</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'agnus_dei'),
	(366, 'GLORY BE TO GOD IN THE HIGHEST', 'pending', NULL, '<p>Glory be to God in the highest A...le..luia<br>And on earth peace to men of good will. A...le.luia<br>We praise you, Alleluia, We bless you, We adore you, We glorify you...A...le.luia</p>\n<p><strong>2.</strong><br>We thank you for your great glory A....<br>Heavenly King, God Almighty Father...</p>\n<p><strong>3.</strong><br>Lord Jesus Christ, Only begotten Son A..leluia<br>Lord Lamb of God son of the father.</p>\n<p><strong>4.</strong><br>Lord Jesus Christ, you take away our sin<br>Have mercy and receive our prayer.</p>\n<p><strong>5.</strong><br>Seated at the right hand of the father<br>Holy one, our Lord the most high.</p>\n<p><strong>6.</strong><br>Jesus Christ reigning with the spirit<br>In the Glory of God the father.<br>Alleleuia, we praise you..</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'gloria'),
	(367, 'CHRIST AROSE', 'pending', NULL, '<p><strong>1.</strong><br>Low in the grave He lay,<br>Jesus my Saviour!<br>Waiting the coming day,<br>Jesus my Lord!</p>\n<p><strong>Chorus:</strong><br>Up from the grave He arose,<br>With a mighty triumph o\'er His foes;<br>He arose a victor from the dark domain,<br>And He lives forever with His Saints to reign<br>He arose! He arose!<br>Alleluia! Christ arose!</p>\n<p><strong>2.</strong><br>Vainly they watch His bed,<br>Jesus my Saviour!<br>Vainly they seal! the dead,<br>Jesus my Lord!</p>\n<p><strong>3.</strong><br>Death cannot keep his prey,<br>Jesus my Saviour!<br>He tore the bars away,<br>Jesus my Lord!</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(368, 'WORTHY IS THE LAMB', 'pending', NULL, '<p>Worthy is the Lamb that was slain,<br>And hath redeemed us to God by his blood,<br>To receive power, and riches, and wisdom, and strength, and honour,<br>and glory, and blessing.</p>\n<p>Blessing and honour, glory and power, be unto Him<br>Be unto Him that sitteth upon the throne, and unto the Lamb, for ever and ever.<br>Amen.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(369, 'HALLELUJAH CHORUS', 'pending', NULL, '<p>Hallelujah hallelujah hallelujah hallelujah hallelujah<br>Hallelujah hallelujah hallelujah hallelujah hallelujah<br>For the lord God omnipotent reigneth<br>Hallelujah hallelujah hallelujah hallelujah<br>For the lord God omnipotent reigneth<br>Hallelujah hallelujah hallelujah hallelujah<br>For the lord God omnipotent reigneth<br>Hallelujah hallelujah hallelujah hallelujah<br>Hallelujah hallelujah hallelujah hallelujah<br>Hallelujah hallelujah hallelujah hallelujah<br>(For the lord God omnipotent reigneth)<br>Hallelujah hallelujah hallelujah hallelujah<br>For the lord God omnipotent reigneth<br>(Hallelujah hallelujah hallelujah hallelujah)<br>Hallelujah</p>\n<p>The kingdom of this world;<br>is become<br>the kingdom of our Lord,<br>and of His Christ<br>and of His Christ<br>And He shall reign for ever and ever<br>And he shall reign forever and ever<br>And he shall reign forever and ever<br>And he shall reign forever and ever</p>\n<p>King of kings forever and ever hallelujah hallelujah<br>and lord of lords forever and ever hallelujah hallelujah<br>King of kings forever and ever hallelujah hallelujah<br>and lord of lords forever and ever hallelujah hallelujah<br>King of kings forever and ever hallelujah hallelujah<br>and lord of lords<br>King of kings and lord of lords</p>\n<p>And he shall reign<br>And he shall reign<br>And he shall reign<br>He shall reign<br>And he shall reign forever and ever<br>King of kings forever and ever<br>and lord of lords hallelujah hallelujah<br>And he shall reign forever and ever<br>King of kings and lord of lords<br>King of kings and lord of lords<br>And he shall reign forever and ever<br>Forever and ever and ever and ever<br>(King of kings and lord of lords)</p>\n<p>Hallelujah hallelujah hallelujah hallelujah<br>Hallelujah</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(370, 'OBILIGO', 'pending', NULL, '<p>Eeh Obiligo, eeh Obiligo<br>Kristi emerigo onwu,<br>omerigo<br>Ka\'nyi nuriba nu, bute nu egwu Oma<br>n\'opi ike<br>Kristi Dinwenu anyi<br>Omerigo<br>Ik\'e-kwensu adago mba, mmeri chim\'e-guzorogo<br>N-nwa Chineke,<br>Omerigo</p>\n<p><strong>1.</strong><br>Na Gesthamani, Kristi riru\'ju<br>osiso nme nile, omerigo<br>Okpu ogwu, utari apiara ya<br>akpogbue ya n\'obe,<br>omerigo</p>\n<p><strong>2.</strong><br>N\'uzututu, mgbe anwu walu,<br>N\'ubochi nk\'ato,<br>umu nwanyi garan\'ili<br>Mana h\'ahughi ya<br>Ha choro y\'elu, choo ya n\'ala, choo ya n\'ugwu<br>choo ya na ndida, choo y\'ebenile<br>Mana h\'a hu ghi ya</p>\n<p><strong>3.</strong><br>Otu muo - ozi kwuru n\'uzo wee si ha,<br>nulibanu Kristi Dinwenu unu ebiligo<br>Oburugo unu uzo gaba na Galilee,<br>Gaba nu ga gwa umuazu ya n\'obiligo</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(371, 'CHRIST THE LORD IS RISEN TODAY', 'pending', NULL, '<p><strong>1.</strong><br>Christ the Lord is risen today!<br>Christians, haste your vows to pay;<br>Offer you your praises meet<br>At the Paschal Victim\'s feet,<br>For the sheep, the Lamb has bled,<br>Sinless in the sinner\'s stead;<br>Christ, the Lord, is risen on high,<br>Now he lives no more to die.</p>\n<p><strong>2.</strong><br>Christ, the Victim undefiled,<br>Man to God has reconciled;<br>When in strange and awful strife<br>Met together death and life;<br>Christians, on this happy day<br>Haste with joy your vows to pay<br>Christ, the Lord, is risen on high!<br>Now he lives no more to die.</p>\n<p><strong>3.</strong><br>Christ, who once for sinners bled,<br>Now the first born from the dead,<br>Throned in endless might and power,<br>Lives and reigns forever more.<br>Hail, eternal hope on high!<br>Hail, our King of victory!<br>Hail, our Prince of life adored!<br>Help and save us, gracious Lord.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(372, 'ALL HAIL THE POWER OF JESUS NAME', 'pending', NULL, '<p><strong>1.</strong><br>All hail the power of Jesus\' name!<br>Let angels prostrate fall.<br>Bring forth the royal diadem,<br>and crown him Lord of all.<br>Bring forth the royal diadem,<br>and crown him Lord of all!</p>\n<p><strong>2.</strong><br>O seed of Israel\'s chosen race<br>now ransomed from the fall,<br>hail him who saves you by his grace,<br>and crown him Lord of all.<br>Hail him who saves you by his grace,<br>and crown him Lord of all!</p>\n<p><strong>3.</strong><br>Let every tongue and every tribe<br>responsive to his call,<br>to him all majesty ascribe,<br>and crown him Lord of all.<br>To him all majesty ascribe,<br>and crown him Lord of all!</p>\n<p><strong>4.</strong><br>Oh, that with all the sacred throng<br>we at his feet may fall!<br>We\'ll join the everlasting song<br>and crown him Lord of all.<br>We\'ll join the everlasting song<br>and crown him Lord of all.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(373, 'ONYENWEANYI MEE EBERE', 'pending', NULL, '<p>Onyenwanyi Mee Ebere<br>Onyenwanyi Mee Ebere<br>Kristi Mee Ebere<br>Kristi Mee Ebere<br>Onyenwanyi Mee Ebere<br>Onyenwanyi Mee Ebere</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'kyrie'),
	(374, 'KING OF GLORY, KING OF PEACE', 'pending', NULL, '<p>King of glory, King of peace,<br>I will love Thee;<br>and that love may never cease,<br>I will move Thee.<br>Thou hast granted my request,<br>Thou hast heard me;<br>Thou didst note my working breast,<br>Thou hast spared me.</p>\n<p>Wherefore with my utmost art<br>I will sing Thee,<br>and the cream of all my heart<br>I will bring Thee.<br>Though my sins against me cried,<br>Thou didst clear me;<br>and alone, when they replied,<br>Thou didst hear me.</p>\n<p>Sev\'n whole days, not one in sev\'n,<br>I will praise Thee;<br>in my heart, though not in heav\'n,<br>I can raise Thee.<br>Small it is, in this poor sort<br>to enroll Thee:<br>e\'en eternity\'s too short<br>to extol Thee.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(375, 'I KNOW WHOM I HAVE BELIEVED', 'pending', NULL, '<p>I know not why God’s wondrous grace<br>To me He hath made known,<br>Nor why, unworthy, Christ in love<br>Redeemed me for His own.</p>\n<p><strong>Refrain:</strong><br>But “I know Whom I have believed,<br>And am persuaded that He is able<br>To keep that which I’ve committed<br>Unto Him against that day.”</p>\n<p>I know not how this saving faith<br>To me He did impart,<br>Nor how believing in His Word<br>Wrought peace within my heart.</p>\n<p>I know not how the Spirit moves,<br>Convincing men of sin,<br>Revealing Jesus through the Word,<br>Creating faith in Him.</p>\n<p>I know not what of good or ill<br>May be reserved for me,<br>Of weary ways or golden days,<br>Before His face I see.</p>\n<p>I know not when my Lord may come,<br>At night or noonday fair,<br>Nor if I walk the vale with Him,<br>Or meet Him in the air.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(376, 'LIFT UP YOUR HEADS O YE GATES', 'pending', NULL, '<p>Lift up your heads O ye gates,<br>Be ye lifted up ye everlasting doors.<br>And the King of glory shall come in.<br>And the King of glory shall come in.</p>\n<p>Who is the King of glory,<br>The Lord strong and mighty.<br>Who is the King of glory,<br>The Lord, mighty in battle.<br>Who is the King of glory,<br>The Lord strong and mighty.<br>Who is the King of glory,<br>The Lord, mighty in battle.</p>\n<p>Tenors: Lift up your heads O ye gates...<br>Altos: lift up your heads O ye gates...<br>Sopranos: lift up your heads O ye gates...</p>\n<p>Tenors: be ye lifted up ye everlasting doors...<br>Altos: be ye lifted up ye everlasting doors...<br>Sopranos: be ye lifted up ye everlasting doors.</p>\n<p>And the King of glory shall come in.<br>And the King of glory shall come in.</p>\n<p>Who is the King of glory,<br>The Lord strong and mighty.<br>Who is the King of glory,<br>The Lord, mighty in battle.<br>Who is the King of glory,<br>The Lord strong and mighty.<br>Who is the King of glory,<br>The Lord, mighty.</p>\n<p>He is the Lord,<br>He is the Lord,<br>He is the Lord,<br>He is the Lord mighty in battle</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(377, 'CHINEKE ONYEOMA', 'pending', NULL, '<p><strong>CHORUS:</strong><br>Kele Chineke jaa Ya mma (Soprano & Alto)<br>(All)<br>Ekele, O di mma eee<br>Onye kel’uwa<br>Onyeoma, Onyeoma, Onyeoma.</p>\n<p><strong>1.</strong><br>Sorom tobe Ya<br>Tobenu Chineke<br>Ekene diri Gi Nna<br>Imeela.</p>\n<p><strong>2.</strong><br>K’anyi jaa ya mma<br>Bunye Y’onyinye<br>Anyi ekele Gi Nna<br>Imela</p>\n<p><strong>3.</strong><br>Anyi g’eji gini kele Gi<br>Ezebube k’Ibu<br>Otito na nsopuru diri Gi<br>Eze dalu o!</p>\n<p><strong>4.</strong><br>Ihunanya Chineke kasi akasi<br>Olis’ebuluwa Chineke dalu o!<br>Imeka.</p>\n<p><strong>5.</strong><br>Na-ra- Onyinye umu Gi n’enye Gi<br>Na-ra Aja anyi n’achunyere Gi</p>\n<p><strong>6.</strong><br>Onyinye nwanyi ajadu<br>ka’nyi n’ebunye Gi<br>Na-ra-ya- ma gozie kwa’nyi</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(378, 'BRING THEM TO THE LORD', 'pending', NULL, '<p>Bring them to the Lord<br>I will bring my gift to the Lord<br>I will offer unto God<br>The gift from my heart<br>I will bring them and bring them to the Lord.</p>\n<p><strong>1.</strong><br>I lost my way and went astray<br>Jesus came to me<br>He touched my heart<br>He touched my soul<br>And then He led me home</p>\n<p><strong>2.</strong><br>I lost my sight I cannot see<br>A shadow tell on me<br>He Spoke to me it was Jesus<br>An I can see again.</p>\n<p><strong>3.</strong><br>I was afloat the troubled sea<br>Jesus came to me<br>He held me close and I calmed my fears<br>And then He led me home.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(379, 'THIS THANKSGIVING OF AMAZING GRACE', 'pending', NULL, '<p>This is thanksgiving of amazing grace<br>Amazing grace, amazing grace<br>Thanksgiving of amazing grace<br>Lord bless the work of our hands<br>Amazing grace</p>\n<p>This is thanksgiving of amazing grace<br>Amazing grace, amazing grace<br>Thanksgiving of amazing grace<br>Lord bless the work of our hands<br>Amazing grace</p>\n<p>The earth is the Lord\'s and everything in it<br>The world and all who live in it<br>For he founded it upon the seas<br>And established it upon the waters<br>Amazing works of your hands<br>We thank you, we bless you Lord</p>\n<p>This is thanksgiving of amazing grace<br>Amazing grace, amazing grace<br>Thanksgiving of amazing grace<br>Lord bless the work of our hands<br>Amazing grace</p>\n<p>We thank you Lord for the grace to be alive<br>And we thank you Lord for the goodness we enjoy<br>We thank you Lord for our families<br>The Gift of children, Lord, friends and relations<br>Amazing works of your hands<br>We thank you, we bless you Lord</p>\n<p>This is thanksgiving of amazing grace<br>Amazing grace, amazing grace<br>Thanksgiving of amazing grace<br>Lord bless the work of our hands<br>Amazing grace</p>\n<p>This is thanksgiving of amazing grace<br>Amazing grace, amazing grace<br>Thanksgiving of amazing grace<br>Lord bless the work of our hands<br>Amazing grace</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(380, 'RIDE ON IN MAJESTY', 'pending', NULL, '<p><strong>1.</strong><br>Ride on, ride on in majesty!<br>Hear all the tribes hosanna cry!<br>O Savior meek, pursue your road<br>With palms and scattered garments stroked.</p>\n<p><strong>Chorus:</strong><br>Ride on, Ride on, ride on in majesty! (3x)<br>In lowly pomp ride on to die.</p>\n<p><strong>2.</strong><br>Ride on, ride on, in majesty!<br>The hosts of angels in the sky<br>Look down with sad and wondering eyes<br>To see th’approaching Sacrifice.</p>\n<p><strong>3.</strong><br>Ride on, ride on, in majesty!<br>Your last and fiercest strife is nigh.<br>The Father on his sapphire throne<br>Awaits his own anointed Son.</p>\n<p><strong>4.</strong><br>Ride on, ride on, in majesty!<br>In lowly pomp, ride on to die.<br>Bow your meek head to mortal pain,<br>Then take, O Christ, your power and reigns</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(381, 'COME LET US REJOICE', 'pending', NULL, '<p><strong>VERSE 1:</strong><br>Come let us rejoice before the Lord Almighty<br>Sing alleluia to him, He is our God,<br>Yes He is our God and we are all his people,<br>Sing alleluia to Him for e’er</p>\n<p><strong>CHORUS:</strong><br>Praise Him alleluia, praise Him alleluia<br>Praise Him alleluia, Let’s praise Him alleluia,<br>Praise Him alleluia, praise Him alleluia<br>Alleluia, Let’s praise Him alleluia, Alleluia!!!!</p>\n<p><strong>VERSE 2:</strong><br>Come into His courts with melodies and praises<br>Praise Him for His love and care that has no end<br>Yes He is our God, and we are all His people’<br>Sing alleluia to Him for e’er</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(382, 'LET US BREAK BREAD TOGETHER', 'pending', NULL, '<p><strong>VERSE 1:</strong><br>Let us break bread together on our knees;<br>let us break bread together on our knees;<br>when I fall down on my knees<br>with my face to the rising sun,<br>O Lord, have mercy on me.</p>\n<p><strong>VERSE 2:</strong><br>Let us drink wine together on our knees;<br>let us drink wine together on our knees;<br>when I fall down on my knees<br>with my face to the rising sun,<br>O Lord, have mercy on me.</p>\n<p><strong>VERSE 3:</strong><br>Let us praise God together on our knees;<br>let us praise God together on our knees;<br>when I fall down on my knees<br>with my face to the rising sun,<br>O Lord, have mercy on me.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(383, 'I AM THE LIVING BREAD', 'pending', NULL, '<p><strong>VERSE 1:</strong><br>I am the living bread, which has come down from heaven<br>Anyone who eats this bread, will live forever and ever</p>\n<p><strong>CHORUS:</strong><br>Come and eat my body and drink my blood<br>I will give you peace and eternal life</p>\n<p><strong>VERSE 2:</strong><br>I tell you solemnly, if you do not eat my flesh,<br>If you do not drink my blood<br>If you do not eat the flesh of the son of Man,<br>You will have no life in you.</p>\n<p><strong>VERSE 3:</strong><br>Anyone who eats my body and drinks my blood shall live<br>Shall live forever and ever.<br>I shall raise him up, I shall raise him up, I shall raise him up<br>On the last day.</p>\n<p><strong>VERSE 4:</strong><br>Whosoever eats my flesh, whosoever drinks my blood<br>Whosoever eats my flesh and drinks of my blood,<br>Shall live in me and I in him.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(384, 'I AM THE BREAD OF LIFE', 'pending', NULL, '<p>I am the bread of life. He who comes to me shall not hunger; he who believes in me shall not thirst. No one can come to me unless the Father draw him. And I will raise him up, and I will raise him up, and I will raise him up on the last day.</p>\n<p>The bread that I will give is my flesh for the life of the world, and he who eats of this bread, he shall live for ever, he shall live for ever. And I will raise him up, and I will raise him up, and I will raise him up on the last day.</p>\n<p>Unless you eat of the flesh of the Son of Man and drink of his blood, and drink of his blood, you shall not have life within you. And I will raise him up, and I will raise him up, and I will raise him up on the last day.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(385, 'REJOICE MASS IS ENDED', 'pending', NULL, '<p><strong>Chorus:</strong><br>Rejoice mass is ended<br>Alleluia Amen, Let us go home and thank the Lord<br>Alleluia Amen</p>\n<p><strong>VERSE 1:</strong><br>Rejoice mass is ended, glory be to God,<br>Let us go home spreading the good news<br>Wherever Man is found</p>\n<p><strong>VERSE 2:</strong><br>You are a child of light, go show the light to the world<br>Distributing Jesus to every heart<br>With every sense of Love.</p>\n<p><strong>VERSE 3:</strong><br>Lord help your people to seek what You desire,<br>As they go home to serve You,<br>Alleluia amen</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(386, 'BABA GBOPE WA', 'pending', NULL, '<p><strong>Chorus:</strong><br>Gbore wa o,<br>gbore wa o<br>ele-du ma re a  wa  so  pe<br>funore  ofe  re  ni  nu  aiye  wa  baba  adupe  o<br>gbore  tia  muwa   e  ledumare..</p>\n<p><strong>Verse 1:</strong><br>Ope  iyin  ogo  lamuwa  siwaju  re baba<br>I  jo  ilu  a  torin  lamuwa  siwaju  re..<br>Baba lo  ke..  baba  lo  ke<br>Te  wo  gbope  wa,  te  wo  gbope  wa<br>Baba lo  ke... baba lo  ke<br>gbore  tiamuwa   e-  leduma  re</p>\n<p><strong>Verse 2.:</strong><br>Oso  funwa  wi  pe  ninu  ohun  ko  hun<br>kia  ma dupe<br>O  hun  ti  ba  sele  o  si  se  po<br>fun  rere  fun  wa<br>Adupe  adupe   baba  adupe  o<br>gbore  tia  muwa  e_eledumare</p>\n<p><strong>Verse 3:</strong><br>Mo  mo  ri  ri  ore baba o<br>iwo   ore  mi ye  o<br>sunmo   biwa  gbo  o  jare<br>Sunmo  biwa  gbo  baba sere re  funwa<br>Sunmo  biwa  gbo  baba sere re  funwa<br>Sunmo  biwa  gbo  baba sere re  funwa<br>Ba  ba  wa  gbo  pe.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(387, 'ABINCI ALHERI', 'pending', NULL, '<p><strong>REFRAIN:</strong><br>Abinci Alheri shine zamu ci Abinci Alheri Abinci rai shiryeye daga wurin Allah oh Abinci Alheri zamu ci</p>\n<p><strong>Verse 1:</strong><br>Yesu ya dauki gurasa yabamu yace wanan shine jikin na daza ba a duka mutane<br>Kristi ya dauki koko yabamu yace wanan shine jini na daza ba a duka mutane</p>\n<p><strong>Verse 2:</strong><br>Gurasa da koko da mu karbi shine jikin shine jinni Yesu duk wanda ya karbi shi a cikin tsarkakiya zucyi zai samu rai har abada in kuna kauna Shi zai samu rai har abada</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(388, 'HUEAN JESU', 'pending', NULL, '<p><strong>Verse 1:</strong><br>O Jesu, ze’ hi bu mhenre ne gbe bia’ hu<br>mhe kha gbon gbon<br>Huean re gbe bia’ran non se mne<br>khe ji mhan de o<br>bhe don......Chorus</p>\n<p><strong>Verse 2:</strong><br>Ebealen, Huean gbee’ lo<br>ghe Ibho khanlen se le re bhe.<br>Rofure mhan, rhi’ iyen len ni mhan,<br>Osenob’lua mhan bhie.... chorus</p>\n<p><strong>Chorus:</strong><br>Huean Jesu 3x<br>khe ji mhan de<br>O bhe’ don mhen<br>ona mhan bhi Ebealen<br>Ise!!!</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(389, 'OBONG AMANAM', 'pending', NULL, '<p><strong>CHORUS:</strong><br>Amanam Obong amanam O sosongo<br>Manam manam manam manam yenyi O sosongo (2ce)</p>\n<p><strong>Verse 1:</strong><br>Abasi mbok O bong amanam O kedi nonnyin U sen mfin emi sosongo bong ye ima fo</p>\n<p><strong>Verse 2:</strong><br>Baba owo nte kiet I biet ke Obong kem fon ido yeki ma fo O bong Yak ekom ye ukpo no yenefi</p>\n<p><strong>Verse 3:</strong><br>Ete mfon nyin I mo kom fi O kedi no Jesus man edi kpa oro anam nnyin I di kom fi O</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(390, 'KYRIE (YORUBA)', 'pending', NULL, '<p>Oluwa sanu fun wa<br>Sanu fun wa<br>Oluwa, Oluwa sanu fun wa<br>Christi sanu fun wa<br>Christi Sanu fun wa<br>Christi sanu fun wa,  O Christi Christ sanu fun wa<br>Oluwa sanu fun wa<br>Sanu fun wa<br>Oluwa, Oluwa sanu fun wa</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'kyrie'),
	(391, 'TEWO GB\'EBOWA', 'pending', NULL, '<p>Tewo GB\'EBOWA Babawa tewo Gbebowa Baba Olodumare e eyinla wa r\'ubosio  tewo Gbebowa laiye Baba wa t\'ewo gb\'ebo was laiye Babawa t\'ewo gb\'ebo wa t\'ewo gb\'ebo wa</p>\n<p><strong>1.</strong><br>Baba egbe wa papa o-unla was r\'ubo fun o t\'ewo gb\'ebo wa<br>Awon aro po papa a wonla wa r\'ubo fun o t\'ewo gb\'ebo wa<br>Gbogo Kristi a ni awonla was r\'ubo fun o t\'ewo gb\'ebo wa</p>\n<p><strong>2.</strong><br>Awa pelu Maria e yinla wa r\'ubo si o t\'ewo gb\'ebo wa<br>Awa pelu Joseph e yinla wa r\'ubo si o t\'ewo gb\'ebo wa<br>Awa pelu Peteru e yinla wa r\'ubo si o t\'ewo gb\'ebo<br>Baba Olodumare eyinla wa r\'ubo si t\'ewo gb\'ebo wa</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(392, 'OMOGODE R\'OGHENE (URHOBO AGNUS DEI)', 'pending', NULL, '<p>Omogode omogode r\'oghene,<br>Omogode omogode r\'oghene (2x)<br>Rosi I mue mu rakpo na no na rue don ra vwa re</p>\n<p>Omogode omogode r\'oghene,<br>Omogode omogode r\'oghene (2x)<br>Rosi I mue mu rakpo na no vwu fuo ma ka vwa re</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'agnus_dei'),
	(393, 'IN LOVE WITH JESUS', 'pending', NULL, '<p><strong>Chorus:</strong><br>Take me deeper in love with you Jesus oh deeper in love<br>Hold me closer in love with you Jesus oh closer in love with you</p>\n<p><strong>1.</strong><br>Lord there is a longing only you can feel<br>A raging tempest only you can still<br>My soul is thirsting for you oh my God<br>Lord quench my thirst Lord feed my soul</p>\n<p><strong>2.</strong><br>Yes from sunrise to sunrise I seek your face<br>From day to day I long for your touch<br>To hold my hand Lord lest I fall<br>So draw me nearer closer to thee</p>\n<p><strong>3.</strong><br>In your love is found great faithfulness<br>Your love is filled with hope and peace<br>Your love is filled with compassion and joy<br>O teach me Lord to love you more</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(394, 'THIS JOYFUL EASTERTIDE', 'pending', NULL, '<p><strong>1.</strong><br>This joyful Eastertide<br>away with sin and sorrow!<br>My love, the Crucified,<br>has sprung to life this morrow.</p>\n<p><strong>Refrain:</strong><br>Had Christ, who once was slain,<br>not burst his three-day prison,<br>our faith had been in vain:<br>but now hath Christ arisen,<br>arisen, arisen, arisen!</p>\n<p><strong>2.</strong><br>Death\'s flood has lost its chill<br>since Jesus crossed the river.<br>Lover of souls, from ill<br>my passing soul deliver.</p>\n<p><strong>3.</strong><br>My flesh in hope shall rest<br>and for a season slumber<br>till trump from east to west<br>shall wake the dead in number.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(395, 'IHE NILE\'M N\'WERE N\'UWA DIGIN\'AKA', 'pending', NULL, '<p>Ihe nile\'m n\'were n\'uwa digin\'aka x2<br>O-nwu diginika, ndu digin\'aka<br>Ebe\'mnwe-re eze Jisos,<br>o-nye kamg\'a tu e-gwu\'ozo</p>\n<p>Ihe nile\'m n\'were n\'uwa sigin\'aka<br>I-he\'obulambu n\'uwa sigin"aka<br>Aku n\'ubam sigin\'aka<br>Obi anuri sigin"aka.</p>\n<p>K\'anyi jee n\'ulo Chukwu bunye ya ekele<br>I-mam ma n\'ilem ma-ra, sigi n\'aka,<br>A-ma mi-he, ako na uche m nwere sigin\'aka<br>Ahuike na i-kike ni-le digin\'aka,<br>Ezinu-lo m ngozi, ngozi sigin\'aka<br>Akunuba ugboala m ni-le sigin\'aka.</p>\n<p>Odisia\'n-jo odiba\'m ma ha nile digin\'aka<br>Ogu guisi sigin\'aka, i-he nile sichagin\'aka,<br>K\'a-nyi jee n\'ulo Chukwu bu-nye ya ekele</p>\n<p>K\'a-nyi jee n\'ulo Chukwu x2<br>Tu-wa-ra ya\'mam ma, Tu-wa-ra ya\'mam ma,<br>Eze Jisos Tu-wa-ra ya\'mam ma<br>Si ya n\'o-mela,tu-wa-ra ya\'mam ma<br>Tu-wa-ra ya\'mam ma, (Si ya n\'o-mela X3)</p>\n<p>Eze Jisos Tu-wa-ra ya\'mam ma<br>Si ya n\'o-mela.<br>Tu-wa-ra ya\'mam ma- - -<br>Si ya n\'o-mela.- - -<br>Eze Jisos Tu-wa-ra ya\'mam ma<br>Si ya n\'o-mela.- - -(imela)</p>\n<p>Ihe nile\'m n\'were n\'uwa si n\'aka chukwu X2<br>Ihe nile\'m n\'were n\'uwa X2<br>Ihe ni-le, ihe ni-le\'m n\'were - - -<br>Solo---( uh.....o si n\'aka chukwu)- - -<br>Ihe nile\'m n\'were n\'uwa si n\'aka chukwu X2<br>Ihe ni-le digin\'aka, ha ni-le sigin\'aka<br>Ebe\'m nwere Eze Jisos, a-ga ghim atu egwo-zo- - -</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(396, 'LORD I’M COMING HOME', 'pending', NULL, '<p><strong>1.</strong><br>I\'ve wandered far away from God,<br>Now I\'m coming home;<br>I now repent with bitter tears,<br>Lord, I\'m coming home.<br>(Refrain)</p>\n<p><strong>2.</strong><br>I\'ve wasted many precious years,<br>Now I\'m coming home;<br>I now repent with bitter tears,<br>Lord, I\'m coming home.<br>(Refrain)</p>\n<p><strong>3.</strong><br>I\'ve tired of sin and straying, Lord,<br>Now I\'m coming home;<br>I\'ll trust Thy love, believe Thy word,<br>Lord, I\'m coming home.<br>(Refrain)</p>\n<p><strong>4.</strong><br>My soul is sick, my heart is sore,<br>Now I\'m coming home;<br>My strength renew, my hope restore,<br>Lord, I\'m coming home.<br>(Refrain)</p>\n<p><strong>Refrain:</strong><br>Coming home, coming home,<br>Nevermore to roam,<br>Open wide Thine arms of love,<br>Lord, I\'m coming home. "</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(397, 'EZI CHUKWU NARA AJA ANYI', 'pending', NULL, '<p><strong>Chorus:</strong><br>Anyi ario gi, Nara Aja anyi<br>Ezi chukwu ezi, Chukwu nabata ya<br>Were ya, gozie ya, mekwaa ya nna, k’odi mma<br>Kwesi n’Iganara ya.</p>\n<p><strong>VERSE 1:</strong><br>Mgbe anyi n’erunyere gi aja obi oma anyi<br>Nke bu ihe ala miputara<br>Obughi nkwughachi ihunanya gi<br>Anyi enweghi ike ya.</p>\n<p><strong>VERSE 2:</strong><br>Mgbe’obula anyi bu umu gi gbakoro<br>n’ihu gi ichuru gi Aja kasi nso,<br>K’anyi n’erunye ya maka ndi mmadu nile<br>Ndi di ndu na ndi nwuru anwu.</p>\n<p><strong>VERSE 3:</strong><br>So gi bu ndu ndi kwere na gi<br>Ndu ihe nile n’uwa na n’eluigwe;<br>Gosi anyi Uzo nke ka mma iji wee gosi gi<br>Anuri anyi na gi.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(398, 'SOFTLY AND TENDERLY', 'pending', NULL, '<p><strong>1.</strong><br>Softly and tenderly Jesus is calling,<br>Calling for you and for me;<br>See, on the portals He’s waiting and watching,<br>Watching for you and for me.</p>\n<p><strong>Refrain:</strong><br>Come home, come home,<br>You who are weary, come home;<br>Earnestly, tenderly, Jesus is calling,<br>Calling, O sinner, come home!</p>\n<p><strong>2.</strong><br>Why should we tarry when Jesus is pleading,<br>Pleading for you and for me?<br>Why should we linger and heed not His mercies,<br>Mercies for you and for me?</p>\n<p><strong>3.</strong><br>Time is now fleeting, the moments are passing,<br>Passing from you and from me;<br>Shadows are gathering, deathbeds are coming,<br>Coming for you and for me.</p>\n<p><strong>4.</strong><br>Oh, for the wonderful love He has promised,<br>Promised for you and for me!<br>Though we have sinned, He has mercy and pardon,<br>Pardon for you and for me.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(399, 'PIE JESU', 'pending', NULL, '<p>Pie Jesu, pie Jesu, pie Jesu, pie Jesu<br>Qui tollis peccata mundi<br>Dona eis requiem, dona eis requiem</p>\n<p>Pie Jesu, pie Jesu, pie Jesu, pie Jesu<br>Qui tollis peccata mundi<br>Dona eis requiem, dona eis requiem</p>\n<p>Agnus Dei, Agnus Dei, Agnus Dei, Agnus Dei<br>Qui tollis peccata mundi<br>Dona eis requiem, dona eis requiem</p>\n<p>Dona eis requiem<br>Sempiternam<br>Dona eis requiem<br>Sempiternam<br>Requiem<br>Sempiternam</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(400, 'FADE, FADE, EACH EARTHLY JOY', 'pending', NULL, '<p><strong>VERSE 1:</strong><br>Fade, fade, each earthly joy, Jesus is mine!<br>Break every tender tie, Jesus is mine!<br>Dark is the wilderness,<br>Earth has no resting place,<br>Jesus alone can bless, Jesus is mine!</p>\n<p><strong>VERSE 2:</strong><br>Tempt not my soul away, Jesus is mine!<br>Here would I ever stay, Jesus is mine!<br>Perishing things of clay,<br>Born but for one brief day,<br>Pass from my heart away! Jesu is mine!</p>\n<p><strong>VERSE 3:</strong><br>Farewell, ye dreams of night, Jesus is mine!<br>Lost in this dawning Light, Jesus is mine!<br>All that my soul has tried,<br>Left but a dismal void,<br>Jesus has satisfied, Jesus is mine!</p>\n<p><strong>VERSE 4:</strong><br>Farewell, mortality, Jesus is mine!<br>Welcome, eternity! Jesus is mine,<br>Welcome, O loved and blest,<br>Welcome, sweet scenes of rest,<br>Welcome, my saviour bless, Jesus is mine!</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(401, 'SECOND CHANCE', 'pending', NULL, '<p><strong>CHORUS:</strong><br>Lord I need your presence<br>That I may be free from sins<br>Guide o Lord through thy ways<br>Save me Lord or I die<br>Please pardon me of my guilt<br>Wash away my sins save me Lord<br>Give me second chance that I may l live,<br>Save me Lord or I die</p>\n<p><strong>VERSE 1:</strong><br>I am old in sin I was born<br>I have lived in sin all my life<br>I have come to you o Jesus<br>Save me Lord or I die, give Lord a second chance</p>\n<p><strong>VERSE 2:</strong><br>I have lived a life of deceit<br>And I cheated, I scorned, I dishonored<br>I surrender to you Jesus<br>Save me Lord or I die give Lord a second chance</p>\n<p><strong>VERSE 3:</strong><br>Christ the rock on you I depend<br>Comfort me take me as I am<br>Oh Lord give me your grace to live<br>Save me Lord or I die give Lord a second chance</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(402, 'OLD RUGGED CROSS', 'pending', NULL, '<p><strong>1.</strong><br>On a hill far away stood an old rugged cross<br>The emblem of suffering and shame<br>And I love that old cross where the dearest and best<br>For a world of lost sinners was slain</p>\n<p><strong>Refrain:</strong><br>So I\'ll cherish the old rugged cross (rugged cross)<br>Till my trophies at last I lay down<br>I will cling to the old rugged cross<br>And exchange it some day for a crown</p>\n<p><strong>2.</strong><br>To the old rugged cross I will ever be true<br>It\'s shame and reproach gladly bear<br>Then he\'ll call me some day to my home far away<br>Where his glory forever I\'ll share</p>\n<p><strong>3.</strong><br>And I\'ll cherish the old rugged cross (rugged cross)<br>Till my trophies at last I lay down<br>And I will cling to the old rugged cross<br>And exchange it some day for a crown<br>I will cling to the old rugged cross<br>And exchange it some day for a crown</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(403, 'ECCE SACERDOS MAGNUS', 'pending', NULL, '<p>Ecce Sacerdos Magnus<br>Ecce Sacerdos Magnus<br>Qui Indi e bus su is placuit Deo<br>Ecce Sacerdos Magnus<br>Ecce Sacerdos Magnus<br>Qui Indi ebus suis qui Indi ebus suis placuit Deo</p>\n<p>Non est in ventus similis illi qui conservaret legem excelsis,<br>Non est in ventus similis illi qui conservaret legem excelsis</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(404, 'ARA E GBE E GA', 'pending', NULL, '<p>Ogo ni f\'olorun loke o-run<br>Alaafia si ni laye<br>Fawon Eda oninu rere<br>Babawa agbe oga afiyi a\'tola fun o ogoye f\'olurunwa</p>\n<p>Ara e gbega ope ye f\'olorun iyi ye f\'olorun ogoye f\'olurunwa ogoye f\'olurunwa Amin</p>\n<p>Oluwa olorunwa odo agunta olorun  iwoto nko ese ayelo saanu funnwa gbotiwa</p>\n<p>Iwonikan lenimimo oluwa toga julo Jesu omo baba ninu isokan emimimo</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'gloria'),
	(405, 'ODO AGUNTAN OLORUN', 'pending', NULL, '<p>Odo aguntan Olorun,<br>Eyin toko ese aye lo<br>Saanu funwa<br>Saanu funwa<br>(Twice)</p>\n<p>Odo aguntan Olorun,<br>Eyin toko ese aye lo<br>Fun wa ni, fun wa ni<br>Alaafiya</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'agnus_dei'),
	(406, 'I HEARD THE VOICE OF JESUS SAY', 'pending', NULL, '<p><strong>VERSE 1:</strong><br>I heard the voice of Jesus say, “Come unto Me and rest;<br>Lay down, thou weary one, lay down Thy head upon My breast.”<br>I came to Jesus as I was, weary and worn and sad;<br>I found in Him a resting place, and He has made me glad.</p>\n<p><strong>VERSE 2:</strong><br>I heard the voice of Jesus say, “Behold, I freely give<br>The living water; thirsty one, stoop down, and drink, and live.”<br>I came to Jesus, and I drank of that life giving stream;<br>My thirst was quenched, my soul revived, and now I live in Him.</p>\n<p><strong>VERSE 3:</strong><br>I heard the voice of Jesus say, “I am this dark world’s Light;<br>Look unto Me, thy morn shall rise, and all thy day be bright.”<br>I looked to Jesus, and I found in Him my Star, my Sun;<br>And in that light of life I’ll walk, till traveling days are done.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(407, 'INTO YOUR SANCTUARY', 'pending', NULL, '<p><strong>Chorus:</strong><br>Into your sanctuary we’ve come to adore you Lord<br>Into your sanctuary, we’ve come to adore you Lord<br>In adoration and praise we glorify your holy name<br>Into your sanctuary, we’ve come to adore you Lord.</p>\n<p><strong>Verse 1:</strong><br>We thank you Lord,<br>For the gift of life in us<br>We reference your holy name<br>O our Lord</p>\n<p><strong>Verse 2:</strong><br>With sweet melody of Joy<br>Our mouth is full of praise<br>For one day in your house<br>Is better than a thousand elsewhere</p>\n<p><strong>Verse 3:</strong><br>Hide us under the shadow<br>Of your wings<br>That we may overcome<br>The tribulations of the world.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(408, 'WE OFFER THEE THE HOLY MASS (CHB 64)', 'pending', NULL, '<p><strong>VERSE 1:</strong><br>We offer thee the Holy Mass,<br>Thee our creator to adore,<br>To thank thee for thy gracious gifts,<br>And praise thy Name for evermore. Amen.</p>\n<p><strong>VERSE 2:</strong><br>Now Jesus Christ, thy flesh and blood,<br>Will be our sacrifice Divine,<br>The same in Mass as on the Cross,<br>Though under forms of Bread and Wine.</p>\n<p><strong>VERSE 3:</strong><br>We pray for pardon and for grace<br>To change the lives that we have led,<br>And beg thee for Thy Son\'s dear sake,<br>To bless the living and the dead.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(409, 'O PERFECT LOVE', 'pending', NULL, '<p><strong>Verse 1:</strong><br>O perfect Love, all human thought transcending<br>Lowly we kneel in prayer before thy throne<br>That theirs may be the love which knows no ending<br>Whom thou forevermore dost join in one</p>\n<p><strong>Verse 2:</strong><br>O perfect Life, be thou their full assurance<br>Of tender charity and steadfast faith<br>Of patient hope and quiet, brave endurance<br>With childlike trust that fears nor pain, nor death</p>\n<p><strong>Verse 3:</strong><br>Grant them the joy which brightens earthly sorrow<br>Grant them the peace which calms all earthly strife<br>And to life\'s day the glorious unknown morrow<br>That dawns upon eternal love and life</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(410, 'GOD IS HERE', 'pending', NULL, '<p>God is here, and that to bless us<br>With the Spirit’s quick’ning power;<br>See, the cloud already bending,<br>Waits to drop the grateful shower.<br>Let it come, O Lord, we pray Thee,<br>Let the shower of blessing fall;<br>We are waiting, we are waiting,<br>Oh, revive the hearts of all.</p>\n<p>God is here! we feel His presence<br>In this consecrated place;<br>But we need the soul refreshing<br>Of His free, unbounded grace.<br>Let it come, O Lord, we pray Thee,<br>Let the shower of blessing fall;<br>We are waiting, we are waiting,<br>Oh, revive the hearts of all.</p>\n<p>God is here! oh, then, believing,<br>Bring to Him our one desire,<br>That His love may now be kindled,<br>Till its flame each heart inspire.<br>Let it come, O Lord, we pray Thee,<br>Let the shower of blessing fall;<br>We are waiting, we are waiting,<br>Oh, revive the hearts of all.</p>\n<p>Savior, grant the prayer we offer,<br>While in simple faith we bow,<br>From the windows of Thy mercy<br>Pour us out a blessing now.<br>Let it come, O Lord, we pray Thee,<br>Let the shower of blessing fall;<br>We are waiting, we are waiting,<br>Oh, revive the hearts of all.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(411, 'ANIMA CHRISTI', 'pending', NULL, '<p><strong>VERSE 1:</strong><br>Passio Christi, conforta me. O bone Iesu, exaudi me. Intra vulnera tua absconde me.</p>\n<p><strong>VERSE 2:</strong><br>Ne permittas a te me separari. Ab hoste maligno defende me. In hora mortis meæ voca me.</p>\n<p><strong>VERSE 3:</strong><br>Et iube me venire ad te, Ut cum sanctis tuis laudem te Per infinita sæcula sæculorum. Amen.</p>\n<p><strong>CHORUS:</strong><br>Anima Christi Sanctifica me<br>Corpus Christi, Salva me<br>Sanguis Christi Inebria me<br>Aqua Lateris Christi, Lava me.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(412, 'WE PLOUGH THE FIELDS (CHB 66)', 'pending', NULL, '<p><strong>VERSE 1:</strong><br>We plough the fields, and scatter<br>the good seed on the land,<br>But it is fed and water\'d by God\'s Almighty hand;<br>He sends the snow in winter,<br>The warmth to swell the grain,<br>The breezes, and the sunshine,<br>And soft refreshing rain.</p>\n<p><strong>CHORUS:</strong><br>All good gifts around us<br>are sent from Heav’n above.<br>Then thank the Lord, O thank the Lord,<br>for all His Love.</p>\n<p><strong>VERSE 2:</strong><br>He only is the Maker of all things near and far;<br>He paints the wayside flower,<br>He lights the evening star;<br>The winds and waves obey Him,<br>By Him the birds are fed;<br>Much more to us, His Children,<br>He gives our daily bread.</p>\n<p><strong>VERSE 3:</strong><br>We thank Thee then, O then, O Father,<br>For all things bright and good,<br>The seed time and the harvest,<br>Our life, our health, our food;<br>Accept the gifts we offer<br>for all Thy love imparts.<br>And, what Thou most desirest,<br>Our humble, thankful hearts.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(413, 'HERE I AM LORD', 'pending', NULL, '<p><strong>Verse 1:</strong><br>I the Lord of sea and sky, I have heard my people cry;<br>all who dwell in dark and sin, my hand will save.<br>I who made the stars of night I will make their darkness bright,<br>who will bear my light to them. Whom shall I send</p>\n<p><strong>Refrain:</strong><br>Here I am Lord, it is I<br>Lors I have heard you calling in the night.<br>I will go Lord if You lead me<br>I will hold Your people in my heart</p>\n<p><strong>Verse 2:</strong><br>I the Lord of snow and rain I have borne my people’s pain<br>I have wept for love of them They run away.<br>I will break their heart of stone give them hearts of love alone<br>I will speak my word to them. Whom shall I send</p>\n<p><strong>Verse 3:</strong><br>I the Lord of wind and flame, I will tend the poor and lame<br>I will set a feast for them my hand will save.<br>Finest bread I will provide till their hearts be satisfied<br>I will give my life to them. Whom shall I send</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(414, 'THIS IS MY BODY (CHB 119)', 'pending', NULL, '<p><strong>CHORUS:</strong><br>This is my Body, given<br>for your freedom.<br>This is my Blood which was shed<br>for all mankind.<br>Take, all, and eat, till the day of my return.</p>\n<p><strong>VERSE 1:</strong><br>Peace to Zion, Yahweh\'s people;<br>Put your sorrows in my hands.<br>As I once led you to freedom,<br>Come now to my Father\'s house.</p>\n<p><strong>VERSE 2:</strong><br>On your journey to the kingdom,<br>You will find the strength you need,<br>At this table of remembrance,<br>Of my rising from the dead.</p>\n<p><strong>VERSE 3:</strong><br>Hear, my flock, now hear me calling<br>For I know you all by name.<br>Come with me the Blessed Shepherd,<br>To the new Jerusalem.</p>\n<p><strong>VERSE 4:</strong><br>When the whole world shakes with terror,<br>When the sky bursts into flame,<br>On the clouds shall I appear?<br>And you shall know my hour has come.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(415, 'THE BASILICAN CREED', 'pending', NULL, '<p>I believe in God the Father I believe in God the son I believe in God the Spirit one God forever more</p>\n<p>Mighty father I believe you created heaven and Earth and in Jesus Christ our Lord everlasting son God</p>\n<p>Equal in the Father\'s power and through him all things were made. He it was who saved us all from heaven he came to earth</p>\n<p>Of the Virgin Mary born by the spirit word made flesh suffered death was crucified and he rose up from the death</p>\n<p>He ascended to heaven and his kingdom had no end in the spirit I believe Lord and giver of all life</p>\n<p>With the Father and the son He\'s adored and glorified I believe in the Holy church and one baptism professed</p>\n<p>I shall see him in heaven, o yes Lord I believe living in the world to come amen amen</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'creed'),
	(416, 'LEENU NWATURU CHUKWU', 'pending', NULL, '<p>Leenu nwaturu Chukwu achicha ndioma nke si nigwe gbadata nuwa lee obu nri oma Kristi nyere anyi na Eucharistia di aso si anyi rie kanyi wee nweta ndu ebebe kanyi jeenu Nara ya nihi na obu nri oma anyi nwere isi oma bu ndi ge eri ya</p>\n<p>Etosighi m Kibata nime obim o dinwenu kwuo nu so okwu nobi m gadiriri dinwenu kwuonu so okwu nobi m gadiriri</p>\n<p>Chukwu nwa si nigwe gbadata n\'uwa were onwe ya meer\'anyi achicha nke ndu otar\'ahuhu nwuo onwu mak\'anyi wer\'obara ya di okeonu gbapu t\'anyi na njo Kristi n\'akponyi umunne ya ndi enyi ya ndi ohuru n\'anya si anyi bia Nara ya</p>\n<p>N\'ezie Jeso bu nri oma n\'ezie Jeso bu achicha nri ndi muozi, Bia Nara ahuya rie bia Nara obara ya nuo obu ezi ihe oriri n\'ezie o bu ezi ihe onunu nrioma na enye ndu</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(417, 'BOFI', 'pending', NULL, '<p><strong>1.</strong><br>Kime sese bofi bofi da fagha akpo yerin fagha akpor yerin o<br>Kime sese bofi tamara ngo fi da fagha fagha akpor yerin you</p>\n<p><strong>Refrain:</strong><br>Tamara ngo fio tamara asin bouo wo bouo o<br>Bouo Bouo fio bouo o da fagha fagha akpor yerin you</p>\n<p><strong>2.</strong><br>Kime sese bouo o bouo o da fagha akpo yerin fagha akpor yerin o<br>Kime sese bouo tamara sin bouo da fagha fagha akpor yerin you</p>\n<p><strong>3.</strong><br>Zesu Kristi buru buru da fagha akpo yerin fagha akpor yerin o<br>Zesu Kristi buru tamara ngo fi da fagha fagha akpor yerin mou</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(418, 'HAMMA SHIE', 'pending', NULL, '<p><strong>1.</strong><br>Zenden shin tar ne Ambatio mov nav hanma shie hanma jiir (2×)</p>\n<p><strong>Chorus:</strong><br>Hanma shie haan, han-ma shie haan, han-ma shie han-ma shie hanma jiir (2×)<br>A-mbatio mov nav Ken Jerusalem hanma shie hanma shie hanma jiir</p>\n<p><strong>2.</strong><br>Tesen se kwaghfan wou sha u dondon gbenda wou... hanma</p>\n<p><strong>3.</strong><br>Eren se baptisima sha u nyorun Ken ya wou hanma...</p>\n<p><strong>4.</strong><br>Yes se mba yilan we va kohol se shintarne hanma...</p>\n<p><strong>5.</strong><br>Shin tar ne se gba kwagh ga kpa u van hen vese abem hanma...</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(419, 'IN ONE GOD IN ONE GOD', 'pending', NULL, '<p>Do you believe in one God in one God in Jesus the son of God. In one God in one God who created heaven and Earth in Jesus the son of God, the saviour of the world</p>\n<p><strong>1.</strong><br>Conceived by the power of the Spirit born of the Virgin Mary, He suffered under Pontius Pilate was crucified and died</p>\n<p><strong>2.</strong><br>He was buried in the Earth he rose up on the third day, He reigns with the Father in heaven He will come to judge the world</p>\n<p><strong>3.</strong><br>I believe in the Holy Spirit, the Holy Catholic Church, the communion of saints the forgiveness of sin</p>\n<p><strong>4.</strong><br>The dead will rise on the last day to share in the life of God, a life that last for ever in the glory of the lord</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'creed'),
	(420, 'EDISANA (EFIK SANCTUS)', 'pending', NULL, '<p>Edisana Edisana</p>\n<p>Edisana Edisana<br>Edisana,</p>\n<p>Obong Abasi u-dim Ekong<br>Enyong ye isong eyohoye itoro\'fo<br>Edisana (2x)</p>\n<p>(Hosanna) Hosanna Hosanna Hosanna-a, Hosanna Hosa-nna<br>Ke ata ikpa enyong.</p>\n<p>Edisana Edisana..a-<br>Edisana Edisana..a<br>Edisana,</p>\n<p>E-mediong enye emi<br>E-di-de K\'enyin Obong (2x)</p>\n<p>(Hosanna) Hosanna Hosanna Hosanna-a, Hosanna Hosa-nna<br>Ke ata ikpa enyong.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'sanctus'),
	(421, 'COME THOU LONG EXPECTED SAVIOUR', 'pending', NULL, '<p><strong>1.</strong><br>Come thou long expected Saviour,<br>Born to set thy people free;<br>From our fears and sins release us;<br>Let us find our rest in thee,<br>Israel\'s strength and consolation,<br>Hope of all the earth thou art;<br>Fond desire of every nation,<br>Joy of every longing heart.</p>\n<p><strong>2.</strong><br>Born thy people to deliver,<br>Born a child and yet a King,<br>Born to reign in us forever,<br>Now thy gracious Kingdom bring.<br>By thine own eternal spirit;<br>Rule in all our hearts alone;<br>By thine all sufficient merit,<br>Raise us to thy glorious throne</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(422, 'LORD DISMISS US', 'pending', NULL, '<p><strong>1.</strong><br>Lord, dismiss us with your blessing;<br>Fill our hearts with joy and peace;<br>Let us each, your love possessing,<br>Triumph in redeeming grace:<br>O refresh us, O refresh us,<br>As we work to keep a-pace.</p>\n<p><strong>2.</strong><br>Thanks, we give and adoration<br>For your gospel\'s joyful sound:<br>May the fruits of this Communion<br>In our hearts and lives abound:<br>Ever faithful, ever faithful<br>To the truth may we be found.</p>\n<p><strong>3.</strong><br>So that when your love shall call us,<br>Saviour, from the world away,<br>Let no fear of death upset us,<br>Glad summons to obey:<br>May we ever, may we ever,<br>In your loving presence stay. Amen.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(423, 'COME TO THE HOUSE OF GOD', 'pending', NULL, '<p><strong>Chorus:</strong><br>Come to the house of God to blessed to be nourished, sing, sing, for the lord is here<br>We are a happy with Jesus by our side, we are a lucky people with Jesus by our side.</p>\n<p><strong>1.</strong><br>Come to the lord all you that Labour and He will give you rest.<br>He will gladen your heart, come to Jesus now and live.</p>\n<p><strong>2.</strong><br>Cast out thy burden upon the lord, He shall sustain thee.<br>He promised He will never forsake the righteous to fall. He is at the right hand</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(424, 'COME TO ME', 'pending', NULL, '<p><strong>1.</strong><br>Come to me, come to me,<br>all you that labour, all who are weary<br>I say come to me,<br>cast your yoke, cast your yoke<br>My yoke is lighter, My yoke is lighter<br>I say come to me.</p>\n<p><strong>Chorus:</strong><br>Jesus is calling you now,<br>come to Jesus as you are,<br>Jesus is calling you today,<br>come just as you are,<br>come just as you are.</p>\n<p><strong>2.</strong><br>Eat My flesh, eat My flesh,<br>you will never hunger, you will never hunger<br>I say eat My flesh,<br>drink from Me, drink from Me<br>never thirst again, never thirst again.<br>I say drink from Me</p>\n<p><strong>3.</strong><br>trust in Me, trust in Me,<br>I will never fail you, I will never fail you<br>I say trust in me,<br>come to Me, come to me,<br>come just as you are, come just as you are<br>I say trust in me</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(425, 'CHRIST IS MY ROCK', 'pending', NULL, '<p><strong>Refrain:</strong><br>Christ is my rock<br>My refuge my stronghold<br>Firm as the tree\'s root that clutches the land<br>He who has faith builds without worry<br>Not like the man who builds upon sand, i set my house on a solid foundation<br>Chrisy is my rock, the root of my souls recreation.</p>\n<p><strong>1.</strong><br>I know a man who loves to live free<br>He pitched his tent by the side of the sea<br>It stood near the surf and was washed by the spray<br>Till one day a wave came and washed it away</p>\n<p><strong>2.</strong><br>I know a man who loves to live high<br>He built his castle near up to the sky<br>Through summer and spring it stood pretty well<br>When winter\'s wind whistled it toppled and fell</p>\n<p><strong>3.</strong><br>I know a man a good to know<br>He built his house out of ice and of snow<br>In chill isolation his night work was done<br>Buyout nelted away with the warm morning sun</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(426, 'PRAISE TO THE LORD THE ALMIGHTY', 'pending', NULL, '<p><strong>1.</strong><br>Praise to the Lord, the Almighty, the King of creation!<br>O my soul, praise him, for he is our health and salvation!<br>All you who hear; now to his presence draw near,<br>join in profound adoration.</p>\n<p><strong>2.</strong><br>Praise to the Lord, let us offer our gifts to the alter.<br>Let not our sins and offences now cause us to faulter,<br>Christ the high priest, bids us all join in his feast,<br>Victims with him at the altar.</p>\n<p><strong>3.</strong><br>Praise to the Lord, O let all that is in us adore him,<br>All that has life and breath comes now rejoicing before him.<br>Let the amen sound from his people again,<br>As we here worship before him.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(427, 'LORD DISMISS US WITH THY BLESSING', 'pending', NULL, '<p><strong>1.</strong><br>Lord, dismiss us with your blessing;<br>Fill our hearts with joy and peace;<br>Let us each, your love possessing,<br>Triumph in redeeming grace:<br>O refresh us, O refresh us,<br>As we work to keep a-pace.</p>\n<p><strong>2.</strong><br>Thanks, we give and adoration<br>For your gospel\'s joyful sound:<br>May the fruits of this Communion<br>In our hearts and lives abound:<br>Ever faithful, ever faithful<br>To the truth may we be found.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(428, 'AS I KNEEL BEFORE YOU', 'pending', NULL, '<p><strong>Verse 1.:</strong><br>As I kneel before you, as I bow my head in pray\'r;take- this day, make - it Yours and fill me with your love.</p>\n<p><strong>Chorus:</strong><br>Ave maria, gratia plena.Dominus tecum, benedicta tu.</p>\n<p><strong>Verse 2.:</strong><br>All I have I give you, ev\'ry dream and wish are Yours;Mother of Christ, mother of mine, present them to my Lord.</p>\n<p><strong>Verse 3.:</strong><br>As I kneel before you, and I see your smiling face;Ev\'ry thought ev\'ry word, is lost in your embrace.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(429, 'I’LL SING A HYMN TO MARY (CHB 299)', 'pending', NULL, '<p><strong>VERSE 1:</strong><br>I’ll sing a hymn to Mary,<br>The Mother of my God,<br>The Virgin of all virgins,<br>Of David’s royal blood,<br>O teach me, holy Mary,<br>A loving song to frame,<br>When wicked men blaspheme thee,<br>To love and bless thy name.</p>\n<p><strong>VERSE 2:</strong><br>O noble tower of David<br>Of gold and ivory<br>The ark of God’s own promise,<br>The gate of Heav’n to me,<br>To live and not to love thee,<br>Would fill my soul with shame;<br>When wicked men blaspheme thee,<br>I’ll love and bless thy name.</p>\n<p><strong>VERSE 3:</strong><br>The saints are high in glory,<br>With golden crowns so bright<br>But brighter far is Mary,<br>Upon her throne of light,<br>Oh, that which God did give thee,<br>Let mortal ne’er disclaim;<br>When wicked men blaspheme thee<br>I’ll love and bless thy name.</p>\n<p><strong>VERSE 4:</strong><br>But in the crown of Mary,<br>There lies a wondrous gem,<br>As Queen of all the angels,<br>Which Mary shares with them,<br>“No sin hath e’er defied thee,”<br>So doth our faith proclaim,<br>When wicked men blaspheme thee<br>I’ll love and bless thy name.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(430, 'KINI MOMA FUN OLUWA', 'pending', NULL, '<p><strong>Chorus:</strong><br>Kini moma fun oluwa?<br>Ni idupe fun Ifere.</p>\n<p><strong>1.</strong><br>I gbati mob a ron tii I se re-re yin uh<br>I nu mi ma ndu-----shogbo<br>Ti mob a ri bi mose nse eshe<br>I nu-mi ko ki- ndu<br>To- mo bi a-re mi kpe.</p>\n<p><strong>2.</strong><br>Ni-nu I-fe le da wa<br>Le da wa ----oluwa<br>Ni-nu o-re oo-fe lé-ron-si<br>Jesu Christ O-lu-gba-la</p>\n<p><strong>3.</strong><br>Eronwa lówo ni-gbogbo i-gba<br>O-lo-rum mi O-luwanu E-to-ju-wa<br>Ge ge bi ba-ba re-re<br>O-lo-run mi O-luwa a-nu</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(431, 'RECEIVE THE GIFT', 'pending', NULL, '<p><strong>CHORUS:</strong><br>Re---ceive Receive the gift<br>Which we offer to you<br>Receive it, receive it for your honor, receive it, receive it for your honor<br>O God</p>\n<p><strong>1.</strong><br>We offer you bread and wine,<br>Take and sanctify O Lord<br>That we may be called the children of God,<br>Take and sanctify O Lord</p>\n<p><strong>2.</strong><br>We offer you our prayers,<br>Take and sanctify O Lord<br>That we may be called the children of God,<br>Take and sanctify O Lord</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'offertory'),
	(432, 'EKENE MARIA', 'pending', NULL, '<p><strong>Chorus:</strong><br>Ave Ave Ave Ave Ave Maria I juputara n’Amara Nne Ekene Ekene Ekene diri gi diri gi Maria Nwanyi Oma Ezigbo Nne</p>\n<p><strong>1.</strong><br>N’etiti umu Nwanyi niile I bu onye di ukwu, ibu onye di Ngozi yobar’anyi ayi yo eh yobar’anyi ayiyo eh dika na kana na Galili</p>\n<p><strong>2.</strong><br>Odi Ngozi odi Ngozi o di Ngozi O di Ngozi bu Nwafo Gi jesu onye bu mezaya bu Nwafo gi jesu Chukwu n’onwe ya bu Nwafo gi jesu Eze udo bu Nwafo gi jesu o g’achi bu Nwafo gi jesu chi chi chi chi chi chiwa chiwa chiwa chigi de chigi de chiwa mba niile</p>\n<p><strong>3.</strong><br>Maria I bu Nne nke chukwu nne nke onye nwa nyi I bu onye di Ngozi onye di ukwu mkpur’obi mo nuriwa na Chineke mmuo m go ri benu goribe nu gori benu na Dinwe nu agburu niile g’akpo mo ha g’akpo mo onye di Ngozi onye di ukwu</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(433, 'IJOBA ORUN', 'pending', NULL, '<p>Ijoba Orun lere oni Gbagbo o (2x)<br>Maje\'n Kuna baba, mumi de\'le o<br>Ki\'n makus\'ona bi-ee-fin, mumi de\'le o, Baba.</p>\n<p>IjobaOrun lere oni Gbagbo o (2x)<br>Maje\'n Kuna baba, mumi de\'le o<br>Ki\'n makus\'ona bi-ee-fin, mumi de\'le o, Baba.</p>\n<p>Sanukun baba, mumi de\'le o, majen rarinu baba<br>Mumi de\'le o<br>Majen tosi baba mumi de\'le o<br>Aiyeloja orunnile mumi de\'le o<br>Ki\'n makus\'ona bi-ee-fin, mumi de\'le o, Baba.<br>Mumi de\'le go mumi de\'le o baba.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(434, 'MUO NSO GBADATA', 'pending', NULL, '<p><strong>Chorus:</strong><br>Muo Nso gbadata, Muo Nso gbadata, eligwe meghe, meghe omeghewo</p>\n<p><strong>1.</strong><br>Muo Nso Muo Nso Muo Nso Bata ni imobi mo Biko doh, gbadata n\'ime ulo a gbadata ni ime Anyi Biko</p>\n<p><strong>2.</strong><br>Obibia Muo Nso nke Kristi kwe l\'anyi nkwa abiawo abiawo, obibia Muo Nso nke Kristi kwel\'anyi nkwa abiawo n\'ime ndu mo</p>\n<p><strong>3.</strong><br>Gbaba luya egwu egwu ekene egwu otito egwu ojija nma eh ewo ewo, gbaba luya egwu egwu ekene egwu otito egwu ojija nma eh ewo ewo</p>\n<p><strong>4.</strong><br>Otito dili Chukwu Nna<br>Otito dili Kristi<br>Otito dili Muo Nso<br>isee isee</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(435, 'SPIRIT OF GOD (CHB 215)', 'pending', NULL, '<p><strong>1.</strong><br>Spirit of God in the clear running water,<br>Blowing to greatness the trees on the hill,<br>Spirit of God in the finger of morning.</p>\n<p><strong>Chorus:</strong><br>Fill the earth, bring it to birth and blow<br>where you will,<br>Blow, blow, blow, till I be but the breath<br>of the Spirit blowing in me.</p>\n<p><strong>2.</strong><br>I saw the scar of a year that lay dying,<br>Hear the lament of a lone whip-poor-will,<br>Spirit of God, see that cloud crying,</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'holy_spirit'),
	(436, 'THE COMFORTER HAS COME', 'pending', NULL, '<p><strong>1.</strong><br>O spread the tidings \'round<br>Wherever man is found,<br>Wherever human hearts<br>and human woes abound;<br>Let every Christian tongue proclaim the joyful sound:<br>The Comforter has come!</p>\n<p><strong>Refrain:</strong><br>The Comforter has come, the Comforter has come!<br>The Holy Ghost from heaven, the Father\'s promise given;<br>O spread the tidings \'round wherever man is found:<br>The Comforter has come!</p>\n<p><strong>2.</strong><br>The long, long night is past, the morning breaks at last,<br>And hushed the dreadful wail and fury of the blast,<br>As o\'er the golden hills the day advances fast!<br>The Comforter has come!</p>\n<p><strong>3.</strong><br>Lo, the great King of kings with healing in His wings,<br>To every captive soul a full deliverance brings;<br>And through the vacant cells the song of triumph rings;<br>The Comforter has come!</p>\n<p><strong>4.</strong><br>O boundless Love divine! how shall this tongue of mine<br>To wondering mortals tell the matchless grace divine:<br>That I, a child of hell, should in His image shine!<br>The Comforter has come!</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'holy_spirit'),
	(437, 'SEE THE PARACLETE DESCENDING (CHB 214)', 'pending', NULL, '<p><strong>1.</strong><br>See the Paraclete descending,<br>Burning with celestial fire,<br>Grace and truth on Him attending,<br>Man with heavenly love inspire.</p>\n<p><strong>Chorus:</strong><br>Let us alleluia singing<br>Offer him grateful lays<br>He all heavenly graces bringing<br>Merits everlasting praise.</p>\n<p><strong>2.</strong><br>Timid souls no longer fearing,<br>Now the greatest danger scorn<br>Midst their sorrows persevering<br>Show themselves in Christ new born.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'holy_spirit'),
	(438, 'NDI BIARA UKA GA ANATA NGOZI', 'pending', NULL, '<p>Ndi biara uka ga anata ngozi, nata ngozi, nata ngozi<br>Ndi biara uka ga anata ngozi n\'aka onyenwanyi,<br>natakwa ebere n\'aka chineke onye zoro ha,<br>N\'ihi na ha so na onu ogugu, Ndi n\'acho dinwenu.</p>\n<p><strong>1.</strong><br>O bu Dinwenu nwe uwa, n\'ihe juru n\'ime ya,<br>uwa nke a na ndi bi n\'elu ya.<br>ka ya wukwa si ri ya, na elu osimiri.</p>\n<p><strong>2.</strong><br>onye ga arigo ugwu nke onyenweanyi<br>Onye ga abata n\'ime ulo nso ya<br>Onye omume ya di nso, onye obi ya di ocha, onyen\'etinyeghi uche ya n\'umu ihe n\'enweghi isi, onye na anaghi anurummadu ibe ya iyi aghugho<br>O ga anata ngozi na aka Onyenweanyi nata kwa ebere, n\'aka Chineke onye zoroha.<br>osorola n\'igwe umu mmadu n\'acho ya, ndi n\'acho ihuchineke jacob.</p>\n<p><strong>3.</strong><br>Onu uzo ama, bulienu isi unu elu<br>bulienu elu, onu uzo okpu, Ka eze di otito bata.<br>Onyekwa bu Eze ebube a ?<br>O bu dinwenu dike di ike, Dinwenu nke siri ike n\'agha<br>Onu uzo ama, bulienu isi unu elu, bulienu elu, onu uzookpu, ka Eze di ebube bata<br>Onye ka o bu Eze abube a?<br>Dinwenu nke igwe agha, O bu ya bu Eze ebube a!</p>\n<p><strong>4.</strong><br>Otito diri Nna na Nwa na Muo Nso, Otu o di na mbun\'ugbua, na mgbe nile, n\'uwa ebigh\' ebi.<br>Amen</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(439, 'CROWN HIM', 'pending', NULL, '<p>Crown Him, crown Him,<br>Christ our Lord and King!<br>Through all ages let His praises ring!<br>Glory, honour to His name we’ll bring<br>Now and for evermore.</p>\n<p>We will crown Him, we will crown Him;<br>In the glory land we’ll crown Him King!<br>Crown Him, we will crown Him—<br>Loud let His praises ring!</p>\n<p>Hail Him, hail Him, angel hosts on high,<br>To His throne with harps<br>and songs draw nigh;<br>Let all nations join the joyful cry:<br>“Crown Him, the King of kings!”</p>\n<p>We will crown Him, we will crown Him;<br>In the glory land we’ll crown Him King!<br>Crown Him, we will crown Him—<br>Loud let His praises ring!</p>\n<p>He is Victor, He has conquered sin;<br>Let His Spirit rule our hearts within;<br>In His name the vict’ry we shall win:<br>Crown Him for evermore.</p>\n<p>We will crown Him, we will crown Him;<br>In the glory land we’ll crown Him King!<br>Crown Him, we will crown Him—<br>Loud let His praises ring!</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(440, 'LIFT UP YOUR HEADS, YE MIGHTY GATES', 'pending', NULL, '<p><strong>1.</strong><br>Lift up your heads, ye mighty gates; behold, the King of glory waits; the King of kings is drawing near; the Savior of the world is here!</p>\n<p><strong>2.</strong><br>Fling wide the portals of your heart; make it a temple, set apart from earthly use for heaven\'s employ, adorned with prayer and love and joy.</p>\n<p><strong>3.</strong><br>Redeemer, come, with us abide; our hearts to thee we open wide; let us thy inner presence feel; thy grace and love in us reveal.</p>\n<p><strong>4.</strong><br>Thy Holy Spirit lead us on until our glorious goal is won; eternal praise, eternal fame be offered, Savior, to thy name!</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(441, 'ORA KENEE IKE JESU', 'pending', NULL, '<p><strong>VERSE 1:</strong><br>Ora Kenee Ike Jesu<br>Ka ndi muozi ya da weputa<br>okpu nke Eze bia mee ya, bia mee ya eze Ora</p>\n<p><strong>Chorus:</strong><br>Bia mee ya<br>Bia mee ya, bia mee ya bia mee ya<br>Bia mee ya Eze ora</p>\n<p><strong>VERSE 2:</strong><br>Mee ya Eze ndi Oma chukwu<br>N’eguzoro n’iru ya, too ya bu onye unu soro<br>Bia mee ya Eze ora</p>\n<p><strong>VERSE 3:</strong><br>Umu Israel Orotalu<br>Ndi agbaputalu, kenee nu onye nzoputa<br>Bia mee ya Eze Ora.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(442, 'MAJESTY', 'pending', NULL, '<p>Majesty, worship His majesty<br>Unto Jesus be all glory, honor and praise,<br>Majesty, kingdom authority<br>Flow from His throne, unto His own<br>His Anthem raise</p>\n<p>So exalt, lift up on high, the name of Jesus<br>Magnify, come glorify Christ Jesus the King<br>Majesty, worship His majesty</p>\n<p>Jesus who died, now glorified<br>King of all kings</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(443, 'COME THOU ALMIGHTY KING', 'pending', NULL, '<p><strong>1.</strong><br>Come, Thou Almighty King,<br>Help us Thy name to sing,<br>Help us to praise.<br>Father, all glorious,<br>O’er all victorious,<br>Come, and reign over us,<br>Ancient of Days.</p>\n<p><strong>2.</strong><br>Come, Thou incarnate Word,<br>Gird on Thy mighty sword,<br>Our prayer attend:<br>Come, and Thy people bless,<br>And give Thy word success;<br>Spirit of holiness,<br>On us descend.</p>\n<p><strong>3.</strong><br>Come, holy Comforter,<br>Thy sacred witness bear<br>In this glad hour:<br>Thou who Almighty art,<br>Now rule in every heart,<br>And ne’er from us depart,<br>Spirit of power.</p>\n<p><strong>4.</strong><br>To Thee, great One in Three,<br>Eternal praises be<br>Hence evermore.<br>Thy sov’reign majesty<br>May we in glory see,<br>And to eternity love and adore</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(444, 'NSO NSO (EMMA NWATU)', 'pending', NULL, '<p>Nso Nso Nso, Nso Nso Nso<br>Osebuluwa I-di N-so<br>Osebuluwa Chukwu nk\'igwe ndi agha<br>Ebube gi juputara Eluigwe n\'ala<br>Osebuluwa Chukwu nk\'igwe ndi agha<br>Ebube gi juputara Eluigwe n\'ala</p>\n<p><strong>REFRAIN:</strong><br>Etu esi tie ya n\'igwe ( Hosanna Hosanna Hosanna)<br>Tie ya n\'uwa, ka ndi mmadu mara eh, na chukwu di nso, ndi mmuoma n\'eti eh!<br>Ngwanu k\'anyi tie Hossana Hossana n\'elu kasi elu.</p>\n<p><strong>2.</strong><br>di Ngozi bu onye biara n\'aha onye-nwe-anyi<br>di Ngozi bu onye biara n\'aha onye-nwe-anyi<br>Etu esi tie ya n\'igwe ( Hosanna Hosanna Hosanna)<br>Tie ya n\'uwa, ka ndi mmadu mara eh, na chukwu di nso, ndi mmuoma n\'eti eh!<br>Ngwanu k\'anyi tie Hossana Hossana n\'elu kasi elu.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'sanctus'),
	(445, 'WE LONG FOR YOU, O LORD', 'pending', NULL, '<p><strong>1.</strong><br>We long for you, O Lord,<br>We long for you, O Lord,<br>Come, make us one with you in love,<br>We long for you, O Lord.</p>\n<p><strong>2.</strong><br>We cannot rest, O Lord,<br>We cannot rest,<br>O Lord, come, Lamb of God, and give us peace,<br>We cannot rest, O Lord.</p>\n<p><strong>3.</strong><br>We hunger for you, O Lord,<br>We hunger for you, O Lord,<br>Come, feed us now with living bread,<br>We hunger for you, Lord.</p>\n<p><strong>4.</strong><br>Your flesh is strength, O Lord,<br>Your flesh is strength, O Lord,<br>Come, holy strong One, make us strong,<br>Your flesh is strength, O Lord.</p>\n<p><strong>5.</strong><br>You live in us, O Lord,<br>You live in us, O Lord,<br>To be our Way and Truth and Life,<br>You live in us, O Lord.</p>\n<p><strong>6.</strong><br>You live in others, Lord,<br>You live in others, Lord,<br>Our love of them is love of you,<br>You live in others, Lord.</p>\n<p><strong>7.</strong><br>You love through us, O Lord,<br>You love through us, O Lord,<br>We are your heart and hands and voice,<br>You love through us, O Lord</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(446, 'OGE ERUGO', 'pending', NULL, '<p><strong>CHORUS:</strong><br>Oge erugo ee. oge rugo ee, Umunna zukotonu n\'iru  alter Oge\'rugo k\'anyi sekpuere Osebutuwa, Chukwu Onye n\'enye udo</p>\n<p><strong>VERSES:</strong><br>(Sop): Bianu sekpuere Chukwu, Bianu kpoo isi ala nye ya.<br>Bianu kpoo isi ala nye ya.<br> Bianu Ka anyi too chukwu<br>Bianu were ukwe too ya<br>Bianu kpoo isi ala nye ya.<br> Bianu ka anyi kelee chukwu<br>Maka ihe ona emere anyi<br>Bianu kpoo isi ala nye ya.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(447, 'BECAUSE HE LOVES US', 'pending', NULL, '<p><strong>1.</strong><br>Because He loves us<br>sinful though we are,<br>With a crescendo, we shall praise His name</p>\n<p><strong>Chorus:</strong><br>O join us our brothers and sisters<br>In praising God for His love and mercy<br>Join us all Ye works of the Lord<br>In adoration in His Holy place</p>\n<p><strong>2.</strong><br>He is a Father who is always near<br>O what a Father with a gracious heart</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(448, 'ONDU MENYINYALO', 'pending', NULL, '<p>Ondu menyinyalo<br>Ondu menyinyalo<br>menyinyalo  menyinyalo<br>Ondu menyinyalo menyinyalo</p>\n<p>Christi menyinyalo<br>Christi menyinyalo<br>Christi menyinyalo menyinyalo menyinyalo</p>\n<p>Ondu menyinyalo<br>Ondu menyinyalo<br> menyinyalo menyinyalo Ondu menyinyalo menyinyalo</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'kyrie'),
	(449, 'OMALA EYI OJO', 'pending', NULL, '<p>O-ma-la O-ma-la e-yi O-jo,  u-we-ki-a kebie-nei-leri-nyo,<br>che-ju mo mi wa</p>\n<p>O-ma-la O-ma-la e-yi O-jo,  u-we-ki-a kebie-nei-leri-nyo,<br>che-ju mo mi wa</p>\n<p>O-ma-la_  O-ma-la e-yi O-jo, u-we_ ki -a kebie-ne i-le ri- nyo,<br>De - be bo nwu wa.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'agnus_dei'),
	(450, 'BOUNDLESS SEA OF LOVE', 'pending', NULL, '<p>On the great day of that supper Jesus assembled the apostles<br>and He fed them in the great Eucharist<br>His body and His blood.</p>\n<p>I can hear you my dear saviour calling upon me with great love<br>To partake freely in this great supper the banquet of the Lord</p>\n<p><strong>CHORUS:</strong><br>How happy oh how happy are we for we have been called to this supper<br>do I deserve this marvelous love am I to claim it my dear Lord<br>amen I don\'t know what to say, hold me in your boundless sea of love</p>\n<p><strong>2.</strong><br>When you feed me in this supper given to Angels in heaven<br>you prepare me for the last days at the table of the Lamb</p>\n<p>When you feed  me your own body and when you feed me your own blood<br>you bestow Grace\'s upon me in a boundless son of love</p>\n<p><strong>3.</strong><br>I behold you my dear Saviour offered to free me from bondage<br>I adore you with my whole heart as the victim and the Priest</p>\n<p>I receive you oh my dear Jesus ever proclaiming your own death and your rising from the dead oh Lord your coming again</p>\n<p><strong>4.</strong><br>I will thank you my dear Jesus ever to praise you at all times<br>I  will not fail to adore you as my Saviour and my God</p>\n<p>To the Father be all glory, glory to Jesus His own son to the Spirit be the glory its a boundless sea of love</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(451, 'ALL PRAISE AND GLORY TO THE LORD', 'pending', NULL, '<p>All praise and glory to the Lord,<br>Forever be his name adored,<br>He guideth all great and small,<br>Most merciful and just to all.<br>Let every nation rise and sing the praises of the mighty King<br>Who rules below, who reigns above,<br>Supreme in power, Sublime in love.</p>\n<p><strong>Chorus:</strong><br>Praise and glory to the Lord, Allelulia Amen<br>Ever be his name adored, Alleluia Amen.<br>Praise  and  glory  to  the  Lord,  Allelulia  Amen<br>Ever  be  his  name  adored,  Alleluia  Amen.<br>Alleluia ! Alleluia !! 2x<br>Praise and glory to the Lord, Allelulia Amen.<br>Allelulia, Praise the Lord 2x<br>Ever be his name adored, Alleluia Amen<br>Amen Amen<br>Praise and glory to the Lord, Allelulia.  Amen, Amen.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(452, 'STANDING ON THE PROMISES OF GOD (CHB 353)', 'pending', NULL, '<p><strong>1.</strong><br>Standing on the promises of Christ my King,<br>Through eternal ages let His praises ring;<br>Glory in the highest, I will shout and sing,<br>Standing on the promises of God.</p>\n<p><strong>Chorus:</strong><br>Stand…ing…stand…ing,…<br>Standing on the promises of God my Saviour;<br>Stand…ing…stand…ing,…<br>I\'m standing on the promises of God.</p>\n<p><strong>2.</strong><br>Standing on the promises cannot fail,<br>When the howling storms<br>of doubt and fear assail,<br>By the living Word of God I shall prevail,<br>Standing on the promises of God.</p>\n<p><strong>3.</strong><br>Standing on the promises I now can see<br>Prefect, present cleansing in the blood for me;<br>Standing in the liberty where Christ makes<br>free,<br>Standing on the promises of God.</p>\n<p><strong>4.</strong><br>Standing on the promises of Christ the Lord,<br>Bound to Him eternally by love\'s strong word<br>Overcoming daily with the Spirit\'s sword,<br>Standing on the promises of God.</p>\n<p><strong>5.</strong><br>Standing on the promises I cannot fall,<br>Listening every moment to the Spirit\'s call,<br>Resting in my Saviour as my all in all,<br>Standing on the promises of God.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'dismissal'),
	(453, 'LORD GOD ALMIGHTY', 'pending', NULL, '<p><strong>1.</strong><br>Holy, holy, holy! Lord God almighty!<br>Early in the morning our song shall rise to thee;<br>Holy, holy, holy! merciful and mighty!<br>God in three persons, blessed Trinity!</p>\n<p><strong>2.</strong><br>Holy, holy, holy! all the saints adore thee.<br>Casting down their golden crowns<br>around the glassy sea;<br>Cherubim and seraphim falling down<br>before thee,<br>Which wert, and art and evermore shalt be.</p>\n<p><strong>3.</strong><br>Holy, holy, holy! Lord God almighty!<br>All thy works shall praise thy name, on earth,<br>and sky, and sea;<br>Holy, holy, holy! merciful and mighty!<br>God in three persons, blessed Trinity.</p>\n<p><strong>4.</strong><br>Holy, holy, holy! though the darkness hide thee,<br>Though the eye of sinful man thy glory<br>may not see,<br>Only thou art holy, there is none beside thee<br>Perfect in power, in love, and purity.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(454, 'ALL GLORY BELONGS TO YOU', 'pending', NULL, '<p><strong>Chorus:</strong><br>All glory belongs to you, all glory belongs to you Holy Trinity, o yes God is three o yes God is one there is one God in three persons all glory belongs to you Holy Trinity</p>\n<p><strong>1.</strong><br>To you be all praise all Thanksgiving for ever o blessed Trinity</p>\n<p><strong>2.</strong><br>In you there is hope and salvation in you glory o blessed Trinity</p>\n<p><strong>3.</strong><br>Hear us when we pray  God the Father son and spirit o blessed Trinity</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(455, 'OTITO NA NSOPURU', 'pending', NULL, '<p>Otito otito otito na nsopuru kanyi na ebunye Gi Chukwu Nna na Nwa na Muo  nso. Ato, ato n\'otu di ngozi</p>\n<p>Uwa Nile donu aha Chineke ebube, werenu ukwe onu bulie aha ya elu, werenu ukwe onu bulie aha ya elu, bulie aha ya bulie aha ya bulie aha ya elu, sekpuere nu ya, sekpuere nu ya</p>\n<p>N\'ezie Person ato n\'otu Chineke do omimi, Kasia kachasi Kasia kachasi uche madu (odikwazi aso kwesi nsopuru) odikwazi aso odikwazi aso kwesi nsopuru na otito nebe ihe Nile okere eke di</p>\n<p>Kanyi kelenu<br>Kanyi kelenu Onye okike<br>Kanyi kelenu<br>Kanyi kelenu Onye nzoputa<br>Kanyi kele ya<br>Bianu kanyi kelenu Onye ndokwa kele Onye ndokwa nke ihe Nile di nokpuru anyanwu Chukwu ee Chukwu na enye ndu Chukwu na enye ndu Chukwu na enye ndu odogwu</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(456, 'SING PRAISE TO THE LIVING GOD', 'pending', NULL, '<p><strong>1.</strong><br>Sing praise to the living God, Glory Halleluia.<br>Come adore the living God, Glory Halleluia,<br>Though sun and moon may pass away,<br>his word will ever stay<br>His power is forevermore, Glory Halleluia.</p>\n<p><strong>Chorus:</strong><br>Glory to the Trinity, the undivided unity.<br>The Father; Son and Spirit One,<br>From whom all life and goodness come.</p>\n<p><strong>2.</strong><br>To the living God we sing, Glory, Halleluia,<br>Let our love and praises ring, Glory, Halleluia.<br>To His sons, He always<br>gives His mercy and His love.<br>Praise Him now forevermore, Glory, Halleluia.</p>\n<p><strong>3.</strong><br>To the God who cannot die, Glory, Halleluia<br>To the living God we cry, Glory, Halleluia<br>He promised to be with us<br>and He lives in everyone<br>Love Him now forevermore, Glory, Halleluia.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'communion'),
	(457, 'WHEN THE SAINTS GO MARCHING IN', 'pending', NULL, '<p><strong>1.</strong><br>I am just alone some travler;<br>Through this big,wild world of sin;<br>Want to join that grand procession,<br>When the saints go marching in.</p>\n<p><strong>Chorus:</strong><br>Oh when the saints go marching in,2×<br>Lord I want to be in that number, when the saints go marching in.</p>\n<p><strong>2.</strong><br>All my folks have gone before me;<br>All my friends and all my kind;<br>But I\'ll meet with them up younder,<br>When the saints go marching in.</p>\n<p><strong>3.</strong><br>Come and join me in my journey;<br>Cause it\'s time that we begin;<br>And we\'ll be there for that judgment,<br>When the saints go marching in.</p>', '2026-07-24 13:53:06', '2026-07-24 13:53:06', 'entrance'),
	(458, 'TAKE MY LIFE AND LET IT BE', 'Frances Ridley Havergal', NULL, '<p><strong>1.</strong></p><p>Take my life and let it be</p><p>consecrated, Lord, to thee.</p><p>Take my moments and my days;</p><p>let them flow in endless praise,</p><p><strong>2.</strong></p><p>Take my hands and let them move</p><p>at the impulse of thy love.</p><p>Take my feet and let them be</p><p>swift and beautiful for thee.</p><p><strong>3.</strong></p><p>Take my voice and let me sing</p><p>always, only, for my King.</p><p>Take my lips and let them be</p><p>filled with messages from thee.</p><p><strong>4.</strong></p><p>Take my silver and my gold;</p><p>not a mite would I withhold.</p><p>Take my intellect and use</p><p>every power as thou shalt choose.</p><p><strong>5.</strong></p><p>Take my will and make it thine;</p><p>it shall be no longer mine.</p><p>Take my heart it is thine own;</p><p>It shall be Thy royal throne.</p>', '2026-07-24 13:53:06', '2026-08-14 07:45:39', NULL),
	(459, 'KU TASHI SAI KUZO', 'Pending', NULL, '<p>Ku tashi sai kuzo, Jesu ya na kira.</p><p>Karbi shi, ci jikin shi.</p><p>Abinchi ne me kyau</p><p><br></p><p>Mai salama, mai iko, mai kauna ya na kiran mu.</p><p>Mu karbi shi, mu zabe shi.</p><p>Mai rayuwa, mai ceto.</p><p><br></p><p>Ya Kristo, ya Kristo,</p><p>Gamu munyi lefi,</p><p>Ka wanke mu, da jinin sa,</p><p>Mu samu lafiya har abada</p><p><br></p><p>Godiya ni na ke, godiya ni na ke,</p><p>Ga godiya abaki na, don Yesu na ya bani rai.</p><p><br></p><p>Ku tashi sai kuzo, Jesu ya na kira.</p><p>Karbi shi, ci jikin shi.</p><p>Abinchi ne me kyau</p>', '2026-07-24 14:20:48', '2026-07-24 14:20:48', 'Communion'),
	(460, 'EYEN ERONG ABASI', 'Pending', NULL, '<p>Eyen erong</p><p>Abasi emi...emende</p><p>M\'i diok\'m kpo</p><p>Ererim bot efep&nbsp;</p><p>tua tua yi mbom&nbsp;</p><p>Tua yin bom tua yin bom&nbsp;</p><p><br></p><p>Eyen erong</p><p>Abasi emi...emende</p><p>M\'i diok\'m kpo</p><p>Ererim bot efep&nbsp;</p><p>tua tua yi mbom&nbsp;</p><p>Tua yin bom tua yin bom&nbsp;</p><p><br></p><p>Eyen erong&nbsp;</p><p>Abasi emi...emende</p><p>M\'i diok\'m kpo</p><p>Erim bot efep&nbsp;</p><p>Noyin noyin emem</p><p>Noyin emem noyin emem</p>', '2026-07-24 14:21:38', '2026-07-24 14:21:38', 'Agnus Dei'),
	(461, 'Ebianlemhan Toha mhanlen', 'HPC Anyanwu', NULL, '<p>Ebianlemhan ebianlemhan to ha mhanlen&nbsp;</p><p>Ebianlemhan ebianlemhan to ha mhanlen&nbsp;</p><p>Toha mhanlen&nbsp;</p><p>Toha mhanlen&nbsp;</p><p>Ebianlemhan to ha mhanlen&nbsp;</p><p><br></p><p>Kristi toha mhanlen&nbsp;</p><p>Kristi toha mhanlen&nbsp;</p><p>Kristi toha mhanlen&nbsp;</p><p>Toha mhanlen Kristi toha mhanlen&nbsp;</p><p><br></p><p>Toha mhanlen, to ha mhanlen&nbsp;</p><p>Toha mhanlen&nbsp;</p><p><br></p><p><br></p><p>Ebianlemhan ebianlemhan to ha mhanlen&nbsp;</p><p>Ebianlemhan ebianlemhan to ha mhanlen</p><p>Toha mhanlen&nbsp;</p><p>Toha mhanlen&nbsp;</p><p>Ebianlemhan to ha mhanlen</p>', '2026-07-24 14:22:38', '2026-07-24 14:22:38', 'Kyrie'),
	(462, 'Kyrie', 'Chinanu Okoli', NULL, '<p>Oh Lord have mercy on us for we have sinned grievously against you</p><p>O Lord have mercy</p><p><br></p><p>Christ you who are seated at the right hand of the Father have mercy on us</p><p>Christ have mercy&nbsp;</p><p><br></p><p>Through our fault through our most grievous fault have&nbsp;mercy on us&nbsp;</p><p>O Lord have mercy</p><p><br></p>', '2026-08-10 09:15:31', '2026-08-10 09:15:31', 'Kyrie'),
	(463, 'GLORy TO GOD', 'Momoh St Gabriels', NULL, '<p>Glory to God, glory to God, glory to God to God to God</p><p>Glory to God, glory to God, glory to God in the highest&nbsp;</p><p><br></p><p>1 And on earth peace to men, peace to men of goodwill</p><p>We praise you, we bless you</p><p>we bless and worship you, we glorify your great name, we give you thanks O lord</p><p><br></p><p>2 Lord God heavenly king, lord God almighty father&nbsp;</p><p>we praise you, we bless you&nbsp;</p><p>Jesus Christ son of God, only son of the father&nbsp;</p><p>Lord God lamb of God</p><p><br></p><p>3 Have mercy in us Lord&nbsp;</p><p>You who takes away sins</p><p>the sins of all mankind&nbsp;</p><p>Have mercy on us Lord</p><p>You who takes away sins</p><p>receive our prayers O lord</p><p><br></p><p>4 Have mercy on us Lord</p><p>You who sits at the right hand</p><p>Of the father in heaven&nbsp;</p><p>You alone lord Jesus&nbsp;</p><p>You alone are holy</p><p>You alone are the most high&nbsp;</p><p><br></p><p>5 You alone lord Jesus&nbsp;</p><p>with the holy spirit</p><p>in the father\'s glory</p><p>Amen, amen amen, amen</p><p><br></p>', '2026-08-10 09:16:37', '2026-08-10 09:16:37', 'Gloria'),
	(464, 'ONLY SAY A WORD', 'Ifeanyi Eze', NULL, '<p>Lord I am not</p><p>Worthy to receive thee</p><p>I am not worthy Lord</p><p>Only say a word</p><p>And my soul shall live</p><p>Only say a word</p><p>And my soul shall live</p><p>&nbsp;</p><p>1. You are the bread that was broken for the life of the poor</p><p>&nbsp;That we may have life in Abundance</p><p>Come into me, and my soul shall live.</p><p>&nbsp;</p><p>2. Remember that I am your handmade o lord my God</p><p>&nbsp;Feed me with your body and blood</p><p>And my soul shall live</p><p>&nbsp;</p><p>3. Rejoice rejoice rejoice in the Lord</p><p>Exult exult oh you just</p><p>O come, ring out your joy</p><p>Oh you upright of heart, ring out your joy</p><p>O come, ring out your joy</p><p>Oh you upright of heart.</p><p><br></p>', '2026-08-10 09:18:43', '2026-08-10 09:18:43', 'Communion'),
	(465, 'O GOD OUR HELP IN AGES PAST', 'Pending', NULL, '<p>1. O God, our help in ages past,</p><p>&nbsp;Our hope for years to come,</p><p>Our shelter from the stormy blast,</p><p>&nbsp;And our eternal home.</p><p><br></p><p>2. Under the shadow of Thy throne</p><p>&nbsp;Thy saints have dwelt secure;</p><p>Sufficient is Thine arm alone,</p><p>&nbsp;And our defence is sure.</p><p><br></p><p>3. Before the hills in order stood,</p><p>&nbsp;Or earth received her frame,</p><p>From everlasting Thou art God,</p><p>&nbsp;To endless years the same.</p><p><br></p><p>4. A thousand ages in Thy sight</p><p>&nbsp;Are like an evening gone;</p><p>Short as the watch that ends the night</p><p>&nbsp;Before the rising sun.</p><p><br></p><p>5. Time, like an ever-rolling stream,</p><p>&nbsp;Bears all its sons away;</p><p>They fly forgotten, as a dream</p><p>&nbsp;Dies at the opening day.</p><p><br></p><p>6. O God, our help in ages past,</p><p>&nbsp;Our hope for years to come,</p><p>Be Thou our guard while life shall last,</p><p>&nbsp;And our eternal home.</p>', '2026-08-10 09:20:27', '2026-08-10 09:20:27', 'Dismissal'),
	(466, 'Control', 'Unplugged', NULL, '<p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">[Verse 1]</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">Here I am</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">All my intentions</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">All my obsessions</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">I want to lay them all down</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">In Your hands</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">Only Your love is vital</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">And though I\'m not entitled</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">Still You call me Your child</span></p><p><br></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">[Chorus]</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">God You don\'t need me</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">But somehow You want me</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">Oh how You love me</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">Somehow that frees me</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">To take my hands off of my life</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">And the way it should go</span></p><p><br></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">[Verse 2]</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">I\'ve had plans</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">Shattered and broken</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">There\'s been these things I have hoped in</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">And they fell through my hands</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">You have plans</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">To rеdeem and restore me</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">You\'rе behind and before me</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">Oh help me believe</span></p>', '2026-08-11 11:20:55', '2026-08-11 11:20:55', 'Offertory'),
	(467, 'We shall go up into God\'s house', 'Jude Orakwe', NULL, '<p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">CHORUS</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">We shall go up into God\'s house with sound of joy,</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">We shall go into the house of the Lord.</span></p><p><br></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">VERSE 1</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">I rejoiced when I heard them say "Let us go to God\'s house"</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">And now our feet are standing within your gates, O Jerusalem.</span></p><p><br></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">VERSE 2</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">Jerusalem is built as a city strongly compact</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">It is there that the tribes go up, The tribes of the Lord.</span></p><p><br></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">VERSE 3</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">For Israel\'s law it is There to praise the Lord\'s name</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">There were set the thrones of judgement Of the house of David.</span></p><p><br></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">VERSE 4</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">For the peace of Jerusalem pray: "Peace be to your homes!"</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">May peace reign in your walls, In your palaces, peace!"</span></p><p><br></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">VERSE 5</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">For love of my brethren and friends, I say: "Peace upon you!"</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">For love of the house of the Lord I will ask for your good.</span></p>', '2026-08-14 07:38:22', '2026-08-14 07:38:22', 'Entrance'),
	(468, 'Kristi Dinwenu', 'Rev. Msgr. Cyril Ezenduka', NULL, '<p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">REFRAIN</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">Kristi Dinwenu, Ụkọchukwu ebebe,</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">naehunye achịcha na mmanya, dị ka Melkizedek.</span></p><p><br></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">VERSE 1</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">Dinwenu gwara Nnam ukwu, nọdụ ala n\'aka nri m,</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">Aga m edote ndị iro gị n\'okpuru ụkwụ gị.</span></p><p><br></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">VERSE 2</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">Onye nwe anyị gaesi na Zayọn zite mkpọ eze nke ike gị,</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">Chịwa ọchịchị, n\'etiti ndị iro gị.</span></p><p><br></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">VERSE 3</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">Eze, site n\'ụbọchị a mụrụ gị, n\'elu ugwu dị nsọ,</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">Tupu chi efo, esirim n\'afọ m mụta gị.</span></p><p><br></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">VERSE 4</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">Onye nwe anyị ṅụrụ iyi, Ọ ma echegharị,</span></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(38, 48, 42);">I bu Ụkọchukwu ebebe, dị ka Melkizedek, mgbe ochie.</span></p>', '2026-08-14 07:42:11', '2026-08-14 07:42:11', 'Consecration'),
	(469, 'In Christ there is no east or west', 'John Oxenham', NULL, '<p>1. In Christ there is no east or west,</p><p>In him no south or north,</p><p>But one great fellowship of love</p><p>Thru\'out the whole wide Earth.</p><p><br></p><p>2. In him shall true hearts ev\'rywhere</p><p>Their high communion find.</p><p>His service is the golden cord</p><p>Close binding humankind.</p><p><br></p><p>3. Join hands, then, children of the faith,</p><p>Whate\'er your race may be!</p><p>Who serves my Father as a child</p><p>Is surely kin to me.</p><p><br></p><p>4. In Christ now meet both east and west,</p><p>In him meet south and north;</p><p>All Christly souls are one in him,</p><p>Thru\'out the whole wide Earth.</p>', '2026-08-14 07:44:06', '2026-08-14 07:44:06', 'Communion');
